// =====================================================
// هش کردن رمز عبور (SHA-256) با Web Crypto API
// =====================================================

// =====================================================
// پیاده‌سازی مستقل SHA-256 (بدون نیاز به Web Crypto API)
// چون crypto.subtle فقط روی HTTPS یا localhost کار می‌کند
// و این سایت ممکن است به‌صورت فایل محلی یا HTTP ساده باز شود
// =====================================================

function stlpSha256Hex(message) {

    function rightRotate(value, amount) {
        return (value >>> amount) | (value << (32 - amount));
    }

    const mathPow = Math.pow;
    const maxWord = mathPow(2, 32);
    const lengthProperty = "length";
    let i, j;
    let result = "";

    const words = [];
    const asciiBitLength = message[lengthProperty] * 8;

    let hash = stlpSha256Hex.h = stlpSha256Hex.h || [];
    const k = stlpSha256Hex.k = stlpSha256Hex.k || [];
    let primeCounter = k[lengthProperty];

    const isComposite = {};

    for (let candidate = 2; primeCounter < 64; candidate++) {
        if (!isComposite[candidate]) {
            for (i = 0; i < 313; i += candidate) {
                isComposite[i] = candidate;
            }
            hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
            k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
        }
    }

    hash = hash.slice(0, 8);

    message += "\x80";

    while ((message[lengthProperty] % 64) - 56) {
        message += "\x00";
    }

    for (i = 0; i < message[lengthProperty]; i++) {
        j = message.charCodeAt(i);
        if (j >> 8) return "";
        words[i >> 2] |= j << (((3 - i) % 4) * 8);
    }

    words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
    words[words[lengthProperty]] = (asciiBitLength);

    for (j = 0; j < words[lengthProperty]; ) {

        const w = words.slice(j, j += 16);
        const oldHash = hash;

        hash = hash.slice(0, 8);

        for (i = 0; i < 64; i++) {

            const w15 = w[i - 15];
            const w2 = w[i - 2];

            const a = hash[0];
            const e = hash[4];

            const temp1 =
                hash[7] +
                (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25)) +
                ((e & hash[5]) ^ ((~e) & hash[6])) +
                k[i] +
                (
                    w[i] = (
                        i < 16
                            ? w[i]
                            : (
                                w[i - 16] +
                                (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) +
                                w[i - 7] +
                                (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
                            ) | 0
                    )
                );

            const temp2 =
                (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) +
                ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));

            hash = [(temp1 + temp2) | 0].concat(hash);
            hash[4] = (hash[4] + temp1) | 0;

        }

        for (i = 0; i < 8; i++) {
            hash[i] = (hash[i] + oldHash[i]) | 0;
        }

    }

    for (i = 0; i < 8; i++) {
        for (j = 3; j + 1; j--) {
            const b = (hash[i] >> (j * 8)) & 255;
            result += ((b < 16) ? "0" : "") + b.toString(16);
        }
    }

    return result;

}

async function stlpHashPassword(password) {

    return stlpSha256Hex(String(password || ""));

}


