function loadEmployees() {

    try {

        return JSON.parse(
            localStorage.getItem("stlp_employees") || "[]"
        );

    } catch (error) {

        return [];

    }

}


function saveEmployees(list) {

    localStorage.setItem(
        "stlp_employees",
        JSON.stringify(list)
    );

}


// فقط چند فیلدِ مرخصیِ یک کارمند را اتمیک روی سرور تغییر می‌دهد
// (به‌جای خواندن کل stlp_employees و نوشتنِ کاملِ آن با saveEmployees،
// که برای letters.html دیگر مجاز نیست — رجوع شود به توضیحِ
// stlp_employees در erp/server/lib/permissions.js)
function stlpApplyEmployeeLeaveEffectSync(employeeId, effect, requestId) {

    try {

        const xhr = new XMLHttpRequest();
        xhr.open("POST", "/api/employees/apply-leave-effect", false);
        xhr.setRequestHeader("Content-Type", "application/json");
        xhr.setRequestHeader("Accept", "application/json");
        xhr.send(JSON.stringify({ employeeId: employeeId, effect: effect, requestId: requestId }));

        if (xhr.status >= 200 && xhr.status < 300) {

            // کشِ محلیِ storage-sync.js را هم با همین تغییر هماهنگ
            // می‌کنیم تا اگر همین تب بلافاصله loadEmployees() را دوباره
            // صدا بزند، مانده‌ی به‌روزشده را ببیند (نه نسخه‌ی قدیمیِ
            // بارگذاریِ اولیه‌ی صفحه) — بدون این‌که خودِ این کار یک
            // نوشتنِ دیگر روی سرور بفرستد (چون قبلاً با موفقیت نوشته شد).
            if (window.__stlpServerStorage && typeof window.__stlpServerStorage.refreshKey === "function") {

                try {

                    const employees = JSON.parse(localStorage.getItem("stlp_employees") || "[]");
                    const idx = employees.findIndex(function(e) { return e && e.id === employeeId; });

                    if (idx >= 0) {
                        Object.assign(employees[idx], effect);
                        window.__stlpServerStorage.refreshKey("stlp_employees", JSON.stringify(employees));
                    }

                } catch (cacheError) {
                    console.error("⚠️ همگام‌سازیِ کشِ محلیِ کارمندان ناموفق بود:", cacheError);
                }

            }

            return true;
        }

        console.error("❌ به‌روزرسانیِ مانده‌ی مرخصیِ کارمند ناموفق بود:", xhr.responseText);

    } catch (error) {

        console.error("❌ خطا در به‌روزرسانیِ مانده‌ی مرخصیِ کارمند:", error);

    }

    return false;

}


// یک آیتمِ جدید را اتمیک به یک آرایه‌یِ ذخیره‌شده روی سرور اضافه
// می‌کند (به‌جای خواندنِ کل آرایه در مرورگر، push، و نوشتنِ کاملِ آن
// با localStorage.setItem — که بین دو کاربرِ هم‌زمان مسابقه دارد و
// می‌تواند ثبتِ یکی از آن دو را گم کند). dedupeField/dedupeValue
// اختیاری‌اند و برای جلوگیری از ثبتِ دوباره (مثلاً دوبار کلیک) به کار
// می‌روند.
function stlpAppendToStoreArraySync(key, item, dedupeField, dedupeValue) {

    try {

        const xhr = new XMLHttpRequest();
        xhr.open("POST", "/api/store/" + encodeURIComponent(key), false);
        xhr.setRequestHeader("Content-Type", "application/json");
        xhr.setRequestHeader("Accept", "application/json");

        const body = { item: item };

        if (dedupeField !== undefined) {
            body.dedupeField = dedupeField;
            body.dedupeValue = dedupeValue;
        }

        xhr.send(JSON.stringify(body));

        if (xhr.status >= 200 && xhr.status < 300) {

            const result = JSON.parse(xhr.responseText);
            const added = result.added !== false;

            // مثل stlpApplyEmployeeLeaveEffectSync — کشِ محلی را با
            // آیتمِ تازه هماهنگ می‌کنیم تا خواندنِ فوریِ بعدی (مثلاً
            // renderRequestsTab بلافاصله بعد از ثبت) آن را ببیند.
            if (added && window.__stlpServerStorage && typeof window.__stlpServerStorage.refreshKey === "function") {

                try {

                    const arr = JSON.parse(localStorage.getItem(key) || "[]");

                    const alreadyThere =
                        dedupeField !== undefined &&
                        arr.some(function(existing) { return existing && String(existing[dedupeField]) === String(dedupeValue); });

                    if (!alreadyThere) {
                        arr.push(item);
                        window.__stlpServerStorage.refreshKey(key, JSON.stringify(arr));
                    }

                } catch (cacheError) {
                    console.error("⚠️ همگام‌سازیِ کشِ محلی ناموفق بود:", cacheError);
                }

            }

            return added;
        }

        console.error("❌ افزودنِ اتمیک به سرور ناموفق بود:", xhr.responseText);

    } catch (error) {

        console.error("❌ خطا در افزودنِ اتمیک به سرور:", error);

    }

    return false;

}


// کشِ محلیِ یک کلید را با نسخه‌ی واقعیِ سرور جایگزین می‌کند (GET
// می‌گیرد و بدونِ هیچ PUT/POST دیگری فقط کشِ همین تب را عوض می‌کند).
// وقتی سرور خودش برخی فیلدها را محاسبه می‌کند (مثلاً شماره‌ی نامه یا
// امضاکننده در handleLettersDecide) بازسازیِ محلیِ آن فیلدها در
// مرورگر درست نیست؛ باید نسخه‌ی واقعیِ سرور را دوباره خواند.
function stlpRefreshStoreKeyFromServerSync(key) {

    if (!(window.__stlpServerStorage && typeof window.__stlpServerStorage.refreshKey === "function")) {
        return false;
    }

    try {

        const xhr = new XMLHttpRequest();
        xhr.open("GET", "/api/store/" + encodeURIComponent(key), false);
        xhr.setRequestHeader("Accept", "application/json");
        xhr.send(null);

        if (xhr.status >= 200 && xhr.status < 300) {
            const body = JSON.parse(xhr.responseText);
            window.__stlpServerStorage.refreshKey(key, body.value == null ? "[]" : body.value);
            return true;
        }

    } catch (error) {
        console.error("⚠️ همگام‌سازیِ کش با سرور ناموفق بود:", error);
    }

    return false;

}


// تصمیم‌گیریِ سطوحِ تأییدِ درخواستِ مرخصی/نامه‌ی رسمی (مدیر/مالی/هیات
// مدیره) را اتمیک و با کنترلِ اختیارِ سمتِ سرور ثبت می‌کند — به‌جای
// خواندنِ کاملِ آرایه، تغییرِ محلی، و PUTِ کامل (که فقط دسترسیِ عمومیِ
// ماژولِ «نامه‌ها» را چک می‌کرد، نه این‌که کاربر واقعاً مدیر/معاونِ
// همان بخش، مسئولِ مالیِ مجاز، یا عضوِ هیات مدیره است یا نه).
// action یکی از: "leave-manager" | "leave-finance" | "official-manager" | "official-board"
// extra (اختیاری) فیلدهای غیرحساسِ اضافه (مثلاً تاریخِ شمسیِ امروز
// برای «official-board») را به بدنه‌ی درخواست اضافه می‌کند
function stlpLettersDecideSync(action, requestId, approve, extra) {

    try {

        const xhr = new XMLHttpRequest();
        xhr.open("POST", "/api/letters/decide", false);
        xhr.setRequestHeader("Content-Type", "application/json");
        xhr.setRequestHeader("Accept", "application/json");
        xhr.send(JSON.stringify(Object.assign({ action: action, requestId: requestId, approve: !!approve }, extra || {})));

        if (xhr.status >= 200 && xhr.status < 300) {
            return true;
        }

        let message = "";
        try { message = JSON.parse(xhr.responseText).error || ""; } catch (parseError) {}

        alert("❌ " + (message || "این تصمیم ثبت نشد."));

    } catch (error) {

        console.error("❌ خطا در ثبتِ تصمیم:", error);
        alert("❌ خطا در ارتباط با سرور — این تصمیم ثبت نشد.");

    }

    return false;

}


// =====================================================
// جایگاه سازمانی — منبع اصلی حقیقت الان رکورد کارمنده
// (employee.orgRole: "employee" | "manager" | "deputy" | "board"،
// و برای هیات‌مدیره employee.boardPost). این توابع مشترک بین
// payroll.html (فرم استخدام)، org-chart.html (چارت) و letters.html
// (مسیریابی تأیید درخواست‌ها/نامه‌ها) استفاده می‌شن
// =====================================================

const STLP_BOARD_POST_ORDER = ["chairman", "vice_chairman", "ceo", "member"];

const STLP_BOARD_POST_LABELS = {
    chairman: "رئیس هیات مدیره",
    vice_chairman: "نایب رئیس هیات مدیره",
    ceo: "مدیرعامل",
    member: "عضو هیات مدیره"
};


// کارمندِ متصل به یک کاربر سیستم (اگر باشه)
function stlpUserEmployee(user) {

    if (!user || !user.employeeId) return null;

    const employees = loadEmployees();

    return employees.find(function(e) { return e.id === user.employeeId; }) || null;

}


// آیا این کاربر، از طریق کارمندِ متصل‌شده‌اش، عضو هیات مدیره است؟
function stlpUserIsBoardMember(user) {

    const employee = stlpUserEmployee(user);

    return !!(employee && employee.orgRole === "board");

}


// اگه این کاربر مدیرِ یک بخشه، همون بخش رو برمی‌گردونه؛ وگرنه null
function stlpUserManagedDepartment(user) {

    const employee = stlpUserEmployee(user);
    if (!employee || employee.orgRole !== "manager" || !employee.departmentId) return null;

    const departments = stlpLoadDepartments();

    return departments.find(function(d) { return d.id === employee.departmentId; }) || null;

}


// اگه این کاربر معاونِ یک بخشه، همون بخش رو برمی‌گردونه؛ وگرنه null
// (معاون هم مثل مدیر باید بتونه صف تأیید سطح ۱ همون بخش رو ببینه)
function stlpUserDeputyDepartment(user) {

    const employee = stlpUserEmployee(user);
    if (!employee || employee.orgRole !== "deputy" || !employee.departmentId) return null;

    const departments = stlpLoadDepartments();

    return departments.find(function(d) { return d.id === employee.departmentId; }) || null;

}


// آی‌دیِ کاربرِ متصل به مدیرِ یک بخش (برای مسیریابی تأیید مرخصی/نامه)؛
// اگه مدیر بخش هیچ حساب کاربری‌ای نداشته باشه، رشته‌ی خالی برمی‌گرده
function stlpDeptManagerUserId(departmentId) {

    if (!departmentId) return "";

    const employees = loadEmployees();

    const managerEmployee =
        employees.find(function(e) {
            return e.departmentId === departmentId && e.orgRole === "manager";
        });

    if (!managerEmployee) return "";

    const users = stlpLoadUsers();

    const managerUser =
        users.find(function(u) { return u.employeeId === managerEmployee.id; });

    return managerUser ? managerUser.id : "";

}


// مهاجرتِ یک‌بارِ داده‌های قدیمی به سیستم جدید: قبلاً مدیر/معاونِ هر
// بخش رو خودِ رکورد بخش (managerUserId / deputyUserIds) نگه می‌داشت
// و عضویت در هیات مدیره رو خودِ کاربر (user.isBoardMember)؛ الان همه
// این‌ها رو رکورد کارمند نگه می‌داره (employee.orgRole). این تابع
// یک‌بار (idempotent — با یه پرچم تو localStorage) این‌ها رو به
// employee.orgRole منتقل می‌کنه تا چارت/تأییدها برای داده‌ی قدیمی
// خالی نمونن. باید تو هر سه صفحه (چارت، حقوق‌ودستمزد، نامه‌ها) قبل
// از رندر/استفاده صدا زده بشه
function stlpMigrateLegacyOrgRoles() {

    if (localStorage.getItem("stlp_org_roles_migrated_v1")) return;

    const employees = loadEmployees();
    const users = stlpLoadUsers();
    const departments = stlpLoadDepartments();

    let changed = false;

    function employeeOfUserId(userId) {
        const u = users.find(function(x) { return x.id === userId; });
        if (!u || !u.employeeId) return null;
        return employees.find(function(e) { return e.id === u.employeeId; }) || null;
    }

    // ۱) هیات مدیره — از روی user.isBoardMember قدیمی
    users.forEach(function(u) {
        if (!u.isBoardMember || !u.employeeId) return;
        const emp = employees.find(function(e) { return e.id === u.employeeId; });
        if (!emp || emp.orgRole) return; // کارمندی که از قبل orgRole داره دست نمی‌خوره
        emp.orgRole = "board";
        emp.boardPost = emp.boardPost || "member";
        emp.departmentId = "";
        changed = true;
    });

    // ۲) مدیرِ هر بخش — از روی dept.managerUserId قدیمی
    departments.forEach(function(dept) {
        if (!dept.managerUserId) return;
        const emp = employeeOfUserId(dept.managerUserId);
        if (!emp || emp.orgRole) return;
        emp.orgRole = "manager";
        emp.departmentId = dept.id;
        changed = true;
    });

    // ۳) معاونینِ هر بخش — از روی dept.deputyUserIds قدیمی
    departments.forEach(function(dept) {
        if (!Array.isArray(dept.deputyUserIds)) return;
        dept.deputyUserIds.forEach(function(uid) {
            const emp = employeeOfUserId(uid);
            if (!emp || emp.orgRole) return;
            emp.orgRole = "deputy";
            emp.departmentId = dept.id;
            changed = true;
        });
    });

    if (changed) {

        saveEmployees(employees);

        if (typeof stlpLogActivity === "function") {
            stlpLogActivity("چارت سازمانی", "مهاجرت خودکار نقش‌های قدیمی به سیستم جدید", "");
        }

    }

    localStorage.setItem("stlp_org_roles_migrated_v1", "1");

}


// =====================================================
// درخواست مرخصی — مشترک بین letters.html (ثبت/تأیید) و
// payroll.html (خواندن برای محاسبه‌ی روز کارکرد)
//
// هر رکورد: { id, employeeId, requestedByUserId, leaveType:
// 'daily'|'hourly', startDate, endDate, hourlyDate, hours, days,
// reason, status: 'pending'|'approved'|'rejected', createdAt,
// decidedAt, decidedByUserId }
// =====================================================

function stlpLoadLeaveRequests() {
    try {
        return JSON.parse(localStorage.getItem("stlp_leave_requests")) || [];
    } catch (e) {
        return [];
    }
}


function stlpSaveLeaveRequests(requests) {
    localStorage.setItem("stlp_leave_requests", JSON.stringify(requests));
}


// چند روز طول می‌کشد یک بازه‌ی تاریخ شمسی (هر دو سر شامل)؛
// از همان الگوی «سال*10000+ماه*100+روز» با تقریب ۳۰ روز در ماه
// که در بقیه‌ی سیستم حقوق هم استفاده شده است
function stlpLeaveRequestDaysBetween(startDateStr, endDateStr) {

    if (typeof stlpParseLooseJalaliDate !== "function") return 1;

    const startPacked = stlpParseLooseJalaliDate(startDateStr);
    const endPacked = stlpParseLooseJalaliDate(endDateStr);

    if (!startPacked || !endPacked) return 1;

    const sy = Math.floor(startPacked / 10000);
    const sm = Math.floor((startPacked % 10000) / 100) || 1;
    const sd = (startPacked % 100) || 1;

    const ey = Math.floor(endPacked / 10000);
    const em = Math.floor((endPacked % 10000) / 100) || 1;
    const ed = (endPacked % 100) || 1;

    const days = ((ey * 360) + (em * 30) + ed) - ((sy * 360) + (sm * 30) + sd) + 1;

    return Math.max(1, days);

}


// جمع روزهای مرخصی تأییدشده (روزانه + ساعتی÷۸) یک کارمند که در
// یک دوره‌ی ماهانه‌ی مشخص (فرمت "1404/07") قرار می‌گیرد — برای
// محاسبه‌ی خودکار روزهای کارکرد در سیستم حقوق استفاده می‌شود
function stlpGetApprovedLeaveForPeriod(employeeId, period) {

    if (!employeeId || !period) return { days: 0, hours: 0 };

    const periodPacked = stlpParseLooseJalaliDate(period + "/01");
    if (!periodPacked) return { days: 0, hours: 0 };

    const periodYear = Math.floor(periodPacked / 10000);
    const periodMonth = Math.floor((periodPacked % 10000) / 100);

    const requests =
        stlpLoadLeaveRequests().filter(function(r) {
            return r.employeeId === employeeId && r.status === "approved";
        });

    let totalDays = 0;
    let totalHours = 0;

    requests.forEach(function(r) {

        if (r.leaveType === "hourly") {

            const p = stlpParseLooseJalaliDate(r.hourlyDate);
            if (!p) return;

            const y = Math.floor(p / 10000);
            const m = Math.floor((p % 10000) / 100);

            if (y === periodYear && m === periodMonth) {
                totalHours += Number(r.hours || 0);
            }

        } else {

            const sp = stlpParseLooseJalaliDate(r.startDate);
            const ep = stlpParseLooseJalaliDate(r.endDate);
            if (!sp || !ep) return;

            const sy = Math.floor(sp / 10000), sm = Math.floor((sp % 10000) / 100) || 1, sd = (sp % 100) || 1;
            const ey = Math.floor(ep / 10000), em = Math.floor((ep % 10000) / 100) || 1, ed = (ep % 100) || 1;

            // بازه‌ی مرخصی و بازه‌ی همین دوره‌ی ماهانه را هر دو روی همان
            // محور خطیِ «سال×۳۶۰ + ماه×۳۰ + روز» (همان تقریبِ ۳۰-روزه‌ی
            // ماه که در کل سیستم حقوق استفاده می‌شود، مثلاً در
            // stlpLeaveRequestDaysBetween) قرار می‌دهیم و فقط طولِ
            // هم‌پوشانیِ واقعی با این ماه را اضافه می‌کنیم — نه کل طول
            // مرخصی — چون قبلاً برای یک مرخصیِ چندماهه، کل روزهایش به
            // هر ماهِ هم‌پوشان جداگانه اضافه می‌شد (یعنی چند برابر
            // شمرده می‌شد و روزهای کارکردِ ماه‌های دیگر را صفر می‌کرد)
            const leaveStartLinear = sy * 360 + sm * 30 + sd;
            const leaveEndLinear = ey * 360 + em * 30 + ed;
            const periodStartLinear = periodYear * 360 + periodMonth * 30 + 1;
            const periodEndLinear = periodYear * 360 + periodMonth * 30 + 30;

            const overlapDays =
                Math.min(leaveEndLinear, periodEndLinear) -
                Math.max(leaveStartLinear, periodStartLinear) + 1;

            if (overlapDays > 0) {
                totalDays += overlapDays;
            }

        }

    });

    return { days: totalDays, hours: totalHours };

}


// یک تاریخ شمسی آزاد (با اعداد فارسی یا لاتین، با یا بدون صفر ابتدایی،
// جداکننده‌ی / یا -) را به یک عدد قابل مقایسه (سال*10000+ماه*100+روز) تبدیل می‌کند
function stlpParseLooseJalaliDate(str) {

    if (!str) return null;

    const latin = String(str)
        .trim()
        .replace(/[۰-۹]/g, function(ch) { return String("۰۱۲۳۴۵۶۷۸۹".indexOf(ch)); })
        .replace(/[٠-٩]/g, function(ch) { return String("٠١٢٣٤٥٦٧٨٩".indexOf(ch)); });

    const parts = latin.split(/[\/\-]/).map(function(p) { return parseInt(p, 10); });

    if (parts.length < 2 || parts.some(function(n) { return isNaN(n); })) return null;

    const year = parts[0];
    const month = parts[1] || 1;
    const day = parts[2] || 1;

    return (year * 10000) + (month * 100) + day;

}




