async function stlpLogout() {

    // قبل از ریدایرکت به login.html، حتماً منتظر می‌مانیم که
    // درخواست خروج واقعاً به سرور برسد و نشست را آنجا باطل کند.
    // قبلاً این fetch به‌صورت async-بدون-await فرستاده می‌شد و
    // بلافاصله location.href صفحه را عوض می‌کرد — یعنی مرورگر
    // معمولاً همان درخواست نیمه‌کاره را قطع می‌کرد، نشست روی
    // سرور هرگز باطل نمی‌شد و کوکی هم پاک نمی‌شد؛ در نتیجه بعد
    // از «خروج» و رفرش، کاربر هنوز وارد بود.
    try {

        await fetch("/api/auth/logout", {
            method: "POST",
            credentials: "same-origin"
        });

    } catch (error) {

        // حتی اگر اتصال قطع بود، باز هم این مرورگر را از حالت
        // واردشده خارج می‌کنیم (ادامه‌ی تابع)

    }

    localStorage.removeItem("role");
    localStorage.removeItem("stlp_current_user");
    location.href = "login.html";

}


// =====================================================
// خروج خودکار بعد از بی‌فعالیتیِ طولانی (۳۰ دقیقه)
// روی همه‌ی صفحاتی که app.js را لود می‌کنند فعال است؛ فقط اگر
// واقعاً کسی وارد شده باشد کاری انجام می‌دهد.
// =====================================================

(function() {

    const STLP_IDLE_LIMIT_MS = 30 * 60 * 1000;

    let idleTimer = null;

    function stlpScheduleAutoLogout() {

        if (idleTimer) {
            clearTimeout(idleTimer);
        }

        idleTimer = setTimeout(function() {

            if (stlpCurrentUser()) {

                alert("⏱ به دلیل عدم فعالیت طولانی (۳۰ دقیقه)، از حساب کاربری خارج شدید.");

                stlpLogout();

            }

        }, STLP_IDLE_LIMIT_MS);

    }

    ["mousemove", "mousedown", "keydown", "scroll", "touchstart"].forEach(function(eventName) {

        document.addEventListener(eventName, stlpScheduleAutoLogout, { passive: true });

    });

    stlpScheduleAutoLogout();

})();


// =====================================================
// لاگ فعالیت کل سیستم — مشترک بین همه‌ی ماژول‌ها
// (فاکتور، خزانه، مشتریان، CRM، خرید و ...)
// هر صفحه‌ای که app.js را لود کند، به همین یک لاگ می‌نویسد
// =====================================================

// این آرایه فقط برای صفحه‌ی لاگِ فعالیت (activity-log.html، فقط
// ادمین) پر می‌شود — چون سرور خواندنِ stlp_activity_log را به ادمین
// محدود کرده. برای بقیه‌ی کاربرها همیشه خالی است، که درست هم هست
// (آن‌ها اجازه‌ی دیدنِ لاگ را ندارند، فقط اجازه‌ی افزودن به آن).
let stlpActivityLog = [];

try {
    stlpActivityLog = JSON.parse(
        localStorage.getItem("stlp_activity_log") || "[]"
    );
} catch (error) {
    stlpActivityLog = [];
}


// module: نام ماژول («خزانه»، «مشتریان»، «CRM»، «حسابداری» و ...)
// action: عنوان کوتاه عملیات («افزودن»، «حذف»، «ویرایش» و ...)
// details: توضیح یک‌خطی خوانا
//
// این تابع دیگر مستقیماً روی stlp_activity_log نمی‌نویسد — آن کلید
// روی سرور append-only است (نه PUT نه DELETE، حتی برای ادمین؛ رجوع
// شود به handleAppendActivityLog در erp/server/routes/store.js) تا
// لاگِ فعالیت واقعاً قابلِ‌اعتماد باشد: نه کسی بتواند آن را دستکاری/
// پاک کند، نه به نامِ کاربرِ دیگری جعل کند. نام‌کاربری و زمان همیشه
// از روی نشستِ واقعیِ سرور ساخته می‌شوند، نه از چیزی که این‌جا
// فرستاده شود.
function stlpLogActivity(module, action, details) {

    try {

        const xhr = new XMLHttpRequest();
        xhr.open("POST", "/api/activity-log/append", false);
        xhr.setRequestHeader("Content-Type", "application/json");
        xhr.send(JSON.stringify({
            module: module || "سیستم",
            action: action || "",
            details: details || ""
        }));

        if (xhr.status >= 200 && xhr.status < 300) {

            const result = JSON.parse(xhr.responseText);

            if (result && result.entry) {
                stlpActivityLog.push(result.entry);
            }

            return;

        }

        console.error("⚠️ ثبتِ لاگِ فعالیت ناموفق بود:", xhr.responseText);

    } catch (error) {

        console.error("⚠️ خطا در ثبتِ لاگِ فعالیت:", error);

    }

}


// هر صفحه‌ی محافظت‌شده در ابتدای بارگذاری این تابع را صدا می‌زند

function stlpRequirePermission(moduleKey) {

    const user = stlpCurrentUser();

    if (!user) {

        location.href = "login.html";
        return false;

    }

    if (user.isAdmin) return true;

    if (moduleKey === "admin-only") {

        alert("⛔ این بخش فقط برای مدیر سیستم قابل دسترسی است.");
        location.href = "home.html";
        return false;

    }

    if (moduleKey === "home") return true;

    if (moduleKey && user.permissions && user.permissions[moduleKey] === true) {
        return true;
    }

    alert("⛔ شما به این بخش دسترسی ندارید. برای دسترسی با مدیر سیستم هماهنگ کنید.");
    location.href = "home.html";
    return false;

}


// =====================================================
// تأیید مدیر برای عملیات حساس (حذف رکوردهای حسابداری/خزانه)
// =====================================================
// رمز را خودِ این تابع بررسی نمی‌کند (چون آن مقایسه باید همیشه
// روی سرور انجام شود، نه با هشِ محلی که هرکسی از کنسول مرورگر
// می‌تواند دور بزند) — فقط از /api/auth/verify-admin می‌پرسد که
// آیا این نام‌کاربری/رمز واقعاً متعلق به یک مدیرِ فعال است، بدون
// اینکه نشستِ فعلی را عوض کند.

async function stlpConfirmAdminPassword(actionLabel) {

    const username = prompt("🔒 برای " + actionLabel + "، نام‌کاربریِ مدیر سیستم را وارد کنید:");

    if (username === null) return false;

    if (!username.trim()) {
        alert("❌ نام‌کاربری وارد نشد.");
        return false;
    }

    const password = prompt("🔒 رمز عبور مدیر سیستم را وارد کنید:");

    if (password === null) return false;

    if (!password) {
        alert("❌ رمز عبور وارد نشد.");
        return false;
    }

    try {

        const response = await fetch("/api/auth/verify-admin", {
            method: "POST",
            credentials: "same-origin",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ username: username.trim(), password: password })
        });

        let result = {};

        try {
            result = await response.json();
        } catch (error) {
            result = {};
        }

        if (!response.ok || !result.ok) {
            alert("❌ " + (result.error || "تأیید مدیر ناموفق بود."));
            return false;
        }

        return true;

    } catch (error) {

        alert("⛔ ارتباط با سرور برای تأیید مدیر برقرار نشد.");
        return false;

    }

}


// چک‌باکسِ «انتخاب همه»ی بالای یک جدول را به همه‌ی چک‌باکس‌های
// هم‌کلاس داخل همان جدول اعمال می‌کند — الگوی عمومی برای هر جدولی
// که نیاز به انتخاب گروهی دارد.

function stlpToggleCheckboxGroup(sourceCheckbox, selector) {

    const table = sourceCheckbox.closest("table");

    if (!table) return;

    table.querySelectorAll(selector).forEach(function(chk) {
        chk.checked = sourceCheckbox.checked;
    });

}


// =====================================================
// محدودیت تلاش ورود (قفل موقت بعد از چند بار رمز اشتباه)
// =====================================================

const STLP_MAX_LOGIN_ATTEMPTS = 5;
const STLP_LOCKOUT_MINUTES = 5;

function stlpGetLoginAttempts() {

    try {

        return JSON.parse(
            localStorage.getItem("stlp_login_attempts") || "{}"
        );

    } catch (error) {

        return {};

    }

}

function stlpSaveLoginAttempts(data) {

    localStorage.setItem(
        "stlp_login_attempts",
        JSON.stringify(data)
    );

}

function stlpCheckLockout(username) {

    const attempts = stlpGetLoginAttempts();

    const record = attempts[username];

    if (!record) return null;

    if (
        record.count >= STLP_MAX_LOGIN_ATTEMPTS &&
        record.lockedUntil &&
        Date.now() < record.lockedUntil
    ) {

        const remainingMs = record.lockedUntil - Date.now();
        const remainingMin = Math.ceil(remainingMs / 60000);

        return remainingMin;

    }

    // اگر زمان قفل تمام شده، شمارنده صفر می‌شود
    if (record.lockedUntil && Date.now() >= record.lockedUntil) {

        delete attempts[username];
        stlpSaveLoginAttempts(attempts);

    }

    return null;

}

function stlpRegisterFailedLogin(username) {

    const attempts = stlpGetLoginAttempts();

    const record =
        attempts[username] || { count: 0, lockedUntil: null };

    record.count = (record.count || 0) + 1;

    if (record.count >= STLP_MAX_LOGIN_ATTEMPTS) {

        record.lockedUntil =
            Date.now() + STLP_LOCKOUT_MINUTES * 60000;

    }

    attempts[username] = record;

    stlpSaveLoginAttempts(attempts);

    return record;

}

function stlpClearLoginAttempts(username) {

    const attempts = stlpGetLoginAttempts();

    delete attempts[username];

    stlpSaveLoginAttempts(attempts);

}


// =============================
//   لاگین
// =============================

function stlpLoginAlert(message) {

    if (typeof stlpShowLoginError === "function") {

        stlpShowLoginError(message);

    } else {

        alert(message);

    }

}

async function login() {

    // =========================================================
    // این تابع دیگر خودش رمز را چک نمی‌کند — رمز و قفل موقت حالا
    // واقعاً روی سرور بررسی می‌شود (قبلاً همه‌چیز فقط داخل همین
    // مرورگر بود و هرکسی با کنسول مرورگر می‌توانست از آن رد شود).
    // =========================================================

    const usernameField =
        document.getElementById("username");

    const passwordField =
        document.getElementById("password");

    const u = usernameField.value.trim();
    const p = passwordField.value;

    if (!u || !p) {

        stlpLoginAlert("لطفاً نام کاربری و رمز عبور را وارد کنید.");
        return;

    }

    let response;

    try {

        response = await fetch("/api/auth/login", {
            method: "POST",
            credentials: "same-origin",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ username: u, password: p })
        });

    } catch (error) {

        stlpLoginAlert("⛔ ارتباط با سرور برقرار نشد. مطمئن شوید سرور STLP روشن است.");
        return;

    }

    let result = {};

    try {
        result = await response.json();
    } catch (error) {
        result = {};
    }

    if (!response.ok || !result.user) {

        stlpLoginAlert(result.error || "نام کاربری یا رمز اشتباه است.");
        return;

    }


    // -------------------------------------------
    // ورود موفق — نشست امن روی سرور ساخته شد.
    // این دو خط فقط کش همین صفحه را پر می‌کنند تا
    // stlpCurrentUser() بلافاصله جواب درست بدهد.
    // -------------------------------------------

    localStorage.setItem("role", result.user.isAdmin ? "admin" : "user");
    localStorage.setItem("stlp_current_user", JSON.stringify(result.user));

    location.href = "home.html";

}

// =============================
//   فاکتور فروش
// =============================
function addRow() {
    let tbody = document.getElementById("invoiceBody");
    if (!tbody) return;

    let row = document.createElement("tr");
    row.id = "row_" + rowIndex;

    row.innerHTML = `
        <td>${rowIndex}</td>
        <td>
            <select id="select_${rowIndex}" onchange="fillItem(${rowIndex})">
                <option value="">-- انتخاب --</option>
            </select>
        </td>
        <td><input id="code_${rowIndex}" style="width:80px" readonly></td>
        <td><input id="desc_${rowIndex}" style="width:160px" readonly></td>
        <td><input id="unit_${rowIndex}" style="width:70px" readonly></td>
        <td><input type="number" id="qty_${rowIndex}" value="1" style="width:60px"
                oninput="recalc(${rowIndex})"></td>
        <td><input type="number" id="price_${rowIndex}" value="0" style="width:90px"
                oninput="recalc(${rowIndex})" readonly></td>
        <td id="total_${rowIndex}">0</td>
        <td><input type="number" id="discount_${rowIndex}" value="0" min="0" max="100" style="width:60px"
                oninput="recalc(${rowIndex})"></td>
        <td id="afterDisc_${rowIndex}">0</td>
        <td id="tax_${rowIndex}">0</td>
        <td id="final_${rowIndex}">0</td>
        <td>
            <button type="button" onclick="removeRow(${rowIndex})"
                style="background:#dc3545; color:#fff; border:none; padding:6px 10px; border-radius:6px; cursor:pointer;">
                🗑
            </button>
        </td>
    `;

    tbody.appendChild(row);

    loadSelect(rowIndex);
    recalc(rowIndex);
    rowIndex++;
}

// ============================================
// حذف یک ردیف از فاکتور
// ============================================

function removeRow(i) {

    const row = document.getElementById("row_" + i);

    if (!row) return;

    const tbody = document.getElementById("invoiceBody");

    if (tbody && tbody.children.length <= 1) {

        alert("فاکتور باید حداقل یک ردیف داشته باشد.");
        return;

    }

    row.remove();

    calcFinalTotal();

}
// ============================================
// بارگذاری کالاهای انبار داخل ردیف فاکتور
// ============================================

function loadSelect(i) {

    const select =
        document.getElementById("select_" + i);

    if (!select) return;

    const inventory =
        JSON.parse(
            localStorage.getItem("stlp_inventory") || "[]"
        );

    select.innerHTML = `
        <option value="">-- انتخاب کالا --</option>
    `;

    inventory.forEach(function(item) {

        const option =
            document.createElement("option");

        option.value = item.code;

        option.textContent =
            item.code + " - " + item.name;

        select.appendChild(option);

    });
}
// ============================================
// پر کردن اطلاعات کالا در فاکتور
// ============================================

function fillItem(i) {

    const select =
        document.getElementById("select_" + i);

    if (!select) return;

    const code = select.value;

    if (!code) {

        document.getElementById("code_" + i).value = "";
        document.getElementById("desc_" + i).value = "";
        document.getElementById("unit_" + i).value = "";
        document.getElementById("price_" + i).value = "0";

        recalc(i);

        return;
    }

    const inventory =
        JSON.parse(
            localStorage.getItem("stlp_inventory") || "[]"
        );

    const item =
        inventory.find(function(product) {

            return String(product.code) === String(code);

        });

    if (!item) return;

    document.getElementById("code_" + i).value =
        item.code || "";

    document.getElementById("desc_" + i).value =
        item.name || "";

    document.getElementById("unit_" + i).value =
        item.unit || "";

    document.getElementById("price_" + i).value =
        Number(item.price || 0);

    recalc(i);
}

function recalc(i) {
    let qtyEl = document.getElementById("qty_" + i);
    let priceEl = document.getElementById("price_" + i);
    let discEl = document.getElementById("discount_" + i);
    let taxRateEl = document.getElementById("taxRate");

    if (!qtyEl || !priceEl || !discEl || !taxRateEl) return;

    let qty = Number(qtyEl.value) || 0;
    let price = Number(priceEl.value) || 0;
    // تخفیف باید بین ۰ تا ۱۰۰ درصد باشد؛ بدون این محدودیت، عددی
    // مثل ۱۵۰ باعث می‌شد afterDisc/tax/final و در نتیجه جمع کل
    // فاکتور منفی شود — یعنی فاکتوری با طلب از مشتری به‌جای بدهی او
    let discount = Math.min(100, Math.max(0, Number(discEl.value) || 0));
    let taxRate = Number(taxRateEl.value) || 0;

    let total = qty * price;
    let afterDisc = total - (total * discount / 100);
    let tax = afterDisc * (taxRate / 100);
    let final = afterDisc + tax;

    let totalCell = document.getElementById("total_" + i);
    let afterDiscCell = document.getElementById("afterDisc_" + i);
    let taxCell = document.getElementById("tax_" + i);
    let finalCell = document.getElementById("final_" + i);

    if (totalCell) totalCell.innerText = total.toLocaleString("en-US");
    if (afterDiscCell) afterDiscCell.innerText = afterDisc.toLocaleString("en-US");
    if (taxCell) taxCell.innerText = tax.toLocaleString("en-US");
    if (finalCell) finalCell.innerText = final.toLocaleString("en-US");

    calcFinalTotal();
}

function calcFinalTotal() {
    let sum = 0;
    for (let x = 1; x < rowIndex; x++) {
        let valEl = document.getElementById("final_" + x);
        if (valEl && valEl.innerText) {
            let num = Number(valEl.innerText.replace(/,/g, ""));
            if (!isNaN(num)) sum += num;
        }
    }
    let ft = document.getElementById("finalTotal");
    if (ft) ft.innerText = sum.toLocaleString("en-US") + " ریال";
}

// ============================================
// مدیریت مشتریان
// ============================================


// مشتری‌ها قبلاً هیچ شناسه‌ای نداشتند و همه‌جا با اندیسِ خامِ آرایه
// شناسایی می‌شدند (ویرایش/حذف/انتخاب در فاکتور و پیش‌فاکتور) — یعنی
// اگر بینِ باز کردنِ فرمِ ویرایش و ذخیره‌ی آن، جای مشتری‌ها در آرایه
// عوض می‌شد (مثلاً یک مشتریِ دیگر همان لحظه اضافه/حذف می‌شد)، ویرایش
// روی مشتریِ اشتباهی اعمال می‌شد. این تابع به هر مشتریِ قدیمیِ بدونِ
// id یک id می‌دهد (فقط یک‌بار، در اولین بار که بعد از این تغییر
// خوانده می‌شود) تا از این‌جا به بعد همه‌جا با id شناسایی شوند.
function stlpLoadCustomersEnsuringIds() {

    let list;

    try {
        list = JSON.parse(localStorage.getItem("customers") || "[]");
        if (!Array.isArray(list)) list = [];
    } catch (error) {
        list = [];
    }

    let migrated = false;

    list.forEach(function(customer) {

        if (customer && !customer.id) {
            customer.id = "cust_" + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);
            migrated = true;
        }

    });

    if (migrated) {
        localStorage.setItem("customers", JSON.stringify(list));
    }

    return list;

}


// لیست مشتری‌ها
let customers = stlpLoadCustomersEnsuringIds();


// شناسه‌ی مشتریِ در حال ویرایش (نه اندیسِ آرایه — رجوع شود به
// stlpLoadCustomersEnsuringIds بالا)
let editingCustomerId = null;


// ============================================
// ذخیره مشتری‌ها
// ============================================

function saveCustomers() {

    localStorage.setItem(
        "customers",
        JSON.stringify(customers)
    );

}


