// ============================================
// جستجوی مشتری
// ============================================

function searchCustomer() {


    const search =
        document
            .getElementById(
                "customerSearch"
            )
            .value
            .trim()
            .toLowerCase();


    // جستجوی خالی
    if (!search) {

        renderCustomers();

        return;

    }


    // فیلتر
    const filtered =
        customers.filter(
            function(customer) {


                return (

                    (customer.name || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.nationalId || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.econCode || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.regNo || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.province || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.city || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.address || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.phone || "")
                        .toLowerCase()
                        .includes(search)

                    ||

                    (customer.postalCode || "")
                        .toLowerCase()
                        .includes(search)

                );

            }
        );


    renderCustomers(filtered);

}
