// شروع صفحه
// ============================================

document.addEventListener(
    "DOMContentLoaded",
    function() {

        renderCustomers();

    }
);
// ===============================
//   تولید شماره فاکتور خودکار
// ===============================
// این شماره حالا روی خودِ سرور و به‌صورت اتمیک تولید می‌شود
// (نه در مرورگر)، وگرنه دو فروشنده که هم‌زمان فاکتور می‌زنند
// می‌توانستند دقیقاً یک شماره‌ی یکسان بگیرند.
async function getNextInvoiceNumber() {

    const response = await fetch("/api/counter/next-invoice-number", {
        method: "POST",
        credentials: "same-origin"
    });

    if (!response.ok) {
        throw new Error("شماره‌ی فاکتور از سرور دریافت نشد؛ دوباره تلاش کنید.");
    }

    const body = await response.json();

    return body.number;

}

// بررسی می‌کند آیا حواله‌ی فروشِ وابسته به یک شماره فاکتور تأیید
// شده یا نه — فاکتور تا وقتی حواله‌اش تأیید نشده نه شماره‌ی واقعی
// نشان می‌دهد نه مهر/امضا می‌گیرد (stlpBuildInvoiceHTML به همین
// پرچم رجوع می‌کند). فقط می‌خواند، چیزی نمی‌نویسد.
function stlpIsInvoiceApproved(invoiceNo) {

    try {

        const deliveries =
            JSON.parse(localStorage.getItem("salesDeliveries") || "[]");

        const delivery =
            deliveries.find(function(d) {
                return String(d.invoiceNo) === String(invoiceNo);
            });

        return !!(delivery && delivery.status === "approved");

    } catch (error) {

        return false;

    }

}

// ============================
//       لود گزارش فاکتورها
// ============================
// فاکتورهای گزارش را بر اساس وضعیت حواله‌ی فروش وابسته‌شان به سه
// دسته تقسیم می‌کند: هنوز حواله‌اش تأیید/رد نشده («پیش‌فاکتورها» —
// همان فاکتورهایی که هنوز شماره و مهر/امضای واقعی نگرفته‌اند)،
// حواله‌اش تأیید شده، یا حواله‌اش رد شده.
function loadInvoices() {

    const pendingBody =
        document.getElementById("invoiceTablePending");

    const approvedBody =
        document.getElementById("invoiceTableApproved");

    const rejectedBody =
        document.getElementById("invoiceTableRejected");

    if (!pendingBody && !approvedBody && !rejectedBody) return;


    // ========================================
    // دریافت فاکتورها و حواله‌ها
    // ========================================

    const list =
        JSON.parse(
            localStorage.getItem("invoices") || "[]"
        );

    const deliveries =
        JSON.parse(
            localStorage.getItem("salesDeliveries") || "[]"
        );

    function deliveryStatusFor(invoiceNo) {

        const delivery =
            deliveries.find(function(d) {
                return String(d.invoiceNo) === String(invoiceNo);
            });

        return delivery ? delivery.status : "";

    }


    // ========================================
    // ساخت یک ردیف
    // ========================================

    function buildRow(inv) {

        const purchaseType =
            inv.purchaseType === "credit"
                ? "غیر نقدی"
                : "نقدی";

        return `

            <tr>

                <td>
                    <input
                        type="checkbox"
                        class="invoice-check"
                        data-invoice-no="${inv.invoiceNo || ""}"
                    >
                </td>

                <td>
                    ${inv.invoiceNo || ""}
                </td>

                <td>
                    ${inv.date || ""}
                </td>

                <td>
                    ${inv.customer || "-"}
                </td>

                <td>
                    ${purchaseType}
                </td>

                <td>
                    ${inv.total || "0"}
                </td>

                <td>
                    <button
                        type="button"
                        class="view-btn"
                        onclick="reprintInvoice('${inv.invoiceNo}')"
                    >
                        مشاهده
                    </button>
                </td>

            </tr>

        `;

    }


    // ========================================
    // دسته‌بندی و نمایش
    // ========================================

    const pendingRows = [];
    const approvedRows = [];
    const rejectedRows = [];

    list.forEach(function(inv) {

        const status = deliveryStatusFor(inv.invoiceNo);
        const row = buildRow(inv);

        if (status === "approved") {
            approvedRows.push(row);
        } else if (status === "rejected") {
            rejectedRows.push(row);
        } else {
            pendingRows.push(row);
        }

    });

    if (pendingBody) pendingBody.innerHTML = pendingRows.join("");
    if (approvedBody) approvedBody.innerHTML = approvedRows.join("");
    if (rejectedBody) rejectedBody.innerHTML = rejectedRows.join("");

}

// جستجوی عمومی برای هر کدام از سه جدول گزارش فاکتورها (هر تب
// ورودی جستجوی خودش را دارد و فقط روی جدول خودش اثر می‌گذارد)
function stlpFilterInvoiceRows(tbodyId, inputId) {

    const searchInput =
        document.getElementById(inputId);

    const tbody =
        document.getElementById(tbodyId);

    if (!searchInput || !tbody) return;


    const query =
        searchInput.value
            .trim()
            .toLowerCase();


    tbody.querySelectorAll("tr").forEach(function(row) {

        const text =
            row.innerText.toLowerCase();


        row.style.display =
            text.includes(query)
                ? ""
                : "none";

    });

}

// =====================================================
// خروجی اکسل گزارش فاکتورهای انتخاب‌شده
// =====================================================

function exportInvoicesReportToExcel() {

    // ---------------------------------------------
    // فاکتورهای انتخاب‌شده
    // ---------------------------------------------

    const checked =
        document.querySelectorAll(
            ".invoice-check:checked"
        );


    if (checked.length === 0) {

        alert(
            "لطفاً حداقل یک فاکتور را انتخاب کنید."
        );

        return;
    }


    // ---------------------------------------------
    // دریافت همه فاکتورها
    // ---------------------------------------------

    const list =
        JSON.parse(
            localStorage.getItem("invoices") || "[]"
        );


    // ---------------------------------------------
    // شماره فاکتورهای انتخاب‌شده
    // ---------------------------------------------

    const selectedNumbers =
        Array.from(checked).map(function (checkbox) {

            return String(
                checkbox.dataset.invoiceNo || ""
            );

        });


    // ---------------------------------------------
    // پیدا کردن فاکتورها
    // ---------------------------------------------

    const invoices =
        list.filter(function (inv) {

            return selectedNumbers.includes(
                String(inv.invoiceNo)
            );

        });


    if (invoices.length === 0) {

        alert(
            "فاکتورهای انتخاب‌شده پیدا نشدند."
        );

        return;
    }


    // =================================================
    // ساخت جدول اکسل
    // =================================================

    let rows = "";


    // ---------------------------------------------
    // عنوان گزارش
    // ---------------------------------------------

    rows += `
        <tr>
            <th colspan="6">
                گزارش فاکتورهای فروش
            </th>
        </tr>
    `;


    // ---------------------------------------------
    // سرفصل ستون‌ها
    // ---------------------------------------------

    rows += `
        <tr>

            <th>
                ردیف
            </th>

            <th>
                شماره فاکتور
            </th>

            <th>
                تاریخ
            </th>

            <th>
                مشتری
            </th>

            <th>
                نوع خرید
            </th>

            <th>
                جمع کل
            </th>

        </tr>
    `;


    // =================================================
    // اطلاعات فاکتورها
    // =================================================

    invoices.forEach(function (inv, index) {


        // ---------------------------------------------
        // نوع خرید
        // ---------------------------------------------

        let purchaseType = "نقدی";


        if (inv.purchaseType === "credit") {

            purchaseType = "غیر نقدی";

        } else if (inv.purchaseType === "cash") {

            purchaseType = "نقدی";

        }


        // ---------------------------------------------
        // جمع کل
        // ---------------------------------------------

        const total =
            inv.total || "0";


        // ---------------------------------------------
        // مشتری
        // ---------------------------------------------

        const customer =
            inv.customer ||
            inv.customerObj?.name ||
            "-";


        // ---------------------------------------------
        // ساخت ردیف
        // ---------------------------------------------

        rows += `
            <tr>

                <td>
                    ${index + 1}
                </td>

                <td>
                    ${escapeExcelHtml(
                        inv.invoiceNo || ""
                    )}
                </td>

                <td>
                    ${escapeExcelHtml(
                        inv.date || ""
                    )}
                </td>

                <td>
                    ${escapeExcelHtml(
                        customer
                    )}
                </td>

                <td>
                    ${purchaseType}
                </td>

                <td>
                    ${escapeExcelHtml(
                        total
                    )}
                </td>

            </tr>
        `;

    });


    // =================================================
    // ساخت فایل Excel
    // =================================================

    const excelHtml = `

        <!DOCTYPE html>

        <html
            xmlns:o="urn:schemas-microsoft-com:office:office"
            xmlns:x="urn:schemas-microsoft-com:office:excel"
            xmlns="http://www.w3.org/TR/REC-html40"
        >

        <head>

            <meta charset="UTF-8">

            <style>

                body {
                    direction: rtl;
                    font-family: Tahoma, Arial;
                }

                table {
                    border-collapse: collapse;
                    width: 100%;
                    direction: rtl;
                }

                th {
                    background: #198754;
                    color: white;
                    font-weight: bold;
                    border: 1px solid #555;
                    padding: 8px;
                    text-align: center;
                }

                td {
                    border: 1px solid #777;
                    padding: 8px;
                    text-align: center;
                }

                tr:first-child th {
                    background: #14532d;
                    font-size: 16px;
                }

            </style>

        </head>


        <body>

            <table>

                ${rows}

            </table>

        </body>

        </html>

    `;


    // =================================================
    // ساخت Blob
    // =================================================

    const blob =
        new Blob(
            ["\uFEFF" + excelHtml],
            {
                type:
                    "application/vnd.ms-excel;charset=utf-8"
            }
        );


    // =================================================
    // دانلود فایل
    // =================================================

    const url =
        URL.createObjectURL(blob);


    const a =
        document.createElement("a");


    a.href = url;


    a.download =
        "گزارش-فاکتورهای-فروش.xls";


    document.body.appendChild(a);


    a.click();


    document.body.removeChild(a);


    setTimeout(function () {

        URL.revokeObjectURL(url);

    }, 1000);


    // =================================================
    // پیام موفقیت
    // =================================================

    alert(
        invoices.length +
        " فاکتور با موفقیت به فایل Excel گزارش شد."
    );

}


// =====================================================
// جلوگیری از خراب شدن HTML اکسل
// =====================================================

function escapeExcelHtml(value) {

    return String(
        value == null ? "" : value
    )
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

}


async function reprintInvoice(no) {

    // ========================================
    // پیدا کردن فاکتور ذخیره‌شده
    // ========================================

    const list = JSON.parse(
        localStorage.getItem("invoices") || "[]"
    );

    const inv = list.find(function (x) {
        return String(x.invoiceNo) === String(no);
    });

    if (!inv) {

        alert("فاکتور یافت نشد.");

        return;
    }


    // ========================================
    // تبدیل اقلام فاکتور
    // ========================================

    const items = (inv.items || []).map(function (it) {

        // ------------------------------------
        // فاکتورهای جدید
        // ------------------------------------

        if (
            typeof it === "object" &&
            !Array.isArray(it)
        ) {

            return {

                code:
                    it.code || "-",

                desc:
                    it.name ||
                    it.desc ||
                    "",

                qty:
                    Number(it.qty || 0),

                unitPrice:
                    Number(
                        it.price ||
                        it.unitPrice ||
                        0
                    ),

                discPercent:
                    Number(
                        it.discount ||
                        it.discPercent ||
                        0
                    ),

                unit:
                    it.unit ||
                    ""

            };
        }


        // ------------------------------------
        // فاکتورهای قدیمی
        // ------------------------------------

        if (Array.isArray(it)) {

            return {

                code:
                    it[1] || "-",

                desc:
                    it[2] || "",

                qty:
                    Number(it[4] || 0),

                unitPrice:
                    Number(it[5] || 0),

                discPercent:
                    Number(it[6] || 0),

                unit:
                    it[3] || ""

            };
        }


        return {

            code: "-",

            desc: "",

            qty: 0,

            unitPrice: 0,

            discPercent: 0

        };

    });


    // ========================================
    // اطلاعات مشتری
    // ========================================

    const customer =
        inv.customerObj || {};


    // ========================================
    // تشخیص نوع خرید
    // ========================================

    const purchaseType =
        inv.purchaseType === "credit"
            ? "credit"
            : "cash";


    const isCash =
        purchaseType === "cash";


    // ========================================
    // گزینه‌های موتور PDF
    // ========================================

    // فاکتور تا وقتی حواله‌ی فروشش تأیید نشده، نه شماره‌ی واقعی
    // نشان می‌دهد نه مهر/امضا می‌گیرد — همین‌جاست که «قابل دانلود
    // شدن در گزارش‌ها بعد از تأیید حواله» عملاً اتفاق می‌افتد.
    const approved =
        stlpIsInvoiceApproved(
            inv.invoiceNo || no
        );

    const opts = {

        // -----------------------------
        // مشخصات فاکتور
        // -----------------------------

        code:
            approved
                ? String(inv.invoiceNo || no)
                : "در انتظار تأیید حواله",

        isApproved:
            approved,

        dateFa:
            inv.date || "",


        // -----------------------------
        // اطلاعات مشتری
        // -----------------------------

        buyerName:
            customer.name ||
            inv.customer ||
            "",

        buyerEconCode:
            customer.econCode ||
            customer.econ ||
            "",

        buyerRegNo:
            customer.regNo ||
            customer.reg ||
            "",

        buyerProvince:
            customer.province ||
            "",

        buyerCity:
            customer.city ||
            "",

        buyerPostalCode:
            customer.postalCode ||
            "",

        buyerNationalId:
            customer.nationalId ||
            customer.national ||
            "",

        buyerAddress:
            customer.address ||
            customer.addr ||
            "",

        buyerPhone:
            customer.phone ||
            "",


        // -----------------------------
        // نوع خرید
        // -----------------------------

        purchaseType:
            purchaseType,

        isCash:
            isCash,


        // -----------------------------
        // اقلام
        // -----------------------------

        items:
            items,

        onlineTrackingCode:
            inv.sourceOrderId ||
            ""

    };


    // ========================================
    // بررسی موتور PDF
    // ========================================

    if (
        typeof stlpGenerateInvoicePDF !==
        "function"
    ) {

        alert(
            "موتور PDF جدید پیدا نشد.\n\n" +
            "ابتدا کد STLP PDF را در app.js قرار دهید."
        );

        return;
    }


    // ========================================
    // چاپ مجدد
    // ========================================

    try {

        await stlpGenerateInvoicePDF(opts);

    } catch (error) {

        console.error(
            "STLP PDF ERROR:",
            error
        );

        alert(
            "خطا در چاپ مجدد فاکتور:\n" +
            error.message
        );

    }

}


// =====================================================
// پیدا کردن کالا با کد
// =====================================================

function stlpFindInventoryItem(code) {

    const value =
        String(code || "").trim();


    if (!value) return null;


    return inventoryItems.find(function(item) {

        return String(item.code).trim() === value;

    }) || null;
}


// =====================================================
// اتصال انبار به فاکتور
// =====================================================

function stlpFillInvoiceItemFromInventory(input) {

    if (!input) return;


    const code =
        input.value.trim();


    const row =
        input.closest("tr");


    if (!row || !code) return;


    const item =
        stlpFindInventoryItem(code);


    if (!item) return;


    const descInput =
        row.querySelector(".it-desc");

    const priceInput =
        row.querySelector(".it-price");


    if (descInput) {
        descInput.value =
            item.name || "";
    }


    if (priceInput) {
        priceInput.value =
            Number(item.price || 0);
    }


    if (
        typeof stlpRecalcTotals === "function"
    ) {
        stlpRecalcTotals();
    }

}
// ============================================
// کسر موجودی کالاهای فاکتور
// ============================================

// =====================================================
// ثبت یک سابقه در «گردش کالا» - از هر صفحه‌ای قابل‌فراخوانی
// (مستقل از متغیر سراسری inventoryMovements، مستقیماً روی
// localStorage کار می‌کند تا در صفحاتی که آن متغیر تعریف
// نشده هم درست کار کند)
// =====================================================

function stlpLogInventoryMovement(entry) {

    let movements = [];

    try {

        movements = JSON.parse(
            localStorage.getItem("inventoryMovements") || "[]"
        );

        if (!Array.isArray(movements)) movements = [];

    } catch (error) {

        movements = [];

    }

    movements.push(

        Object.assign({

            id:
                Date.now() + "_" + Math.random().toString(36).slice(2),

            createdAt:
                new Date().toISOString()

        }, entry)

    );

    localStorage.setItem(
        "inventoryMovements",
        JSON.stringify(movements)
    );

    if (
        typeof window.inventoryMovements !== "undefined" &&
        Array.isArray(window.inventoryMovements)
    ) {

        window.inventoryMovements = movements;

    }

    if (typeof renderInventoryMovements === "function") {

        try {
            renderInventoryMovements();
        } catch (error) {
            // صفحه‌ی فعلی ممکن است جدول گردش کالا نداشته باشد
        }

    }

}


function stlpDeductInvoiceStock(items) {

    const inventory = JSON.parse(
        localStorage.getItem("stlp_inventory") || "[]"
    );

    if (!Array.isArray(inventory)) {
        alert("❌ اطلاعات انبار معتبر نیست.");
        return false;
    }

    if (!Array.isArray(items) || items.length === 0) {
        alert("❌ کالایی برای کسر از انبار وجود ندارد.");
        return false;
    }


    // ========================================
    // ابتدا همه کالاها را بررسی می‌کنیم
    // ========================================

    const usedItems = [];

    // اگر یک کد کالا چند بار در همین فاکتور تکرار شده باشد (مثلاً
    // کاربر اشتباهی یک کالا را در دو ردیف جدا انتخاب کرده)، باید
    // جمع تعداد همه‌ی ردیف‌های آن کد با موجودی مقایسه شود، نه
    // تک‌تک هر ردیف جداگانه — وگرنه هر ردیف به‌تنهایی از موجودیِ
    // دست‌نخورده رد می‌شد و موجودی نهایی منفی می‌شد.
    const requestedByCode = {};

    for (const invoiceItem of items) {

        const code =
            String(invoiceItem.code || "").trim();

        const qty =
            Number(invoiceItem.qty || 0);

        if (!code || qty <= 0) {
            continue;
        }


        // پیدا کردن کالا با کد واقعی
        const inventoryItem =
            inventory.find(function(item) {

                return String(item.code || "").trim() === code;

            });


        if (!inventoryItem) {

            alert(
                "❌ کالای «" +
                code +
                "» در انبار پیدا نشد."
            );

            return false;
        }


        const stock =
            Number(inventoryItem.stock || 0);

        requestedByCode[code] = (requestedByCode[code] || 0) + qty;

        // ========================================
        // بررسی موجودی (جمع تمام ردیف‌های همین کد در این فاکتور)
        // ========================================

        if (requestedByCode[code] > stock) {

            alert(
                "❌ موجودی کالای «" +
                (inventoryItem.name || code) +
                "» کافی نیست.\n\n" +

                "موجودی فعلی: " +
                stock.toLocaleString("fa-IR") +

                "\n" +

                "تعداد درخواستی (مجموع ردیف‌های این کد در فاکتور): " +
                requestedByCode[code].toLocaleString("fa-IR")
            );

            return false;
        }


        usedItems.push({
            code: code,
            qty: qty,
            ref: invoiceItem
        });
    }


    // ========================================
    // کسر موجودی
    // ========================================

    usedItems.forEach(function(used) {

        const item =
            inventory.find(function(product) {

                return String(product.code || "").trim() ===
                    used.code;

            });


        if (!item) return;


        const oldStock =
            Number(item.stock || 0);


        item.stock =
            oldStock - Number(used.qty || 0);


        // مصرف FIFO از دسته‌های موجود این کالا — بهای واقعی همین لحظه
        // را برای همیشه روی همین ردیف فروش ذخیره می‌کنیم (نه قیمت آینده)
        const lotResult = stlpConsumeInventoryLotsFIFO(item.code, used.qty);

        if (used.ref) {
            used.ref.unitCostAtSale = lotResult.avgUnitCost;
            used.ref.totalCostAtSale = lotResult.totalCost;
        }


        stlpLogInventoryMovement({

            type: "out",
            itemCode: item.code || "",
            itemName: item.name || "",
            quantity: Number(used.qty || 0),
            date: new Date().toLocaleDateString("fa-IR"),
            reason: "فروش",
            document: "",
            notes: "کسر خودکار بابت تأیید حواله فروش",
            stockBefore: oldStock,
            stockAfter: item.stock

        });


        console.log(
            "کسر موجودی:",
            item.name,
            "| کد:",
            item.code,
            "| موجودی قبلی:",
            oldStock,
            "| مقدار کسر:",
            used.qty,
            "| موجودی جدید:",
            item.stock
        );

    });


    // ========================================
    // ذخیره انبار
    // ========================================

    localStorage.setItem(
        "stlp_inventory",
        JSON.stringify(inventory)
    );


    // هماهنگ کردن متغیر اصلی
    if (typeof inventoryItems !== "undefined") {
        inventoryItems = inventory;
    }


    // نمایش مجدد جدول
    if (typeof renderInventory === "function") {
        renderInventory();
    }


    return true;
}


// =====================================================
// برگرداندن موجودی انبار (معکوس stlpDeductInvoiceStock)
// برای لغو حواله‌ای که قبلاً تأیید و کسر شده بود
// =====================================================

function stlpRestoreInvoiceStock(items) {

    const inventory = JSON.parse(
        localStorage.getItem("stlp_inventory") || "[]"
    );

    if (!Array.isArray(inventory)) {
        alert("❌ اطلاعات انبار معتبر نیست.");
        return false;
    }

    if (!Array.isArray(items) || items.length === 0) {
        // حواله‌ی بدون کالا - چیزی برای برگرداندن نیست
        return true;
    }


    items.forEach(function(invoiceItem) {

        const code =
            String(invoiceItem.code || "").trim();

        const qty =
            Number(invoiceItem.qty || 0);

        if (!code || qty <= 0) {
            return;
        }


        const inventoryItem =
            inventory.find(function(item) {

                return String(item.code || "").trim() === code;

            });


        if (!inventoryItem) {

            // کالا ممکن است از انبار حذف شده باشد؛
            // برگرداندن موجودی برای این ردیف صرف‌نظر می‌شود
            // ولی روند لغو حواله متوقف نمی‌شود.

            console.warn(
                "⚠️ کالای «" +
                code +
                "» برای برگرداندن موجودی در انبار پیدا نشد."
            );

            return;

        }


        const oldStock =
            Number(inventoryItem.stock || 0);


        inventoryItem.stock =
            oldStock + qty;


        // دسته‌ی FIFO معادل همین مقدار را هم برمی‌گردانیم — وگرنه
        // «موجودی» و «جمعِ دسته‌های FIFO» از هم فاصله می‌گیرند و
        // فروش‌های بعدی به‌جای مصرفِ لات واقعی، به شاخه‌ی تقریبیِ
        // «آخرین قیمت خرید» می‌افتند. بهای واحد را از همان چیزی
        // می‌گیریم که موقع تأییدِ همین حواله واقعاً مصرف شده بود
        // (stlpDeductInvoiceStock آن را روی خودِ ردیف ذخیره کرده)
        if (typeof stlpRestoreInventoryLot === "function") {

            const unitCost =
                Number(
                    invoiceItem.unitCostAtSale ??
                    inventoryItem.purchasePrice ??
                    0
                );

            stlpRestoreInventoryLot(code, qty, unitCost);

        }


        stlpLogInventoryMovement({

            type: "in",
            itemCode: inventoryItem.code || "",
            itemName: inventoryItem.name || "",
            quantity: qty,
            date: new Date().toLocaleDateString("fa-IR"),
            reason: "برگشت",
            document: "",
            notes: "برگرداندن موجودی بابت لغو حواله فروش تأییدشده",
            stockBefore: oldStock,
            stockAfter: inventoryItem.stock

        });


        console.log(
            "برگرداندن موجودی:",
            inventoryItem.name,
            "| کد:",
            inventoryItem.code,
            "| موجودی قبلی:",
            oldStock,
            "| مقدار برگشتی:",
            qty,
            "| موجودی جدید:",
            inventoryItem.stock
        );

    });


    // ذخیره انبار

    localStorage.setItem(
        "stlp_inventory",
        JSON.stringify(inventory)
    );


    if (typeof inventoryItems !== "undefined") {
        inventoryItems = inventory;
    }


    if (typeof renderInventory === "function") {
        renderInventory();
    }


    return true;
}


// =====================================================
// رزرو موجودی برای فاکتوری که تازه ثبت شده ولی حواله‌اش هنوز
// تأیید نشده — یک نگه‌داشتِ نرم روی فیلدِ جداگانه‌ی reserved،
// نه کسرِ واقعیِ stock (آن کسر واقعی همچنان فقط موقع تأیید
// حواله، توسط stlpDeductInvoiceStock، اتفاق می‌افتد). هدف این
// است که موجودیِ همین کالاها به یک فاکتورِ دیگرِ در انتظار
// فروخته نشود، بدون اینکه هنوز واقعاً از انبار کسر شده باشد.
// =====================================================

function stlpReserveInvoiceStock(items) {

    const inventory = JSON.parse(
        localStorage.getItem("stlp_inventory") || "[]"
    );

    if (!Array.isArray(inventory)) {
        alert("❌ اطلاعات انبار معتبر نیست.");
        return false;
    }

    if (!Array.isArray(items) || items.length === 0) {
        alert("❌ کالایی برای رزرو موجودی وجود ندارد.");
        return false;
    }


    // ابتدا همه کالاها را بررسی می‌کنیم (جمع تعداد هر کد، برای
    // حالتی که یک کد چند بار در همین فاکتور تکرار شده باشد)
    const requestedByCode = {};

    for (const invoiceItem of items) {

        const code =
            String(invoiceItem.code || "").trim();

        const qty =
            Number(invoiceItem.qty || 0);

        if (!code || qty <= 0) {
            continue;
        }

        const inventoryItem =
            inventory.find(function(item) {
                return String(item.code || "").trim() === code;
            });

        if (!inventoryItem) {

            alert(
                "❌ کالای «" +
                code +
                "» در انبار پیدا نشد."
            );

            return false;
        }

        const available =
            Number(inventoryItem.stock || 0) -
            Number(inventoryItem.reserved || 0);

        requestedByCode[code] = (requestedByCode[code] || 0) + qty;

        if (requestedByCode[code] > available) {

            alert(
                "❌ موجودی قابل‌فروشِ کالای «" +
                (inventoryItem.name || code) +
                "» کافی نیست (بخشی از موجودی برای فاکتورهای دیگر رزرو شده است).\n\n" +
                "موجودی قابل‌فروش: " +
                available.toLocaleString("fa-IR") +
                "\n" +
                "تعداد درخواستی: " +
                requestedByCode[code].toLocaleString("fa-IR")
            );

            return false;
        }

    }


    // رزرو را اعمال می‌کنیم
    for (const code in requestedByCode) {

        const inventoryItem =
            inventory.find(function(item) {
                return String(item.code || "").trim() === code;
            });

        if (!inventoryItem) continue;

        inventoryItem.reserved =
            Number(inventoryItem.reserved || 0) + requestedByCode[code];

    }


    localStorage.setItem(
        "stlp_inventory",
        JSON.stringify(inventory)
    );

    if (typeof inventoryItems !== "undefined") {
        inventoryItems = inventory;
    }

    if (typeof renderInventory === "function") {
        renderInventory();
    }

    return true;
}


// معکوسِ stlpReserveInvoiceStock — رزروِ کالاهای یک حواله را آزاد
// می‌کند (چه چون حواله تأیید و به کسرِ واقعی تبدیل شد، چه چون رد
// شد و اصلاً فروشی اتفاق نیفتاد). فقط روی reserved اثر می‌گذارد،
// کاری به stock ندارد.

function stlpReleaseInvoiceReservation(items) {

    const inventory = JSON.parse(
        localStorage.getItem("stlp_inventory") || "[]"
    );

    if (!Array.isArray(inventory)) {
        return false;
    }

    if (!Array.isArray(items) || items.length === 0) {
        return true;
    }

    items.forEach(function(invoiceItem) {

        const code =
            String(invoiceItem.code || "").trim();

        const qty =
            Number(invoiceItem.qty || 0);

        if (!code || qty <= 0) return;

        const inventoryItem =
            inventory.find(function(item) {
                return String(item.code || "").trim() === code;
            });

        if (!inventoryItem) return;

        inventoryItem.reserved =
            Math.max(0, Number(inventoryItem.reserved || 0) - qty);

    });

    localStorage.setItem(
        "stlp_inventory",
        JSON.stringify(inventory)
    );

    if (typeof inventoryItems !== "undefined") {
        inventoryItems = inventory;
    }

    if (typeof renderInventory === "function") {
        renderInventory();
    }

    return true;
}


// =====================================================
// اعمال یک خرید روی انبار: افزایش موجودی کالای موجود،
// یا ساخت کالای جدید در انبار اگر کد قبلاً وجود نداشت
// items: [{code, desc, qty, unit, unitPrice}]
// =====================================================

// =====================================================
// ردیابی دسته‌ای (FIFO) برای محاسبه‌ی دقیق COGS
// هر خرید (یا موجودی اولیه) یک «دسته» با قیمت مخصوص خودش می‌سازد؛
// هر فروش دقیقاً از قدیمی‌ترین دسته مصرف می‌کند و آن قیمت را
// برای همیشه روی همان ردیف فروش ذخیره می‌کند — تغییر قیمت خرید
// بعدی، فروش‌های گذشته را دیگر تحت‌تأثیر قرار نمی‌دهد.
// =====================================================

function stlpLoadInventoryLots() {

    try {

        const lots = JSON.parse(localStorage.getItem("stlp_inventory_lots") || "[]");
        return Array.isArray(lots) ? lots : [];

    } catch (error) {

        return [];

    }

}


function stlpSaveInventoryLots(lots) {

    localStorage.setItem("stlp_inventory_lots", JSON.stringify(lots));

}


function stlpCreateInventoryLot(itemCode, qty, unitCost, source, deliveryId) {

    const code = String(itemCode || "").trim();
    qty = Number(qty || 0);

    if (!code || qty <= 0) return;

    const lots = stlpLoadInventoryLots();

    lots.push({

        id: "lot_" + Date.now().toString(36) + Math.random().toString(36).substring(2, 7),
        itemCode: code,
        qty: qty,
        remainingQty: qty,
        unitCost: Number(unitCost || 0),
        date: new Date().toLocaleDateString("fa-IR"),
        createdAt: new Date().toISOString(),
        source: source || "",
        // اگر این دسته از یک حواله‌ی خرید ساخته شده، شناسه‌ی همان
        // حواله اینجا ذخیره می‌شود — تا اگر آن خرید بعداً لغو شد،
        // دقیقاً همین دسته (نه قدیمی‌ترین دسته‌ی FIFO) برگردانده شود
        deliveryId: deliveryId || ""

    });

    stlpSaveInventoryLots(lots);

}


// مصرف FIFO از قدیمی‌ترین دسته‌های یک کالا؛ بهای واقعی مصرف‌شده را برمی‌گرداند
function stlpConsumeInventoryLotsFIFO(itemCode, qty) {

    const code = String(itemCode || "").trim();
    let remaining = Number(qty || 0);
    let totalCost = 0;

    const lots = stlpLoadInventoryLots();

    const relevant = lots
        .filter(function(l) { return l.itemCode === code && l.remainingQty > 0; })
        .sort(function(a, b) { return new Date(a.createdAt) - new Date(b.createdAt); });

    relevant.forEach(function(lot) {

        if (remaining <= 0) return;

        const take = Math.min(lot.remainingQty, remaining);

        totalCost += take * lot.unitCost;
        lot.remainingQty -= take;
        remaining -= take;

    });

    // اگر دسته‌ای برای بخشی از این مقدار وجود نداشت (مثلاً موجودی خیلی قدیمی
    // که قبل از راه‌اندازی سیستم دسته‌بندی ثبت شده)، آن باقیمانده را با
    // آخرین «قیمت خرید» شناخته‌شده‌ی کالا تقریب می‌زنیم
    if (remaining > 0) {

        try {

            const inventory = JSON.parse(localStorage.getItem("stlp_inventory") || "[]");
            const item = Array.isArray(inventory)
                ? inventory.find(function(i) { return String(i.code || "").trim() === code; })
                : null;

            const fallbackCost = item ? Number(item.purchasePrice || 0) : 0;

            totalCost += remaining * fallbackCost;

        } catch (error) {

            // نادیده گرفته می‌شود

        }

        remaining = 0;

    }

    stlpSaveInventoryLots(lots);

    return {
        totalCost: totalCost,
        avgUnitCost: Number(qty) > 0 ? totalCost / Number(qty) : 0
    };

}


// وقتی حواله‌ای که قبلاً تأیید و مصرف‌شده لغو/رد می‌شود، دسته‌ی معادل
// همان بها دوباره ساخته می‌شود تا موجودی و بهایش با هم برگردند
function stlpRestoreInventoryLot(itemCode, qty, unitCost) {

    stlpCreateInventoryLot(itemCode, qty, unitCost, "بازگشت از حواله لغوشده");

}


function stlpApplyPurchaseToInventory(items, supplierName, deliveryId) {

    const inventory = JSON.parse(
        localStorage.getItem("stlp_inventory") || "[]"
    );

    if (!Array.isArray(inventory)) {
        alert("❌ اطلاعات انبار معتبر نیست.");
        return false;
    }

    if (!Array.isArray(items) || items.length === 0) {
        return true;
    }


    items.forEach(function(purchaseItem) {

        let code =
            String(purchaseItem.code || "").trim();

        const qty =
            Number(purchaseItem.qty || 0);

        if (!code || qty <= 0) {
            return;
        }


        // فرمِ خرید کد را بدونِ حساسیت به بزرگی/کوچکیِ حروف با انبار
        // تطبیق می‌دهد (و برای کدِ موجود، بخشِ «کالای جدید» را نشان
        // نمی‌دهد)؛ اگر این‌جا مقایسه دقیق (===) بود، «abc» به‌جای
        // «ABC» یک کالای تکراریِ بی‌مشخصات می‌ساخت
        const existing =
            inventory.find(function(item) {
                return String(item.code || "").trim().toLowerCase() === code.toLowerCase();
            });

        if (existing) code = String(existing.code || "").trim();


        let stockBefore = 0;
        let stockAfter = 0;
        let itemName = purchaseItem.desc || code;

        if (existing) {

            stockBefore =
                Number(existing.stock || 0);

            existing.stock =
                stockBefore + qty;

            stockAfter = existing.stock;
            itemName = existing.name || itemName;

            // قیمت خرید را با آخرین خرید به‌روز می‌کنیم
            // (قیمت فروش دست‌نخورده می‌ماند). از != null (نه truthy)
            // استفاده می‌شود چون قیمت صفر هم یک مقدار واقعی است — مثلاً
            // برای خریدهای نمونه‌ی رایگان — و نباید نادیده گرفته شود
            // (قبلاً با if(purchaseItem.unitPrice) یک خرید با قیمت صفر
            // اصلاً purchasePrice را به‌روز نمی‌کرد و همان قیمت قدیمی
            // می‌ماند، در حالی که لاتِ FIFO همین خرید را با هزینه‌ی صفر
            // ثبت می‌کرد — یعنی دو منبع داده با هم ناسازگار می‌شدند)

            // مقدارِ قبلیِ چیزهایی که این خرید رویشان می‌نویسد روی خودِ
            // ردیفِ حواله ذخیره می‌شود تا اگر همین خرید بعداً لغو شد،
            // برگردانده شوند (قبلاً قیمتِ خرید/نسبت‌ها برای همیشه مقدارِ
            // خریدِ لغوشده می‌ماندند)
            if (purchaseItem.prevPurchasePrice === undefined) {
                purchaseItem.prevPurchasePrice = Number(existing.purchasePrice || 0);
                purchaseItem.prevPackagesPerCarton = Number(existing.packagesPerCarton || 1);
                purchaseItem.prevPiecesPerPackage = Number(existing.piecesPerPackage || 1);
            }

            if (purchaseItem.unitPrice !== undefined && purchaseItem.unitPrice !== null && purchaseItem.unitPrice !== "") {
                existing.purchasePrice = Number(purchaseItem.unitPrice);
            }

            // نسبتِ تبدیلِ کارتن/عدد به بسته می‌تونه بینِ خریدهای مختلف
            // فرق کنه (مثلاً این‌بار کارتن‌بندیِ متفاوتی رسیده)؛ اگر این
            // خرید صریحاً نسبتی داده، همون رو به‌عنوانِ نسبتِ فعلیِ کالا
            // به‌روز می‌کنیم — اگر نداده (خرید بر مبنای خودِ بسته بوده)،
            // نسبتِ قبلیِ کالا دست‌نخورده می‌ماند
            if (purchaseItem.packagesPerCarton !== undefined) {
                existing.packagesPerCarton = Number(purchaseItem.packagesPerCarton);
            }

            if (purchaseItem.piecesPerPackage !== undefined) {
                existing.piecesPerPackage = Number(purchaseItem.piecesPerPackage);
            }

            console.log(
                "افزایش موجودی از خرید:",
                existing.name || existing.code,
                "| موجودی قبلی:", stockBefore,
                "| مقدار خریداری‌شده:", qty,
                "| موجودی جدید:", existing.stock
            );

        } else {

            // کالای جدید - قبلاً در انبار نبوده
            // فیلدها با ساختار کامل انبار هماهنگ می‌شوند

            stockBefore = 0;
            stockAfter = qty;

            // علامتِ «این خرید این کالا را ساخته» — برای لغوِ همین خرید
            // (stlpReversePurchaseFromInventory) تا کالای ساخته‌شده با
            // موجودیِ صفر در انبار یتیم نماند
            purchaseItem.createdNewItem = true;

            inventory.push({

                // بارکد/دسته‌بندی/برند/تولیدکننده/تاریخ تولید/Batch/
                // تاریخ انقضا/حداقل موجودی/محل نگهداری/عکس: اگر فرمِ
                // ثبتِ خرید (چون این کد جدید بوده) این جزئیات رو گرفته
                // باشه، همون‌ها استفاده می‌شن؛ وگرنه (حواله‌های قدیمی‌تر
                // که این فیلدها رو نداشتن) مثلِ قبل خالی/پیش‌فرض می‌مونن
                code: code,
                barcode: purchaseItem.barcode || "",
                name: itemName,
                category: purchaseItem.category || "",
                brand: purchaseItem.brand || "",
                manufacturer: purchaseItem.manufacturer || "",
                unit: purchaseItem.unit || "بسته",
                purchasePrice: Number(purchaseItem.unitPrice || 0),
                // قیمتِ فروش باید جدا از قیمتِ خرید باشه (اختلافشون سوده)؛
                // اگر فرمِ خرید صریحاً قیمتِ فروش گرفته باشه همون استفاده
                // می‌شه، وگرنه (فقط برای این‌که کالا صفر نمونه) موقتاً
                // مساویِ قیمتِ خرید می‌مونه تا بعداً دستی اصلاح بشه
                // قیمتِ فروشِ پیش‌فرض (وقتی صریحاً داده نشده) گرد می‌شود —
                // قیمتِ خریدِ هر بسته بعد از تبدیل از کارتن/عدد ممکن است
                // اعشاری باشد، ولی فروشگاه آنلاین فقط قیمتِ صحیح می‌پذیرد
                price: Math.round(Number(purchaseItem.salePrice !== undefined && purchaseItem.salePrice !== null && purchaseItem.salePrice !== "" ? purchaseItem.salePrice : (purchaseItem.unitPrice || 0))),
                packagesPerCarton: Number(purchaseItem.packagesPerCarton || 1),
                piecesPerPackage: Number(purchaseItem.piecesPerPackage || 1),
                mfg: purchaseItem.mfg || "",
                batch: purchaseItem.batch || "",
                exp: purchaseItem.exp || "",
                stock: qty,
                minStock: Number(purchaseItem.minStock || 5),
                location: purchaseItem.location || "",
                supplier: supplierName || "",
                status: "active",
                notes: "ایجادشده خودکار از ثبت خرید",
                image: purchaseItem.image || ""

            });

            console.log(
                "کالای جدید از خرید به انبار اضافه شد:",
                itemName,
                "| موجودی اولیه:", qty
            );

        }


        // ساخت دسته‌ی (لات) جدید برای این خرید — پایه‌ی محاسبه‌ی COGS دقیق
        stlpCreateInventoryLot(
            code,
            qty,
            Number(purchaseItem.unitPrice || 0),
            (supplierName ? "خرید از " + supplierName : "ثبت خرید"),
            deliveryId
        );


        stlpLogInventoryMovement({

            type: "in",
            itemCode: code,
            itemName: itemName,
            quantity: qty,
            date: new Date().toLocaleDateString("fa-IR"),
            reason: "خرید",
            document: "",
            notes:
                supplierName
                    ? "خرید از " + supplierName
                    : "ثبت خرید",
            stockBefore: stockBefore,
            stockAfter: stockAfter

        });

    });


    localStorage.setItem(
        "stlp_inventory",
        JSON.stringify(inventory)
    );

    if (typeof inventoryItems !== "undefined") {
        inventoryItems = inventory;
    }

    if (typeof renderInventory === "function") {
        renderInventory();
    }

    return true;

}


// =====================================================
// معکوسِ stlpApplyPurchaseToInventory — برای وقتی که یک
// حواله‌ی خریدِ قبلاً تأییدشده لغو می‌شود.
//
// قبلاً این حالت با صدا زدنِ stlpDeductInvoiceStock انجام
// می‌شد که یک تابعِ فروش است و همیشه از قدیمی‌ترین دسته‌ی
// FIFO مصرف می‌کند — یعنی لغوِ یک خرید، دسته‌ی درستِ خودش را
// برنمی‌گرداند، بلکه دسته‌ای کاملاً نامرتبط (با قیمت متفاوت)
// را می‌خورد و تاریخچه‌ی بهای تمام‌شده را برای همیشه خراب
// می‌کند. حالا دقیقاً همان دسته‌ای که خودِ این خرید ساخته بود
// (با deliveryId مشخص می‌شود) کم/حذف می‌شود.
// =====================================================

function stlpReversePurchaseFromInventory(items, deliveryId) {

    const inventory = JSON.parse(
        localStorage.getItem("stlp_inventory") || "[]"
    );

    if (!Array.isArray(inventory)) {
        alert("❌ اطلاعات انبار معتبر نیست.");
        return false;
    }

    if (!Array.isArray(items) || items.length === 0) {
        return true;
    }

    const lots = stlpLoadInventoryLots();

    const stlpOrphanCodes = [];

    items.forEach(function(purchaseItem) {

        const code = String(purchaseItem.code || "").trim();
        const qty = Number(purchaseItem.qty || 0);

        if (!code || qty <= 0) return;

        const inventoryItem = inventory.find(function(item) {
            return String(item.code || "").trim().toLowerCase() === code.toLowerCase();
        });

        if (inventoryItem) {

            const oldStock = Number(inventoryItem.stock || 0);

            inventoryItem.stock = Math.max(0, oldStock - qty);

            stlpLogInventoryMovement({
                type: "out",
                itemCode: inventoryItem.code || code,
                itemName: inventoryItem.name || code,
                quantity: qty,
                date: new Date().toLocaleDateString("fa-IR"),
                reason: "لغو خرید",
                document: "",
                notes: "برگرداندن موجودی بابت لغو حواله‌ی خرید تأییدشده",
                stockBefore: oldStock,
                stockAfter: inventoryItem.stock
            });

            // آنچه این خرید روی خودِ کالا نوشته برمی‌گردد — فقط اگر هنوز
            // همان مقدارِ این خرید است (اگر خریدِ بعدی عوضش کرده، دست
            // نمی‌خورد)
            if (!purchaseItem.createdNewItem) {

                if (purchaseItem.prevPurchasePrice !== undefined &&
                    Number(inventoryItem.purchasePrice) === Number(purchaseItem.unitPrice)) {
                    inventoryItem.purchasePrice = purchaseItem.prevPurchasePrice;
                }

                if (purchaseItem.packagesPerCarton !== undefined && purchaseItem.prevPackagesPerCarton !== undefined &&
                    Number(inventoryItem.packagesPerCarton) === Number(purchaseItem.packagesPerCarton)) {
                    inventoryItem.packagesPerCarton = purchaseItem.prevPackagesPerCarton;
                }

                if (purchaseItem.piecesPerPackage !== undefined && purchaseItem.prevPiecesPerPackage !== undefined &&
                    Number(inventoryItem.piecesPerPackage) === Number(purchaseItem.piecesPerPackage)) {
                    inventoryItem.piecesPerPackage = purchaseItem.prevPiecesPerPackage;
                }

            } else if (inventoryItem.stock <= 0 && Number(inventoryItem.reserved || 0) <= 0) {

                // خودِ این خرید این کالا را ساخته بود و حالا موجودی‌ای
                // ندارد — با لغوِ خرید نباید یک کالای صفر و بی‌صاحاب بماند
                stlpOrphanCodes.push(inventoryItem.code);

            }

        }

        // دقیقاً همان دسته‌(های)ی همین خرید را پیدا و کم/حذف کن —
        // نه قدیمی‌ترین دسته‌ی کالا را (که FIFO معمولی این کار را می‌کرد)
        let remaining = qty;

        const lotCode = inventoryItem ? String(inventoryItem.code || "").trim() : code;

        const ownLots = lots
            .filter(function(l) {
                return l.itemCode === lotCode &&
                    l.deliveryId === deliveryId &&
                    l.remainingQty > 0;
            })
            .sort(function(a, b) {
                return new Date(b.createdAt) - new Date(a.createdAt);
            });

        ownLots.forEach(function(lot) {

            if (remaining <= 0) return;

            const take = Math.min(lot.remainingQty, remaining);

            lot.remainingQty -= take;
            remaining -= take;

        });

        if (remaining > 0) {

            // بخشی از این خرید قبل از لغو، قبلاً فروخته شده (لات
            // خودش کامل مصرف شده) — دیگر نمی‌شود دقیقاً همان مقدار
            // را از جای دیگری کم کرد بدون خراب‌کردنِ بهای یک فروشِ
            // واقعی‌ِ دیگر، پس فقط هشدار می‌دهیم و همان مقدار را
            // در تاریخچه‌ی دسته‌ها نادیده می‌گیریم.
            console.warn(
                "⚠️ لغو خرید: " + remaining +
                " عدد از کالای " + code +
                " قبل از لغو از دسته‌ی همین خرید مصرف/فروخته شده بود؛ " +
                "دسته‌ی دیگری برای برگرداندن آن دست‌کاری نشد."
            );

        }

    });

    stlpOrphanCodes.forEach(function(orphanCode) {

        const at = inventory.findIndex(function(i) { return i.code === orphanCode; });

        if (at >= 0) inventory.splice(at, 1);

    });

    stlpSaveInventoryLots(lots);

    localStorage.setItem(
        "stlp_inventory",
        JSON.stringify(inventory)
    );

    if (typeof inventoryItems !== "undefined") {
        inventoryItems = inventory;
    }

    if (typeof renderInventory === "function") {
        renderInventory();
    }

    return true;

}


// =====================================================
// تأیید حواله فروش
// =====================================================

// ============================================
// ثبت نهایی فاکتور
// ============================================

// ============================================
// ثبت کامل و نهایی فاکتور
// ============================================

async function stlpSaveInvoice(exportFormat) {

    // ========================================
    // انتخاب مشتری
    // ========================================

    const customerSelect =
        document.getElementById("customerSelect");

    if (!customerSelect || !customerSelect.value) {

        alert("لطفاً ابتدا مشتری را انتخاب کنید.");

        return;
    }


    const customers =
        stlpLoadCustomersEnsuringIds();


    const customer =
        customers.find(function(c) { return c.id === customerSelect.value; });


    if (!customer) {

        alert("اطلاعات مشتری پیدا نشد.");

        return;
    }


    // ========================================
    // نوع خرید
    // ========================================

    const purchaseTypeElement =
        document.getElementById("purchaseType");


    const purchaseType =
        purchaseTypeElement?.value === "credit"
            ? "credit"
            : "cash";


    // ========================================
    // جمع‌آوری کالاها
    // ========================================

    const items = [];


    for (let i = 1; i < rowIndex; i++) {

        const select =
            document.getElementById("select_" + i);


        if (!select || !select.value) {
            continue;
        }


        const code =
            document.getElementById("code_" + i)?.value || "";


        const desc =
            document.getElementById("desc_" + i)?.value || "";


        const unit =
            document.getElementById("unit_" + i)?.value || "";


        const qty =
            Number(
                document.getElementById("qty_" + i)?.value || 0
            );


        const price =
            Number(
                document.getElementById("price_" + i)?.value || 0
            );


        const discount =
            Math.min(100, Math.max(0, Number(
                document.getElementById("discount_" + i)?.value || 0
            )));


        const total =
            Number(
                (
                    document.getElementById("total_" + i)
                    ?.innerText || "0"
                ).replace(/,/g, "")
            );


        const afterDisc =
            Number(
                (
                    document.getElementById("afterDisc_" + i)
                    ?.innerText || "0"
                ).replace(/,/g, "")
            );


        const tax =
            Number(
                (
                    document.getElementById("tax_" + i)
                    ?.innerText || "0"
                ).replace(/,/g, "")
            );


        const final =
            Number(
                (
                    document.getElementById("final_" + i)
                    ?.innerText || "0"
                ).replace(/,/g, "")
            );


        // ========================================
        // بررسی تعداد
        // ========================================

        if (qty <= 0) {

            alert(
                "تعداد کالا در ردیف " +
                i +
                " معتبر نیست."
            );

            return;
        }


        // ========================================
        // افزودن کالا
        // ========================================

        items.push({

            row: i,

            code: code,

            name: desc,

            unit: unit,

            qty: qty,

            price: price,

            total: total,

            discount: discount,

            afterDiscount: afterDisc,

            tax: tax,

            final: final

        });

    }


    // ========================================
    // حداقل یک کالا
    // ========================================

    if (items.length === 0) {

        alert(
            "لطفاً حداقل یک کالا به فاکتور اضافه کنید."
        );

        return;
    }


    // ========================================
    // رزرو موجودی — قبل از گرفتن شماره‌ی فاکتور، تا اگر موجودیِ
    // قابل‌فروش کافی نبود، هیچ شماره‌ای هم هدر نرود
    // ========================================

    if (!stlpReserveInvoiceStock(items)) {
        return;
    }


    // ========================================
    // شماره فاکتور
    // ========================================

    let invoiceNo;

    try {
        invoiceNo = await getNextInvoiceNumber();
    } catch (error) {
        // رزروی که چند خط بالاتر انجام شد باید آزاد شود، وگرنه این
        // موجودی برای همیشه «رزروشده» می‌ماند بدونِ هیچ فاکتوری که
        // آن را آزاد/تأیید کند
        stlpReleaseInvoiceReservation(items);
        alert("شماره‌ی فاکتور از سرور دریافت نشد؛ اتصال را بررسی کنید و دوباره تلاش کنید.");
        return;
    }


    // ========================================
    // تاریخ
    // ========================================

    const date =
        new Date().toLocaleDateString("fa-IR");


    // ========================================
    // مالیات
    // ========================================

    const taxRate =
        Number(
            document.getElementById("taxRate")?.value || 0
        );


    // ========================================
    // جمع نهایی
    // ========================================

    const finalTotal =
        document.getElementById("finalTotal")
        ?.innerText || "0 ریال";


    // ========================================
    // ساخت فاکتور
    // ========================================

    const invoice = {

        id:
            "inv_" +
            Date.now().toString(36) +
            Math.random().toString(36).substring(2, 8),

        invoiceNo: invoiceNo,

        date: date,

        taxRate: taxRate,

        customer:
            customer.name || "-",

        customerObj:
            customer,

        purchaseType:
            purchaseType,

        items:
            items,

        total:
            finalTotal,

        createdAt:
            new Date().toISOString()

    };


    // ========================================
    // دریافت فاکتورهای قبلی
    // ========================================

    // ========================================
    // بررسی موجودی قبل از ذخیره
    // ========================================

    // ========================================
    // ذخیره فاکتور — اتمیک روی سرور (نه خواندنِ کاملِ آرایه +
    // نوشتنِ کاملِ آن، که اگر دو نفر هم‌زمان فاکتور ثبت می‌کردند،
    // یکی از دو فاکتور را گم می‌کرد)
    // ========================================

    stlpAppendToStoreArraySync("invoices", invoice, "invoiceNo", invoice.invoiceNo);

    stlpLogActivity(
        "فاکتور فروش",
        "ثبت فاکتور",
        "فاکتور شماره " + invoiceNo + " — «" + (customer.name || "-") + "» — " + stlpParseMoney(finalTotal).toLocaleString("fa-IR") + " ریال"
    );

    // ========================================
// ساخت حواله فروش
// ========================================

// شماره حواله مستقل از شماره فاکتور — اتمیک از سرور
const deliveryNo =
    getNextSalesDeliveryNumber();


const delivery = {

    id:
        "dlv_" +
        Date.now().toString(36) +
        Math.random().toString(36).substring(2, 8),

    deliveryNo: deliveryNo,

    invoiceNo: invoiceNo,

    date: date,

    customer:
        customer.name || "-",

    customerObj:
        customer,

    purchaseType:
        purchaseType,

    items:
        items,

    total:
        finalTotal,

    status:
        "pending",

    stockDeducted:
        false,

    createdAt:
        new Date().toISOString()

};


stlpAppendToStoreArraySync("salesDeliveries", delivery, "id", delivery.id);


    // ========================================
    // ثبت در خزانه
    // فقط فاکتور نقدی
    // ========================================

    // ========================================
    // ساخت خروجی اکسل / PDF (اختیاری)
    // ========================================

    if (exportFormat === "excel" || exportFormat === "pdf") {

        const opts = {

            code: String(invoiceNo),

            dateFa: date,

            buyerName: customer.name || "",
            buyerAddress: customer.address || "",
            buyerPhone: customer.phone || "",
            buyerEconCode: customer.econCode || "",
            buyerRegNo: customer.regNo || "",
            buyerProvince: customer.province || "",
            buyerCity: customer.city || "",
            buyerPostalCode: customer.postalCode || "",
            buyerNationalId: customer.nationalId || "",

            purchaseType: purchaseType,
            isCash: purchaseType !== "credit",

            items: items.map(function(it) {

                return {
                    code: it.code,
                    desc: it.name,
                    unit: it.unit,
                    qty: it.qty,
                    unitPrice: it.price,
                    discPercent: it.discount
                };

            })

        };

        try {

            if (exportFormat === "excel") {

                const blob = await stlpGenerateInvoiceXLSX(opts);

                if (blob) {
                    stlpDownloadBlob(blob, "فاکتور-" + invoiceNo + ".xlsx");
                }

            } else {

                // فاکتور تازه ثبت‌شده — حواله‌ی فروشش هنوز حتماً
                // pending است (چند خط بالاتر همین الان ساخته شد)،
                // پس این دانلود همیشه نسخه‌ی «در انتظار تأیید» را
                // نشان می‌دهد؛ بعد از تأیید حواله، چاپ مجدد از
                // گزارش فاکتورها (reprintInvoice) نسخه‌ی نهایی را
                // با شماره و مهر/امضا نشان می‌دهد.
                const approved = stlpIsInvoiceApproved(invoiceNo);

                await stlpGenerateInvoicePDF({
                    ...opts,
                    code: approved ? String(invoiceNo) : "در انتظار تأیید حواله",
                    isApproved: approved
                });

            }

        } catch (error) {

            console.error("خطا در ساخت فایل فاکتور:", error);

            alert(
                "⚠️ فاکتور ثبت شد ولی ساخت فایل خروجی با خطا مواجه شد:\n" +
                (error.message || error)
            );

        }

    }


    // ========================================
    // پیام موفقیت
    // ========================================

    const purchaseTypeText =
        purchaseType === "credit"
            ? "غیر نقدی"
            : "نقدی";


    alert(
    "✅ فاکتور شماره " +
    invoiceNo +
    " با موفقیت ثبت شد.\n\n" +

    "📦 حواله فروش شماره " +
    deliveryNo +
    " ایجاد شد.\n\n" +

    "نوع خرید: " +
    purchaseTypeText +
    "\n\n" +

    "📦 موجودی این کالاها رزرو شد؛ با تأیید حواله به‌صورت قطعی از انبار کسر می‌شود."
);


    // ========================================
    // بازنشانی فرم
    // ========================================

    resetInvoiceForm();

    return invoice;

}
function getNextSalesDeliveryNumberLocal() {

    const deliveries =
        JSON.parse(
            localStorage.getItem("salesDeliveries") || "[]"
        );


    if (deliveries.length === 0) {
        return 1;
    }


    const numbers =
        deliveries
            .map(d => Number(d.deliveryNo) || 0)
            .filter(n => n > 0);


    if (numbers.length === 0) {
        return 1;
    }


    return Math.max(...numbers) + 1;
}


// اتمیک از سرور می‌گیرد تا دو ثبتِ هم‌زمانِ حواله (فروش یا خرید،
// هر دو همین شمارنده را به‌اشتراک می‌گذارند) شماره‌ی تکراری نگیرند؛
// اگر سرور در دسترس نبود، به محاسبه‌ی محلیِ قدیمی (max+۱) برمی‌گردد.
function getNextSalesDeliveryNumber() {

    if (typeof stlpNextCounterFromServerSync === "function") {
        return stlpNextCounterFromServerSync(
            "/api/counter/next-delivery-number",
            getNextSalesDeliveryNumberLocal
        );
    }

    return getNextSalesDeliveryNumberLocal();

}



