/* ===================== STLP XLSX INVOICE ENGINE ===================== */
/* این بخش فاکتور رسمی اکسل (فرمت TTMS) را بر اساس فایل «فاکتور_جدید.xlsx» */
/* که خودتان فرستادید می‌سازد. asset ها (لوگو/فونت) دست نخورده باقی مانده‌اند. */

const STLP_XLSX_TEMPLATE_B64 = "";

function stlpB64ToBytes(b64){
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

/* ---- CRC32 ---- */
const STLP_CRC_TABLE = (function(){
  const t = new Uint32Array(256);
  for(let n=0;n<256;n++){
    let c = n;
    for(let k=0;k<8;k++){
      c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    t[n] = c >>> 0;
  }
  return t;
})();
function stlpCrc32(bytes){
  let crc = 0xFFFFFFFF;
  for(let i=0;i<bytes.length;i++){
    crc = STLP_CRC_TABLE[(crc ^ bytes[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

/* ---- little endian helpers ---- */
function stlpW16(view, off, val){ view.setUint16(off, val, true); }
function stlpW32(view, off, val){ view.setUint32(off, val, true); }
function stlpR16(view, off){ return view.getUint16(off, true); }
function stlpR32(view, off){ return view.getUint32(off, true); }

/* ---- ZIP READ (پشتیبانی از deflate و stored) ---- */
async function stlpUnzip(bytes){
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let eocd = -1;
  const searchFrom = Math.max(0, bytes.length - 66000);
  for(let i=bytes.length-22; i>=searchFrom; i--){
    if(stlpR32(view,i)===0x06054b50){ eocd=i; break; }
  }
  if(eocd<0) throw new Error('ZIP EOCD یافت نشد - فایل قالب خراب است');
  const total = stlpR16(view, eocd+10);
  const cdOff = stlpR32(view, eocd+16);
  const entries = {};
  let p = cdOff;
  const dec = new TextDecoder('utf-8');
  for(let i=0;i<total;i++){
    if(stlpR32(view,p)!==0x02014b50) throw new Error('Central directory خراب است');
    const method = stlpR16(view,p+10);
    const compSize = stlpR32(view,p+20);
    const nameLen = stlpR16(view,p+28);
    const extraLen = stlpR16(view,p+30);
    const commentLen = stlpR16(view,p+32);
    const localOff = stlpR32(view,p+42);
    const name = dec.decode(bytes.subarray(p+46, p+46+nameLen));
    entries[name] = {method, compSize, localOff};
    p += 46 + nameLen + extraLen + commentLen;
  }
  const out = {};
  for(const name in entries){
    const e = entries[name];
    const lp = e.localOff;
    const lNameLen = stlpR16(view, lp+26);
    const lExtraLen = stlpR16(view, lp+28);
    const dataStart = lp + 30 + lNameLen + lExtraLen;
    const raw = bytes.subarray(dataStart, dataStart + e.compSize);
    let data;
    if(e.method === 0){
      data = raw;
    } else if(e.method === 8){
      const ds = new DecompressionStream('deflate-raw');
      const writer = ds.writable.getWriter();
      writer.write(raw);
      writer.close();
      const ab = await new Response(ds.readable).arrayBuffer();
      data = new Uint8Array(ab);
    } else {
      throw new Error('روش فشرده‌سازی پشتیبانی نمی‌شود: '+e.method);
    }
    out[name] = data;
  }
  return out;
}

/* ---- ZIP WRITE (method=0 STORED؛ ساده و بدون نیاز به فشرده‌سازی) ---- */
function stlpZip(files){
  const encoder = new TextEncoder();
  const localParts = [];
  const centralParts = [];
  let offset = 0;
  const now = new Date();
  const dosTime = ((now.getHours()&0x1F)<<11) | ((now.getMinutes()&0x3F)<<5) | (Math.floor(now.getSeconds()/2)&0x1F);
  const dosDate = (((now.getFullYear()-1980)&0x7F)<<9) | (((now.getMonth()+1)&0xF)<<5) | (now.getDate()&0x1F);

  const names = Object.keys(files);
  const offsets = [];
  for(const name of names){
    const nameBytes = encoder.encode(name);
    const data = files[name];
    const crc = stlpCrc32(data);
    const lh = new ArrayBuffer(30);
    const lv = new DataView(lh);
    stlpW32(lv,0,0x04034b50);
    stlpW16(lv,4,20);
    stlpW16(lv,6,0);
    stlpW16(lv,8,0);
    stlpW16(lv,10,dosTime);
    stlpW16(lv,12,dosDate);
    stlpW32(lv,14,crc);
    stlpW32(lv,18,data.length);
    stlpW32(lv,22,data.length);
    stlpW16(lv,26,nameBytes.length);
    stlpW16(lv,28,0);
    offsets.push(offset);
    localParts.push(new Uint8Array(lh), nameBytes, data);
    offset += 30 + nameBytes.length + data.length;
  }

  let cdSize = 0;
  for(let i=0;i<names.length;i++){
    const name = names[i];
    const nameBytes = encoder.encode(name);
    const data = files[name];
    const crc = stlpCrc32(data);
    const ch = new ArrayBuffer(46);
    const cv = new DataView(ch);
    stlpW32(cv,0,0x02014b50);
    stlpW16(cv,4,20);
    stlpW16(cv,6,20);
    stlpW16(cv,8,0);
    stlpW16(cv,10,0);
    stlpW16(cv,12,dosTime);
    stlpW16(cv,14,dosDate);
    stlpW32(cv,16,crc);
    stlpW32(cv,20,data.length);
    stlpW32(cv,24,data.length);
    stlpW16(cv,28,nameBytes.length);
    stlpW16(cv,30,0);
    stlpW16(cv,32,0);
    stlpW16(cv,34,0);
    stlpW16(cv,36,0);
    stlpW32(cv,38,0);
    stlpW32(cv,42,offsets[i]);
    centralParts.push(new Uint8Array(ch), nameBytes);
    cdSize += 46 + nameBytes.length;
  }

  const eocd = new ArrayBuffer(22);
  const ev = new DataView(eocd);
  stlpW32(ev,0,0x06054b50);
  stlpW16(ev,4,0);
  stlpW16(ev,6,0);
  stlpW16(ev,8,names.length);
  stlpW16(ev,10,names.length);
  stlpW32(ev,12,cdSize);
  stlpW32(ev,16,offset);
  stlpW16(ev,20,0);

  let cdTotalLen = 0;
  for(const part of centralParts) cdTotalLen += part.length;
  const totalSize = offset + cdTotalLen + 22;
  const out = new Uint8Array(totalSize);
  let pos = 0;
  for(const part of localParts){ out.set(part,pos); pos += part.length; }
  for(const part of centralParts){ out.set(part,pos); pos += part.length; }
  out.set(new Uint8Array(eocd), pos);
  return out;
}

/* ---- کمکی‌های XML و ستون ---- */
function stlpXmlEsc(s){
  return String(s==null?'':s)
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&apos;');
}
function stlpInlineCell(ref, style, text){
  return '<c r="'+ref+'" s="'+style+'" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(text)+'</t></is></c>';
}
function stlpNumCell(ref, style, num){
  const v = Number.isFinite(num) ? num : 0;
  return '<c r="'+ref+'" s="'+style+'"><v>'+v+'</v></c>';
}
function stlpFormulaCell(ref, style, formula, val){
  return '<c r="'+ref+'" s="'+style+'"><f>'+formula+'</f><v>'+val+'</v></c>';
}
function stlpEmptyCell(ref, style){
  return '<c r="'+ref+'" s="'+style+'"/>';
}
function stlpSharedCell(ref, style, idx){
  return '<c r="'+ref+'" s="'+style+'" t="s"><v>'+idx+'</v></c>';
}
function stlpColToNum(col){
  let n=0;
  for(const ch of col){ n = n*26 + (ch.charCodeAt(0)-64); }
  return n;
}
function stlpNumToCol(n){
  let s='';
  while(n>0){
    const r=(n-1)%26;
    s=String.fromCharCode(65+r)+s;
    n=Math.floor((n-1)/26);
  }
  return s;
}
function stlpColRange(a,b){
  const start=stlpColToNum(a), end=stlpColToNum(b);
  const out=[];
  for(let i=start;i<=end;i++) out.push(stlpNumToCol(i));
  return out;
}

/* ---- عدد به حروف فارسی (برای «جمع به حروف») ---- */
const STLP_ONES = ['', 'یک','دو','سه','چهار','پنج','شش','هفت','هشت','نه'];
const STLP_TENS = ['', 'ده','بیست','سی','چهل','پنجاه','شصت','هفتاد','هشتاد','نود'];
const STLP_TEENS = ['ده','یازده','دوازده','سیزده','چهارده','پانزده','شانزده','هفده','هجده','نوزده'];
const STLP_HUNDREDS = ['', 'صد','دویست','سیصد','چهارصد','پانصد','ششصد','هفتصد','هشتصد','نهصد'];
const STLP_MAGNITUDE = ['', ' هزار', ' میلیون', ' میلیارد', ' تریلیون'];

function stlpThreeDigitWords(n){
  const parts = [];
  const h = Math.floor(n/100);
  const rem = n%100;
  if(h>0) parts.push(STLP_HUNDREDS[h]);
  if(rem>=10 && rem<20){
    parts.push(STLP_TEENS[rem-10]);
  } else {
    const t = Math.floor(rem/10);
    const o = rem%10;
    if(t>0) parts.push(STLP_TENS[t]);
    if(o>0) parts.push(STLP_ONES[o]);
  }
  return parts.join(' و ');
}
function stlpNumberToPersianWords(num){
  num = Math.round(num);
  if(num === 0) return 'صفر ریال';
  if(num < 0) return 'منفی ' + stlpNumberToPersianWords(-num);
  const groups = [];
  let n = num;
  while(n>0){
    groups.push(n % 1000);
    n = Math.floor(n/1000);
  }
  const parts = [];
  for(let i=groups.length-1;i>=0;i--){
    if(groups[i]===0) continue;
    parts.push(stlpThreeDigitWords(groups[i]) + (STLP_MAGNITUDE[i]||''));
  }
  return parts.join(' و ') + ' ریال';
}

/* ---- ساخت ردیف‌های کالا و ردیف‌های جمع/شرایط/امضا ---- */
function stlpBuildItemRow(r, idx, code, desc, qty, price, discPercent, unit){
  const amount = qty*price;
  const afterDisc = Math.round(amount - (discPercent/100)*amount);
  const tax = 0; /* طبق درخواست: مالیات صفر */
  const total = afterDisc + tax;
  let s = '<row r="'+r+'" spans="2:63" ht="27.75" customHeight="1">';
  s += stlpNumCell('B'+r,24,idx);
  s += stlpEmptyCell('C'+r,24);
  s += stlpInlineCell('D'+r,25,code);
  s += stlpEmptyCell('E'+r,25);
  s += stlpEmptyCell('F'+r,25);
  s += stlpInlineCell('G'+r,26,desc);
  stlpColRange('H','S').forEach(c=>{ s+=stlpEmptyCell(c+r,26); });
  s += stlpNumCell('T'+r,27,qty);
  s += stlpInlineCell('U'+r,24, unit || 'بسته'); /* واحد واقعی کالا (از انبار)، در نبود آن پیش‌فرض "بسته" */
  s += stlpEmptyCell('V'+r,24);
  s += stlpEmptyCell('W'+r,24);
  s += stlpNumCell('X'+r,28,price);
  stlpColRange('Y','AB').forEach(c=>{ s+=stlpEmptyCell(c+r,28); });
  s += stlpFormulaCell('AC'+r,28,'T'+r+'*X'+r, amount);
  stlpColRange('AD','AI').forEach(c=>{ s+=stlpEmptyCell(c+r,28); });
  s += stlpNumCell('AJ'+r,28,discPercent||0);
  stlpColRange('AK','AN').forEach(c=>{ s+=stlpEmptyCell(c+r,28); });
  s += stlpFormulaCell('AO'+r,28,'AC'+r+'-(AJ'+r+'/100)*AC'+r, afterDisc);
  stlpColRange('AP','AU').forEach(c=>{ s+=stlpEmptyCell(c+r,28); });
  s += stlpNumCell('AV'+r,28,0);
  stlpColRange('AW','AZ').forEach(c=>{ s+=stlpEmptyCell(c+r,28); });
  s += stlpFormulaCell('BA'+r,28,'AO'+r+'+AV'+r, total);
  stlpColRange('BB','BH').forEach(c=>{ s+=stlpEmptyCell(c+r,28); });
  s += '</row>';
  return {xml:s, amount, afterDisc, tax, total};
}
function stlpItemRowMerges(r){
  return ['B'+r+':C'+r,'D'+r+':F'+r,'G'+r+':S'+r,'U'+r+':W'+r,'X'+r+':AB'+r,'AC'+r+':AI'+r,'AJ'+r+':AN'+r,'AO'+r+':AU'+r,'AV'+r+':AZ'+r,'BA'+r+':BH'+r];
}
function stlpBuildTotalRow(r, firstItem, lastItem, grandTotal, amountWords){
  let s = '<row r="'+r+'" spans="2:63" ht="27.75" customHeight="1">';
  s += stlpSharedCell('B'+r,35,44); /* "جمع کل" */
  stlpColRange('C','F').forEach(c=>{ s+=stlpEmptyCell(c+r,35); });
  s += stlpFormulaCell('G'+r,36,'SUM(BA'+firstItem+':BH'+lastItem+')', grandTotal);
  stlpColRange('H','W').forEach(c=>{ s+=stlpEmptyCell(c+r,36); });
  s += stlpSharedCell('X'+r,37,43); /* "ریال" */
  stlpColRange('Y','AA').forEach(c=>{ s+=stlpEmptyCell(c+r,37); });
  s += stlpEmptyCell('AB'+r,38);
  s += stlpSharedCell('AC'+r,39,45); /* "جمع به حروف" */
  stlpColRange('AD','AI').forEach(c=>{ s+=stlpEmptyCell(c+r,39); });
  s += stlpInlineCell('AJ'+r,43, amountWords);
  stlpColRange('AK','BG').forEach(c=>{ s+=stlpEmptyCell(c+r,19); });
  s += stlpEmptyCell('BH'+r,44);
  s += '</row>';
  return s;
}
function stlpTotalRowMerges(r){
  return ['B'+r+':F'+r,'G'+r+':W'+r,'X'+r+':AA'+r,'AC'+r+':AI'+r,'AJ'+r+':BH'+r];
}
function stlpBuildTermsRow(r, isCash){
  let s = '<row r="'+r+'" spans="2:63" ht="29.25" customHeight="1">';
  s += stlpSharedCell('B'+r,35,40); /* "شرایط و نحوه فروش" */
  stlpColRange('C','H').forEach(c=>{ s+=stlpEmptyCell(c+r,35); });
  s += stlpSharedCell('I'+r,35,8); /* "نقدی" */
  s += stlpEmptyCell('J'+r,35);
  s += isCash ? stlpInlineCell('K'+r,40,'X') : stlpEmptyCell('K'+r,40);
  s += stlpEmptyCell('L'+r,40);
  s += stlpSharedCell('M'+r,35,9); /* "غیر نقدی" */
  s += stlpEmptyCell('N'+r,35);
  s += stlpEmptyCell('O'+r,35);
  s += (!isCash) ? stlpInlineCell('P'+r,41,'X') : stlpEmptyCell('P'+r,41);
  s += stlpEmptyCell('Q'+r,41);
  stlpColRange('R','AA').forEach(c=>{ s+=stlpEmptyCell(c+r,25); });
  s += stlpSharedCell('AB'+r,20,47); /* اطلاعات شبا شرکت */
  stlpColRange('AC','BG').forEach(c=>{ s+=stlpEmptyCell(c+r,45); });
  s += stlpEmptyCell('BH'+r,46);
  s += '</row>';
  return s;
}
function stlpTermsRowMerges(r){
  return ['B'+r+':H'+r,'I'+r+':J'+r,'K'+r+':L'+r,'M'+r+':O'+r,'P'+r+':Q'+r,'R'+r+':AA'+r,'AB'+r+':BH'+r];
}
function stlpBuildSigRows(r1, r2){
  let s = '<row r="'+r1+'" spans="2:63" ht="32.25" customHeight="1">';
  s += stlpSharedCell('B'+r1,42,41); /* "مهر و امضا فروشنده" */
  stlpColRange('C','AA').forEach(c=>{ s+=stlpEmptyCell(c+r1,42); });
  s += stlpSharedCell('AB'+r1,47,42); /* "مهر و امضا خریدار" */
  stlpColRange('AC','BG').forEach(c=>{ s+=stlpEmptyCell(c+r1,48); });
  s += stlpEmptyCell('BH'+r1,49);
  s += '</row>';
  s += '<row r="'+r2+'" spans="2:63" ht="24" customHeight="1">';
  stlpColRange('B','AA').forEach(c=>{ s+=stlpEmptyCell(c+r2,42); });
  s += stlpEmptyCell('AB'+r2,50);
  stlpColRange('AC','BG').forEach(c=>{ s+=stlpEmptyCell(c+r2,51); });
  s += stlpEmptyCell('BH'+r2,52);
  s += '</row>';
  return s;
}
function stlpSigRowMerges(r1,r2){
  return ['AB'+r1+':BH'+r2,'B'+r1+':AA'+r2];
}

/* merge های ثابتِ بخش سربرگ (سطرهای 1 تا 20) که هرگز تغییر نمی‌کنند */
const STLP_HEADER_MERGES = [
  'N1:AT4','A1:M5','AU1:AW2','AX1:BG2','AU3:AW4','AX3:BG4','N5:AT5','AU5:BG5',
  'B7:J7','K7:Y7','Z7:AD7','AE7:AP7','AV7:BG7','Z9:AD9','AE9:AP9','B9:E9','AV9:BG9',
  'AR9:AU9','T9:Y9','F9:J9','R9:S9','K9:Q9','AR11:AU11','AV11:BG11','F11:AP11','B11:E11',
  'N12:AT12','B12:M12','AU12:BG12','B14:J14','K14:Y14','AE14:AP14','AV14:BG14','Z14:AD14',
  'B16:E16','AV16:BG16','AE16:AP16','F16:J16','K16:Q16','R16:S16','AR16:AU16','Z16:AD16','T16:Y16',
  'B18:E18','F18:AP18','AR18:AU18','AV18:BG18','B19:BG19','G20:S20','U20:W20','X20:AB20',
  'AC20:AI20','AO20:AU20','AV20:AZ20','BA20:BH20','AJ20:AN20','D20:F20','B20:C20'
];

/* ---- تابع اصلی: ساخت فایل اکسل ---- */
async function stlpGenerateInvoiceXLSX(opts){
  if(typeof DecompressionStream === 'undefined'){
    alert('مرورگر شما از ساخت فایل اکسل پشتیبانی نمی‌کند. لطفاً از Chrome، Edge یا Firefox جدید استفاده کنید.');
    return null;
  }
  const templateBytes = stlpB64ToBytes(STLP_XLSX_TEMPLATE_B64);
  const files = await stlpUnzip(templateBytes);
  const decoder = new TextDecoder('utf-8');
  const encoder = new TextEncoder();
  let sheetXml = decoder.decode(files['xl/worksheets/sheet1.xml']);

  /* --- فیلدهای سربرگ (شماره، تاریخ، خریدار) --- */
  sheetXml = sheetXml.replace(
    '<c r="AX1" s="18"><v>111111</v></c>',
    '<c r="AX1" s="18" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.code)+'</t></is></c>'
  );
  sheetXml = sheetXml.replace(
    '<c r="AX3" s="14"/>',
    '<c r="AX3" s="14" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.dateFa)+'</t></is></c>'
  );
  sheetXml = sheetXml.replace(
    '<c r="K14" s="8"/>',
    '<c r="K14" s="8" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerName||'')+'</t></is></c>'
  );
  sheetXml = sheetXml.replace(
    '<c r="F18" s="8"/>',
    '<c r="F18" s="8" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerAddress||'')+'</t></is></c>'
  );
  sheetXml = sheetXml.replace(
    '<c r="AV18" s="7"/>',
    '<c r="AV18" s="7" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerPhone||'')+'</t></is></c>'
  );
  /* فیلدهای تکمیلی خریدار (اختیاری) - اگر پر شده باشند در فاکتور درج می‌شوند */
  if(opts.buyerEconCode){
    sheetXml = sheetXml.replace(
      '<c r="AE14" s="7"/>',
      '<c r="AE14" s="7" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerEconCode)+'</t></is></c>'
    );
  }
  if(opts.buyerRegNo){
    sheetXml = sheetXml.replace(
      '<c r="AV14" s="12"/>',
      '<c r="AV14" s="12" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerRegNo)+'</t></is></c>'
    );
  }
  if(opts.buyerProvince){
    sheetXml = sheetXml.replace(
      '<c r="K16" s="8"/>',
      '<c r="K16" s="8" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerProvince)+'</t></is></c>'
    );
  }
  if(opts.buyerCity){
    sheetXml = sheetXml.replace(
      '<c r="T16" s="8"/>',
      '<c r="T16" s="8" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerCity)+'</t></is></c>'
    );
  }
  if(opts.buyerPostalCode){
    sheetXml = sheetXml.replace(
      '<c r="AE16" s="7"/>',
      '<c r="AE16" s="7" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerPostalCode)+'</t></is></c>'
    );
  }
  if(opts.buyerNationalId){
    sheetXml = sheetXml.replace(
      '<c r="AV16" s="7"/>',
      '<c r="AV16" s="7" t="inlineStr"><is><t xml:space="preserve">'+stlpXmlEsc(opts.buyerNationalId)+'</t></is></c>'
    );
  }

  /* --- ردیف‌های کالا (به تعداد اقلام سفارش) + جمع/شرایط/امضا --- */
  const items = opts.items && opts.items.length ? opts.items : [{code:'-',desc:'-',qty:0,unitPrice:0,discPercent:0}];
  const firstItemRow = 21;
  const lastItemRow = 20 + items.length;
  const totalRow = lastItemRow + 1;
  const termsRow = totalRow + 1;
  const sig1 = termsRow + 1;
  const sig2 = sig1 + 1;

  let rowsXml = '';
  let grandTotal = 0;
  let itemMerges = [];
  items.forEach((it, i)=>{
    const r = firstItemRow + i;
    const built = stlpBuildItemRow(r, i+1, it.code||'-', it.desc||'', it.qty||0, it.unitPrice||0, it.discPercent||0, it.unit);
    rowsXml += built.xml;
    grandTotal += built.total;
    itemMerges = itemMerges.concat(stlpItemRowMerges(r));
  });

  const amountWords = stlpNumberToPersianWords(grandTotal);
  rowsXml += stlpBuildTotalRow(totalRow, firstItemRow, lastItemRow, grandTotal, amountWords);
  rowsXml += stlpBuildTermsRow(termsRow, !!opts.isCash);
  rowsXml += stlpBuildSigRows(sig1, sig2);

  const startIdx = sheetXml.indexOf('<row r="21" ');
  const oldTailIdx = sheetXml.indexOf('<row r="31" ', startIdx);
  const endIdx = sheetXml.indexOf('</row>', oldTailIdx) + '</row>'.length;
  sheetXml = sheetXml.substring(0,startIdx) + rowsXml + sheetXml.substring(endIdx);

  /* --- dimension --- */
  sheetXml = sheetXml.replace('<dimension ref="A1:BW32"/>', '<dimension ref="A1:BW'+(sig2+1)+'"/>');

  /* --- mergeCells --- */
  const allMerges = STLP_HEADER_MERGES
    .concat(itemMerges)
    .concat(stlpTotalRowMerges(totalRow))
    .concat(stlpTermsRowMerges(termsRow))
    .concat(stlpSigRowMerges(sig1,sig2));
  const mergeXml = '<mergeCells count="'+allMerges.length+'">' + allMerges.map(m=>'<mergeCell ref="'+m+'"/>').join('') + '</mergeCells>';
  sheetXml = sheetXml.replace(/<mergeCells count="\d+">[\s\S]*?<\/mergeCells>/, mergeXml);

  files['xl/worksheets/sheet1.xml'] = encoder.encode(sheetXml);

  /* --- حذف calcChain (چون بعد از تغییر ردیف‌ها دیگر معتبر نیست) --- */
  delete files['xl/calcChain.xml'];
  let ct = decoder.decode(files['[Content_Types].xml']);
  ct = ct.replace('<Override PartName="/xl/calcChain.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.calcChain+xml"/>', '');
  files['[Content_Types].xml'] = encoder.encode(ct);
  let rels = decoder.decode(files['xl/_rels/workbook.xml.rels']);
  rels = rels.replace('<Relationship Id="rId5" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/calcChain" Target="calcChain.xml"/>', '');
  files['xl/_rels/workbook.xml.rels'] = encoder.encode(rels);

  const zipped = stlpZip(files);
  return new Blob([zipped], {type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
}

function stlpDownloadBlob(blob, filename){
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  setTimeout(()=>{ document.body.removeChild(a); URL.revokeObjectURL(url); }, 1500);
}

/* =====================================================
   ساخت یک فایل اکسل ساده (تک‌شیت) از روی آرایه‌ای از ردیف‌ها
   بدون نیاز به قالب - برای خروجی‌های عمومی (مثل فیش حقوق)
   rows: آرایه‌ای از آرایه‌ها (هر آرایه = یک ردیف از سلول‌ها)
   عدد -> عددی نوشته می‌شود، بقیه -> متن (inlineStr)
   ===================================================== */
function stlpBuildSimpleXlsx(sheetName, rows){

  const encoder = new TextEncoder();

  const colCount =
    rows.reduce(function(max, r){ return Math.max(max, r.length); }, 1);

  const colLetter = function(n){
    let s = '';
    n = n + 1;
    while(n > 0){
      const rem = (n - 1) % 26;
      s = String.fromCharCode(65 + rem) + s;
      n = Math.floor((n - 1) / 26);
    }
    return s;
  };

  let rowsXml = '';

  rows.forEach(function(row, rIdx){

    const r = rIdx + 1;
    let cellsXml = '';

    row.forEach(function(value, cIdx){

      const ref = colLetter(cIdx) + r;

      if (value === null || value === undefined || value === '') {
        return;
      }

      if (typeof value === 'number' && isFinite(value)) {

        cellsXml +=
          '<c r="' + ref + '"><v>' + value + '</v></c>';

      } else {

        cellsXml +=
          '<c r="' + ref + '" t="inlineStr"><is><t xml:space="preserve">' +
          stlpXmlEsc(String(value)) +
          '</t></is></c>';

      }

    });

    rowsXml += '<row r="' + r + '">' + cellsXml + '</row>';

  });

  const colsXml =
    '<cols>' +
    Array.from({length: colCount}).map(function(_, i){
      return '<col min="' + (i+1) + '" max="' + (i+1) + '" width="22" customWidth="1"/>';
    }).join('') +
    '</cols>';

  const sheetXml =
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">' +
    '<sheetViews><sheetView rightToLeft="1" workbookViewId="0"/></sheetViews>' +
    colsXml +
    '<sheetData>' + rowsXml + '</sheetData>' +
    '</worksheet>';

  const contentTypesXml =
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">' +
    '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>' +
    '<Default Extension="xml" ContentType="application/xml"/>' +
    '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>' +
    '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>' +
    '</Types>';

  const rootRelsXml =
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>' +
    '</Relationships>';

  const workbookXml =
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" ' +
    'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">' +
    '<sheets><sheet name="' + stlpXmlEsc(sheetName || 'Sheet1') + '" sheetId="1" r:id="rId1"/></sheets>' +
    '</workbook>';

  const workbookRelsXml =
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>' +
    '</Relationships>';

  const files = {

    '[Content_Types].xml': encoder.encode(contentTypesXml),
    '_rels/.rels': encoder.encode(rootRelsXml),
    'xl/workbook.xml': encoder.encode(workbookXml),
    'xl/_rels/workbook.xml.rels': encoder.encode(workbookRelsXml),
    'xl/worksheets/sheet1.xml': encoder.encode(sheetXml)

  };

  const zipped = stlpZip(files);

  return new Blob(
    [zipped],
    { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }
  );

}

/* ===================== پایان STLP XLSX INVOICE ENGINE ===================== */

async function exportSelectedInvoicesToExcel() {

    // فاکتورهای انتخاب‌شده
    const checks =
        document.querySelectorAll(
            ".invoice-check:checked"
        );

    if (checks.length === 0) {

        alert("حداقل یک فاکتور را انتخاب کنید.");

        return;
    }

    // همه فاکتورها
    const invoices =
        JSON.parse(
            localStorage.getItem("invoices") || "[]"
        );

    // شماره فاکتورهای انتخاب‌شده
    const selectedNumbers =
        Array.from(checks).map(function(check) {
            return String(check.value);
        });

    // پیدا کردن فاکتورها
    const selectedInvoices =
        invoices.filter(function(inv) {

            return selectedNumbers.includes(
                String(inv.invoiceNo)
            );

        });

    if (selectedInvoices.length === 0) {

        alert("فاکتورهای انتخاب‌شده پیدا نشدند.");

        return;
    }

    // فعلاً هر فاکتور را جداگانه خروجی می‌گیریم
    for (const inv of selectedInvoices) {

        const items = [];

        (inv.items || []).forEach(function(it) {

            // فاکتورهای جدید
            if (
                typeof it === "object" &&
                !Array.isArray(it)
            ) {

                items.push({

                    code: it.code || "-",

                    desc:
                        it.name ||
                        it.desc ||
                        "",

                    qty:
                        Number(it.qty || 0),

                    unitPrice:
                        Number(
                            it.price ||
                            it.unitPrice ||
                            0
                        ),

                    discPercent:
                        Number(
                            it.discount ||
                            it.discPercent ||
                            0
                        ),

                    unit:
                        it.unit ||
                        ""

                });

            }

            // فاکتورهای قدیمی
            else if (Array.isArray(it)) {

                items.push({

                    code: it[1] || "-",

                    desc: it[2] || "",

                    qty:
                        Number(it[4] || 0),

                    unitPrice:
                        Number(it[5] || 0),

                    discPercent:
                        Number(it[6] || 0),

                    unit:
                        it[3] || ""

                });

            }

        });


        const customer =
            inv.customerObj || {};


        const opts = {

            code:
                String(inv.invoiceNo),

            dateFa:
                inv.date || "",

            buyerName:
                customer.name ||
                inv.customer ||
                "",

            buyerAddress:
                customer.address ||
                customer.addr ||
                "",

            buyerPhone:
                customer.phone ||
                "",

            buyerEconCode:
                customer.econCode ||
                customer.econ ||
                "",

            buyerRegNo:
                customer.regNo ||
                customer.reg ||
                "",

            buyerProvince:
                customer.province ||
                "",

            buyerCity:
                customer.city ||
                "",

            buyerPostalCode:
                customer.postalCode ||
                "",

            buyerNationalId:
                customer.nationalId ||
                customer.national ||
                "",

            isCash:
                inv.purchaseType !== "credit",

            items:
                items

        };


        try {

            const blob =
                await stlpGenerateInvoiceXLSX(opts);

            if (blob) {

                stlpDownloadBlob(
                    blob,
                    "فاکتور-" +
                    inv.invoiceNo +
                    ".xlsx"
                );

            }

        } catch (error) {

            console.error(error);

            alert(
                "خطا در خروجی اکسل فاکتور " +
                inv.invoiceNo +
                ":\n" +
                error.message
            );

            return;
        }

    }

    alert(
        selectedInvoices.length +
        " فاکتور با موفقیت برای خروجی اکسل آماده شد."
    );
}

