// ============================================
// هشدار موجودی و تاریخ انقضا
// ============================================

function checkInventoryWarnings() {

    const box =
        document.getElementById("inventoryWarnings");

    if (!box) return;

    const warnings = [];

    const today = new Date();

    const warningDays = 30;


    inventoryItems.forEach(function(item) {

        const stock =
            Number(item.stock || 0);

        const reserved =
            Number(item.reserved || 0);

        // موجودیِ واقعاً قابل‌فروش (بخشی که رزروِ فاکتورهای در
        // انتظارِ تأیید نیست) — هشدارها باید بر همین مبنا باشند،
        // نه روی کل موجودیِ فیزیکی، وگرنه کالایی که کاملاً رزرو
        // شده هیچ هشداری نشان نمی‌دهد در حالی که چیزی برای فروش
        // ندارد.
        const available =
            stock - reserved;


        // =========================
        // موجودی صفر
        // =========================

        if (available <= 0) {

            warnings.push(
                `<div class="inventory-warning-item warning-stock">
                    🔴 موجودی قابل‌فروشِ «${escapeHtml(item.name)}» صفر است.
                    ${
                        reserved > 0
                            ? "(کل موجودی رزروِ فاکتورهای در انتظار تأیید است)"
                            : ""
                    }
                </div>`
            );

        }


        // =========================
        // موجودی کم
        // =========================

        else if (available <= 5) {

            warnings.push(
                `<div class="inventory-warning-item warning-stock">
                    🟠 موجودی قابل‌فروشِ «${escapeHtml(item.name)}» کم است.
                    موجودی قابل‌فروش: ${available.toLocaleString("fa-IR")}
                    ${
                        reserved > 0
                            ? "(از موجودیِ کل " + stock.toLocaleString("fa-IR") + "، " + reserved.toLocaleString("fa-IR") + " رزرو شده)"
                            : ""
                    }
                </div>`
            );

        }


        // =========================
        // تاریخ انقضا
        // =========================

        if (item.exp) {

            const expiryDate =
                new Date(item.exp);


            if (!isNaN(expiryDate.getTime())) {

                const diff =
                    expiryDate - today;

                const daysLeft =
                    Math.ceil(
                        diff / (1000 * 60 * 60 * 24)
                    );


                // منقضی شده
                if (daysLeft < 0) {

                    warnings.push(
                        `<div class="inventory-warning-item warning-expiry">
                            ❌ «${escapeHtml(item.name)}» منقضی شده است.
                        </div>`
                    );

                }


                // تا 30 روز آینده
                else if (daysLeft <= warningDays) {

                    warnings.push(
                        `<div class="inventory-warning-item warning-expiry">
                            ⚠️ تاریخ انقضای «${escapeHtml(item.name)}»
                            ${daysLeft} روز دیگر است.
                        </div>`
                    );

                }

            }

        }

    });


    // =========================
    // نمایش / مخفی کردن
    // =========================

    if (warnings.length === 0) {

        box.style.display = "none";
        box.innerHTML = "";

        return;
    }


    box.style.display = "block";

    box.innerHTML = `
        <div class="inventory-warning-title">
            ⚠️ هشدارهای انبار
        </div>

        ${warnings.join("")}
    `;
}
