function saveInventory() {

    localStorage.setItem(
        "stlp_inventory",
        JSON.stringify(inventoryItems)
    );

}
function updateInventoryExpiryStatus() {

    if (
        !inventoryItems ||
        inventoryItems.length === 0
    ) {

        return;

    }


    let changed = false;


    inventoryItems.forEach(function(item) {

        const expiry =
            getInventoryExpiryStatus(item.exp);


        const oldExpired =
            item.expired === true;


        const newExpired =
            expiry.expired === true;


        if (
            oldExpired !== newExpired
        ) {

            item.expired =
                newExpired;

            changed = true;

        }


        // وضعیت محاسباتی
        item.expiryStatus =
            expiry.status;

    });


    if (changed) {

        saveInventory();

    }

}

// =====================================================
// نمایش هشدارهای انبار
// =====================================================
// =====================================================
// بررسی تاریخ انقضای کالا
// =====================================================

// =====================================================
// بررسی تاریخ انقضای کالا
// =====================================================

function getInventoryExpiryStatus(expDate) {

    if (!expDate) {

        return {
            expired: false,
            warning: false,
            days: null,
            label: ""
        };

    }


    // تاریخ امروز
    const today = new Date();

    today.setHours(0, 0, 0, 0);


    // تبدیل YYYY-MM-DD به تاریخ محلی
    const parts = String(expDate).split("-");

    if (parts.length !== 3) {

        return {
            expired: false,
            warning: false,
            days: null,
            label: ""
        };

    }


    const expiryDate = new Date(
        Number(parts[0]),
        Number(parts[1]) - 1,
        Number(parts[2])
    );

    expiryDate.setHours(0, 0, 0, 0);


    if (isNaN(expiryDate.getTime())) {

        return {
            expired: false,
            warning: false,
            days: null,
            label: ""
        };

    }


    const diffTime =
        expiryDate.getTime() -
        today.getTime();


    const diffDays =
        Math.round(
            diffTime /
            (1000 * 60 * 60 * 24)
        );


    // ================================================
    // منقضی شده
    // ================================================

    if (diffDays < 0) {

        return {

            expired: true,

            warning: false,

            days: diffDays,

            label:
                "⛔ منقضی شده"

        };

    }


    // ================================================
    // امروز
    // ================================================

    if (diffDays === 0) {

        return {

            expired: false,

            warning: true,

            days: 0,

            label:
                "🔴 امروز منقضی می‌شود"

        };

    }


    // ================================================
    // 30 روز مانده یا کمتر
    // ================================================

    if (diffDays <= 30) {

        return {

            expired: false,

            warning: true,

            days: diffDays,

            label:
                "🟠 " +
                diffDays +
                " روز تا انقضا"

        };

    }


    return {

        expired: false,

        warning: false,

        days: diffDays,

        label:
            diffDays +
            " روز تا انقضا"

    };

}

function renderInventoryWarnings() {

    const box =
        document.getElementById("inventoryWarnings");


    if (!box) {
        return;
    }


    const warnings = [];


    inventoryItems.forEach(function(item) {

        const expiry =
            getInventoryExpiryStatus(item.exp);


        // ==========================================
        // منقضی
        // ==========================================

        if (expiry.expired) {

            warnings.push(`
                <div class="inventory-warning-item">

                    🔴

                    <strong>
                        ${escapeInventoryText(item.name)}
                    </strong>

                    -

                    کد:
                    ${escapeInventoryText(item.code)}

                    <span class="warning-expiry">

                        ⛔ تاریخ مصرف گذشته

                    </span>

                </div>
            `);

        }


        // ==========================================
        // نزدیک انقضا
        // ==========================================

        else if (expiry.warning) {

            warnings.push(`
                <div class="inventory-warning-item">

                    🟠

                    <strong>
                        ${escapeInventoryText(item.name)}
                    </strong>

                    -

                    کد:
                    ${escapeInventoryText(item.code)}

                    <span class="warning-expiry">

                        ${expiry.label}

                    </span>

                </div>
            `);

        }


        // ==========================================
        // موجودی کم
        // ==========================================

        const stock =
            Number(item.stock || 0);

        const minStock =
            Number(item.minStock || 0);


        if (
            stock > 0 &&
            minStock > 0 &&
            stock <= minStock
        ) {

            warnings.push(`
                <div class="inventory-warning-item">

                    ⚠️

                    <strong>
                        ${escapeInventoryText(item.name)}
                    </strong>

                    -

                    کد:
                    ${escapeInventoryText(item.code)}

                    <span class="warning-stock">

                        موجودی کم: ${stock}

                    </span>

                </div>
            `);

        }


        // ==========================================
        // موجودی صفر
        // ==========================================

        if (stock === 0) {

            warnings.push(`
                <div class="inventory-warning-item">

                    ❌

                    <strong>
                        ${escapeInventoryText(item.name)}
                    </strong>

                    -

                    کد:
                    ${escapeInventoryText(item.code)}

                    <span class="warning-stock">

                        موجودی صفر

                    </span>

                </div>
            `);

        }

    });


    // ==========================================
    // نمایش
    // ==========================================

    if (warnings.length === 0) {

        box.style.display = "none";

        box.innerHTML = "";

        return;

    }


    box.style.display = "block";


    box.innerHTML = `

        <div class="inventory-warning-title">

            ⚠️ هشدارهای انبار

        </div>

        ${warnings.join("")}

    `;

}
// =====================================================
// جلوگیری از ورود HTML به هشدارهای انبار
// =====================================================

function escapeInventoryText(value) {

    if (
        value === null ||
        value === undefined
    ) {

        return "";

    }


    return String(value)

        .replace(/&/g, "&amp;")

        .replace(/</g, "&lt;")

        .replace(/>/g, "&gt;")

        .replace(/"/g, "&quot;")

        .replace(/'/g, "&#039;");

}

