// =====================================================
// تبدیل اطلاعات قدیمی به ساختار جدید
// =====================================================

function normalizeInventoryItem(item) {

    // کالاهایی که قبل از ساختنِ «تبدیل واحد» ثبت شده‌اند (هیچ‌کدام از دو
    // فیلدِ نسبت را ندارند): طبقِ تصمیمِ مالک، یک‌بار و برای همیشه
    // «بسته» با هر کارتن = ۱۲ بسته و هر بسته = ۱۰۰ عدد می‌شوند. کالای
    // ساخته‌شده از فرمِ انبار یا از خرید، همیشه این دو فیلد را صریحاً دارد
    // و دست نمی‌خورد.
    const neverConfiguredRatio =
        item.packagesPerCarton === undefined &&
        item.piecesPerPackage === undefined;

    return {

        code: item.code || "",

        barcode: item.barcode || "",

        name: item.name || "",

        category: item.category || "",

        brand: item.brand || "",

        manufacturer:
            item.manufacturer ||
            item.mfg ||
            "",

        unit: neverConfiguredRatio ? "بسته" : (item.unit || "عدد"),

        packagesPerCarton:
            neverConfiguredRatio ? 12 : Number(item.packagesPerCarton || 1),

        piecesPerPackage:
            neverConfiguredRatio ? 100 : Number(item.piecesPerPackage || 1),

        purchasePrice:
            Number(item.purchasePrice || 0),

        price:
            Number(item.price || 0),

        mfg:
            item.mfg || "",

        batch:
            item.batch || "",

        exp:
            item.exp || "",

        stock:
            Number(item.stock || 0),

        reserved:
            Number(item.reserved || 0),

        minStock:
            Number(item.minStock || 5),

        location:
            item.location || "",

        supplier:
            item.supplier || "",

        status:
            item.status || "active",

        notes:
            item.notes || "",

        image:
            item.image || ""

    };

}


// =====================================================
// سازگاری اطلاعات قبلی
// =====================================================

inventoryItems =
    inventoryItems.map(normalizeInventoryItem);

saveInventory();


