function stlpInventoryImageChange() {

    const input = document.getElementById("iimage");
    const preview = document.getElementById("iimagePreview");
    const file = input.files[0];

    if (!file) return;

    if (file.size > 2000000 || !["image/png", "image/jpeg", "image/webp"].includes(file.type)) {

        alert("عکس باید PNG، JPEG یا WebP و کمتر از ۲ مگابایت باشد.");
        input.value = "";
        return;

    }

    const reader = new FileReader();

    reader.onload = function() {
        preview.src = reader.result;
        preview.style.display = "inline-block";
    };

    reader.readAsDataURL(file);

}


