function printInventory() {

    // چاپ فقط چیزی را که روی صفحه دیده می‌شود چاپ می‌کند؛ با تب‌بندیِ
    // جدید ممکن بود «چاپ» از تبِ خلاصه/فرم زده شود و لیستِ کالاها چاپ نشود
    if (typeof stlpInventorySwitchTab === "function") stlpInventorySwitchTab("main");
    if (typeof stlpInventoryMainSubTab === "function") stlpInventoryMainSubTab("list");

    window.print();

}


