function exportInventoryExcel() {

    if (
        !inventoryItems ||
        inventoryItems.length === 0
    ) {

        alert("⚠️ کالایی برای خروجی گرفتن وجود ندارد.");

        return;
    }


    // =================================================
    // تبدیل مقدار به HTML امن
    // =================================================

    function escapeHTML(value) {

        if (
            value === null ||
            value === undefined
        ) {
            return "";
        }

        return String(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    // =================================================
    // فرمت عدد
    // =================================================

    function numberFormat(value) {

        const number = Number(value || 0);

        if (isNaN(number)) {
            return "0";
        }

        return number.toLocaleString("en-US");

    }


    // =================================================
    // HTML فایل Excel
    // =================================================

    let html = `
<!DOCTYPE html>

<html
    xmlns:o="urn:schemas-microsoft-com:office:office"
    xmlns:x="urn:schemas-microsoft-com:office:excel"
    xmlns="http://www.w3.org/TR/REC-html40"
>

<head>

<meta charset="UTF-8">

<meta http-equiv="Content-Type"
      content="text/html; charset=UTF-8">

<style>

    body {

        font-family: Tahoma, Arial, sans-serif;

        direction: rtl;

        background: #ffffff;

    }


    table {

        border-collapse: collapse;

        width: 100%;

        direction: rtl;

    }


    th {

        background: #7C3AED;

        color: #FFFFFF;

        border: 1px solid #5B21B6;

        padding: 10px 12px;

        font-family: Tahoma, Arial, sans-serif;

        font-size: 11pt;

        font-weight: bold;

        text-align: center;

        vertical-align: middle;

        white-space: nowrap;

    }


    td {

        border: 1px solid #D9D9D9;

        padding: 8px 10px;

        font-family: Tahoma, Arial, sans-serif;

        font-size: 10pt;

        text-align: center;

        vertical-align: middle;

    }


    tr:nth-child(even) td {

        background: #F8F5FF;

    }


    .number {

        direction: ltr;

        text-align: center;

        mso-number-format: "#,##0";

    }


    .text {

        mso-number-format: "\\@";

    }


</style>

</head>


<body>


<table>


<thead>

<tr>

    <th>کد کالا</th>

    <th>بارکد</th>

    <th>شرح کالا</th>

    <th>دسته‌بندی</th>

    <th>برند</th>

    <th>تولیدکننده</th>

    <th>واحد</th>

    <th>قیمت خرید</th>

    <th>قیمت فروش</th>

    <th>تاریخ تولید</th>

    <th>Batch / Lot</th>

    <th>تاریخ انقضا</th>

    <th>موجودی</th>

    <th>حداقل موجودی</th>

    <th>محل نگهداری</th>

    <th>تأمین‌کننده</th>

    <th>وضعیت</th>

    <th>توضیحات</th>

</tr>

</thead>


<tbody>
`;


    // =================================================
    // کالاها
    // =================================================

    inventoryItems.forEach(function(item) {

        const status =
            item.status === "inactive"
                ? "غیرفعال"
                : "فعال";


        html += `

<tr>

    <td class="text">
        ${escapeHTML(item.code || "")}
    </td>


    <td class="text">
        ${escapeHTML(item.barcode || "")}
    </td>


    <td>
        ${escapeHTML(item.name || "")}
    </td>


    <td>
        ${escapeHTML(item.category || "")}
    </td>


    <td>
        ${escapeHTML(item.brand || "")}
    </td>


    <td>
        ${escapeHTML(item.manufacturer || "")}
    </td>


    <td>
        ${escapeHTML(item.unit || "")}
    </td>


    <td class="number">
        ${numberFormat(item.purchasePrice)}
    </td>


    <td class="number">
        ${numberFormat(item.price)}
    </td>


    <td class="text">
        ${escapeHTML(item.mfg || "")}
    </td>


    <td class="text">
        ${escapeHTML(item.batch || "")}
    </td>


    <td class="text">
        ${escapeHTML(item.exp || "")}
    </td>


    <td class="number">
        ${numberFormat(item.stock)}
    </td>


    <td class="number">
        ${numberFormat(item.minStock)}
    </td>


    <td>
        ${escapeHTML(item.location || "")}
    </td>


    <td>
        ${escapeHTML(item.supplier || "")}
    </td>


    <td>
        ${escapeHTML(status)}
    </td>


    <td>
        ${escapeHTML(item.notes || "")}
    </td>

</tr>

`;

    });


    html += `

</tbody>

</table>

</body>

</html>
`;


    // =================================================
    // ساخت فایل
    // =================================================

    const blob = new Blob(
        [
            "\uFEFF",
            html
        ],
        {
            type:
                "application/vnd.ms-excel;charset=utf-8"
        }
    );


    // =================================================
    // دانلود
    // =================================================

    const url =
        URL.createObjectURL(blob);


    const link =
        document.createElement("a");


    link.href = url;


    link.download =
        "STLP-گزارش-انبار.xls";


    document.body.appendChild(link);


    link.click();


    document.body.removeChild(link);


    setTimeout(function() {

        URL.revokeObjectURL(url);

    }, 1000);


    alert(
        "✅ فایل Excel با موفقیت ساخته شد."
    );

}


