// =====================================================
// خروجی اکسل حرفه‌ای — برای همه‌ی بخش‌های حسابداری
// (سرتیتر شرکت، تاریخ گزارش، فرمت عددی سه‌رقمی، عرض ستون مناسب،
//  راست‌به‌چپ، چند شیت در گزارش‌های ترکیبی)
// =====================================================

function stlpAcctCheckExcelLib() {

    if (typeof XLSX === "undefined") {
        alert("❌ کتابخانه‌ی خروجی اکسل (SheetJS) لود نشده — به اینترنت وصل باشید.");
        return false;
    }

    return true;

}


function stlpAcctNewWorkbook() {

    const wb = XLSX.utils.book_new();

    // نمای راست‌به‌چپ برای کل فایل
    wb.Workbook = { Views: [{ RTL: true }] };

    return wb;

}


// یک شیت «حرفه‌ای» می‌سازد: ردیف سرتیتر شرکت (ادغام‌شده)،
// ردیف زیرعنوان گزارش + تاریخ، یک ردیف خالی، هدر جدول، بعد داده‌ها.
// moneyCols: اندیس (0-based) ستون‌هایی که باید فرمت پول بگیرند.
function stlpAcctBuildSheet(reportTitle, headers, rows, moneyCols, colWidths) {

    const companyRow = ["صبا تجهیز لاله پارسه — گزارش حسابداری"];
    const titleRow = [reportTitle];
    const dateRow = ["تاریخ تهیه: " + new Date().toLocaleString("fa-IR")];
    const blankRow = [];

    const aoa = [companyRow, titleRow, dateRow, blankRow, headers].concat(rows);

    const ws = XLSX.utils.aoa_to_sheet(aoa);

    const colCount = headers.length;

    // ادغام سه ردیف اول در کل عرض جدول
    ws["!merges"] = [
        { s: { r: 0, c: 0 }, e: { r: 0, c: colCount - 1 } },
        { s: { r: 1, c: 0 }, e: { r: 1, c: colCount - 1 } },
        { s: { r: 2, c: 0 }, e: { r: 2, c: colCount - 1 } }
    ];

    // عرض ستون‌ها
    ws["!cols"] = (colWidths || headers.map(function() { return 18; }))
        .map(function(w) { return { wch: w }; });

    // فرمت عددی برای ستون‌های پولی (سه‌رقمی با جداکننده)
    const dataStartRow = 5; // بعد از ۵ ردیف بالای صفحه (0-indexed)

    rows.forEach(function(row, rIdx) {

        (moneyCols || []).forEach(function(cIdx) {

            const cellRef = XLSX.utils.encode_cell({ r: dataStartRow + rIdx, c: cIdx });
            const cell = ws[cellRef];

            if (cell && typeof cell.v === "number") {
                cell.z = "#,##0";
            }

        });

    });

    // فریز کردن ردیف هدر جدول برای اسکرول راحت‌تر
    ws["!freeze"] = { xSplit: 0, ySplit: dataStartRow };

    return ws;

}


function stlpAcctDownload(wb, filenamePrefix) {

    const dateStamp = new Date().toISOString().slice(0, 10);
    XLSX.writeFile(wb, filenamePrefix + "-" + dateStamp + ".xlsx");

}


// ---------------- خروجی: داشبورد ----------------

function stlpAcctExportDashboardExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    const revAcc = stlpFindAccountByCode("4100");
    const rev = revAcc ? stlpAccountBalance(revAcc.id) : { debit: 0, credit: 0 };
    const totalRevenue = rev.credit - rev.debit;

    const otherRevAcc = stlpFindAccountByCode("4200");
    const otherRev = otherRevAcc ? stlpAccountBalance(otherRevAcc.id) : { debit: 0, credit: 0 };
    const totalOtherRevenue = otherRev.credit - otherRev.debit;

    const expAccounts = stlpAccounts.filter(function(a) { return a.type === "expense"; });
    const totalExpense = expAccounts.reduce(function(sum, a) {
        const b = stlpAccountBalance(a.id);
        return sum + (b.debit - b.credit);
    }, 0);

    // مانده‌ی حساب سرفصل «1200 - چک‌های دریافتنی» همیشه صفر است، چون
    // stlpBuildTreasuryJournalLines چک‌ها را تا وصول‌نشدن اصلاً به دفتر
    // کل پست نمی‌کند (طبق طراحی) و بعد از وصول هم مستقیم به حساب بانک/
    // صندوق پست می‌کند، نه به این سرفصل — یعنی این حساب هیچ‌وقت سندی
    // نمی‌گیرد. پس مانده‌ی چک‌های دریافتنیِ درجریان را مستقیم از روی
    // خودِ تراکنش‌های خزانه (چک‌های دریافتی‌ای که هنوز وصول/برگشت
    // نخورده‌اند) حساب می‌کنیم، نه از مانده‌ی این حساب.
    const checksOutstanding = stlpTreasury
        .filter(function(item) {
            return (
                item.method === "cheque" &&
                item.checkDirection === "received" &&
                (item.checkStatus === "pending" || item.checkStatus === "approved")
            );
        })
        .reduce(function(sum, item) { return sum + Number(item.amount || 0); }, 0);

    const cashAccounts = stlpAccounts.filter(function(a) { return a.treasuryAccountId; });
    const totalCash = cashAccounts.reduce(function(sum, a) {
        const b = stlpAccountBalance(a.id);
        return sum + (b.debit - b.credit);
    }, 0);

    const rows = [
        ["درآمد فروش", totalRevenue],
        ["بهای تمام‌شده‌ی کالای فروش‌رفته (COGS)", stlpComputeCOGS()],
        ["سود ناخالص", totalRevenue - stlpComputeCOGS()],
        ["سایر درآمدها", totalOtherRevenue],
        ["جمع هزینه‌های نقدی", totalExpense],
        ["سود (زیان) خالص نقدی", totalRevenue + totalOtherRevenue - totalExpense],
        ["موجودی نقد و بانک (طبق دفتر)", totalCash],
        ["مانده چک‌های دریافتنی", checksOutstanding],
        ["مانده مشتریان (طلب از مشتری)", stlpComputeCustomerBalances().reduce(function(s, c) { return s + c.total; }, 0)],
        ["مانده تأمین‌کنندگان (بدهی به تأمین‌کننده)", stlpComputeSupplierBalances().reduce(function(s, c) { return s + c.total; }, 0)]
    ];

    const ws = stlpAcctBuildSheet(
        "داشبورد حسابداری",
        ["شاخص", "مبلغ (ریال)"],
        rows,
        [1],
        [34, 22]
    );

    const wb = stlpAcctNewWorkbook();
    XLSX.utils.book_append_sheet(wb, ws, "داشبورد");
    stlpAcctDownload(wb, "گزارش-داشبورد-حسابداری");

}


// ---------------- خروجی: سرفصل حساب‌ها ----------------

function stlpAcctExportAccountsExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    const sorted = stlpAccounts.slice().sort(function(a, b) {
        return String(a.code).localeCompare(String(b.code));
    });

    const rows = sorted.map(function(a) {

        const parent = stlpFindAccountById(a.parentId);
        const bal = stlpAccountBalance(a.id);
        const side = stlpAccountNormalSide(a.type);
        const balance = side === "debit" ? (bal.debit - bal.credit) : (bal.credit - bal.debit);

        return [
            a.code,
            a.name,
            stlpAccountTypeLabel(a.type),
            parent ? parent.name : "—",
            balance,
            a.system ? "پیش‌فرض" : "دستی"
        ];

    });

    const ws = stlpAcctBuildSheet(
        "سرفصل حساب‌ها",
        ["کد", "نام حساب", "نوع", "زیرمجموعه‌ی", "مانده (ریال)", "منشأ"],
        rows,
        [4],
        [10, 28, 16, 24, 18, 12]
    );

    const wb = stlpAcctNewWorkbook();
    XLSX.utils.book_append_sheet(wb, ws, "سرفصل حساب‌ها");
    stlpAcctDownload(wb, "گزارش-سرفصل-حسابها");

}


// ---------------- خروجی: اسناد حسابداری ----------------

function stlpAcctExportJournalExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    const sortedEntries = stlpJournalEntries.slice().sort(function(a, b) {
        return (b.dateTs || 0) - (a.dateTs || 0);
    });

    const rows = [];

    sortedEntries.forEach(function(e) {

        const src = e.sourceType === "treasury" ? "خودکار (خزانه)" : (e.sourceType === "manual" ? "دستی" : e.sourceType);

        e.lines.forEach(function(l, lineIdx) {

            const acc = stlpFindAccountById(l.accountId);

            rows.push([
                lineIdx === 0 ? e.number : "",
                lineIdx === 0 ? e.date : "",
                lineIdx === 0 ? e.description : "",
                acc ? (acc.code + " — " + acc.name) : "—",
                l.debit || 0,
                l.credit || 0,
                lineIdx === 0 ? src : ""
            ]);

        });

    });

    const ws = stlpAcctBuildSheet(
        "اسناد حسابداری",
        ["شماره سند", "تاریخ", "شرح سند", "حساب", "بدهکار (ریال)", "بستانکار (ریال)", "منبع"],
        rows,
        [4, 5],
        [12, 14, 30, 28, 16, 16, 16]
    );

    const wb = stlpAcctNewWorkbook();
    XLSX.utils.book_append_sheet(wb, ws, "اسناد حسابداری");
    stlpAcctDownload(wb, "گزارش-اسناد-حسابداری");

}


// ---------------- خروجی: دفتر کل ----------------

function stlpAcctExportLedgerExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    if (!stlpLedgerSelectedAccountId) {
        alert("لطفاً اول از تب دفتر کل یک حساب انتخاب کنید.");
        return;
    }

    const acc = stlpFindAccountById(stlpLedgerSelectedAccountId);
    if (!acc) return;

    const entries = [];

    stlpJournalEntries
        .slice()
        .sort(function(a, b) { return (a.dateTs || 0) - (b.dateTs || 0); })
        .forEach(function(e) {
            e.lines.forEach(function(l) {
                if (l.accountId === stlpLedgerSelectedAccountId) {
                    entries.push({
                        number: e.number,
                        date: e.date,
                        description: e.description,
                        debit: l.debit || 0,
                        credit: l.credit || 0
                    });
                }
            });
        });

    let running = 0;
    const side = stlpAccountNormalSide(acc.type);

    const rows = entries.map(function(r) {

        running += side === "debit" ? (r.debit - r.credit) : (r.credit - r.debit);

        return [r.number, r.date, r.description, r.debit, r.credit, running];

    });

    const ws = stlpAcctBuildSheet(
        "دفتر کل — " + acc.code + " " + acc.name,
        ["شماره سند", "تاریخ", "شرح", "بدهکار (ریال)", "بستانکار (ریال)", "مانده (ریال)"],
        rows,
        [3, 4, 5],
        [12, 14, 32, 16, 16, 16]
    );

    const wb = stlpAcctNewWorkbook();
    XLSX.utils.book_append_sheet(wb, ws, "دفتر کل");
    stlpAcctDownload(wb, "دفتر-کل-" + acc.code);

}


// ---------------- خروجی: تراز آزمایشی ----------------

function stlpAcctExportTrialBalanceExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    const rows = stlpAccounts
        .map(function(a) {
            const bal = stlpAccountBalance(a.id);
            return { account: a, debit: bal.debit, credit: bal.credit };
        })
        .filter(function(r) { return r.debit || r.credit; })
        .sort(function(a, b) { return String(a.account.code).localeCompare(String(b.account.code)); });

    const totalDebit = rows.reduce(function(a, r) { return a + r.debit; }, 0);
    const totalCredit = rows.reduce(function(a, r) { return a + r.credit; }, 0);

    const dataRows = rows.map(function(r) {
        return [r.account.code, r.account.name, r.debit, r.credit];
    });

    dataRows.push(["", "جمع کل", totalDebit, totalCredit]);

    const ws = stlpAcctBuildSheet(
        "تراز آزمایشی",
        ["کد", "نام حساب", "بدهکار (ریال)", "بستانکار (ریال)"],
        dataRows,
        [2, 3],
        [10, 30, 18, 18]
    );

    const wb = stlpAcctNewWorkbook();
    XLSX.utils.book_append_sheet(wb, ws, "تراز آزمایشی");
    stlpAcctDownload(wb, "تراز-آزمایشی");

}


// ---------------- خروجی: ترازنامه ----------------

function stlpAcctExportBalanceSheetExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    const byType = { asset: [], liability: [], equity: [] };

    stlpAccounts.forEach(function(a) {
        if (!byType[a.type]) return;
        const b = stlpAccountBalance(a.id);
        const bal = stlpAccountNormalSide(a.type) === "debit" ? (b.debit - b.credit) : (b.credit - b.debit);
        if (bal) byType[a.type].push({ name: a.name, bal: bal });
    });

    const revAccounts = stlpAccounts.filter(function(a) { return a.type === "revenue"; });
    const expAccounts = stlpAccounts.filter(function(a) { return a.type === "expense"; });

    const totalRevenue = revAccounts.reduce(function(sum, a) {
        const b = stlpAccountBalance(a.id);
        return sum + (b.credit - b.debit);
    }, 0);

    const totalExpense = expAccounts.reduce(function(sum, a) {
        const b = stlpAccountBalance(a.id);
        return sum + (b.debit - b.credit);
    }, 0);

    const netIncome = totalRevenue - totalExpense;

    const sumType = function(t) { return byType[t].reduce(function(a, x) { return a + x.bal; }, 0); };

    const totalAssets = sumType("asset");
    const totalLiab = sumType("liability");
    const totalEquity = sumType("equity") + netIncome;

    const rows = [];

    rows.push(["دارایی‌ها", "", ""]);
    byType.asset.forEach(function(x) { rows.push(["", x.name, x.bal]); });
    rows.push(["", "جمع دارایی‌ها", totalAssets]);
    rows.push(["", "", ""]);

    rows.push(["بدهی‌ها", "", ""]);
    byType.liability.forEach(function(x) { rows.push(["", x.name, x.bal]); });
    rows.push(["", "جمع بدهی‌ها", totalLiab]);
    rows.push(["", "", ""]);

    rows.push(["حقوق صاحبان سهام", "", ""]);
    byType.equity.forEach(function(x) { rows.push(["", x.name, x.bal]); });
    rows.push(["", "سود (زیان) دوره جاری", netIncome]);
    rows.push(["", "جمع حقوق صاحبان سهام", totalEquity]);
    rows.push(["", "", ""]);
    rows.push(["", "جمع بدهی‌ها + حقوق صاحبان سهام", totalLiab + totalEquity]);

    const ws = stlpAcctBuildSheet(
        "ترازنامه",
        ["گروه", "شرح", "مبلغ (ریال)"],
        rows,
        [2],
        [24, 32, 20]
    );

    const wb = stlpAcctNewWorkbook();
    XLSX.utils.book_append_sheet(wb, ws, "ترازنامه");
    stlpAcctDownload(wb, "ترازنامه");

}


// ---------------- خروجی: سود و زیان ----------------

function stlpAcctExportIncomeStatementExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    const revAccounts = stlpAccounts.filter(function(a) { return a.type === "revenue"; });
    const expAccounts = stlpAccounts.filter(function(a) { return a.type === "expense"; });

    const revRows = revAccounts
        .map(function(a) {
            const b = stlpAccountBalance(a.id);
            return { name: a.name, amount: b.credit - b.debit };
        })
        .filter(function(r) { return r.amount; });

    const expRows = expAccounts
        .map(function(a) {
            const b = stlpAccountBalance(a.id);
            return { name: a.name, amount: b.debit - b.credit };
        })
        .filter(function(r) { return r.amount; });

    const totalRev = revRows.reduce(function(a, r) { return a + r.amount; }, 0);
    const totalExp = expRows.reduce(function(a, r) { return a + r.amount; }, 0);
    const cogs = stlpComputeCOGS();
    const grossProfit = totalRev - cogs;

    const rows = [];

    rows.push(["درآمدها", ""]);
    revRows.forEach(function(r) { rows.push([r.name, r.amount]); });
    rows.push(["جمع درآمد", totalRev]);
    rows.push(["", ""]);

    rows.push(["بهای تمام‌شده‌ی کالای فروش‌رفته (COGS، تقریبی)", cogs]);
    rows.push(["سود ناخالص", grossProfit]);
    rows.push(["", ""]);

    rows.push(["هزینه‌ها (عملیاتی/نقدی)", ""]);
    expRows.forEach(function(r) { rows.push([r.name, r.amount]); });
    rows.push(["جمع هزینه", totalExp]);
    rows.push(["", ""]);

    rows.push(["سود (زیان) خالص نقدی دوره (بدون COGS)", totalRev - totalExp]);
    rows.push(["سود (زیان) خالص واقعی‌تر (سود ناخالص − هزینه‌های نقدی)", grossProfit - totalExp]);

    const ws = stlpAcctBuildSheet(
        "صورت سود و زیان",
        ["شرح", "مبلغ (ریال)"],
        rows,
        [1],
        [40, 22]
    );

    const wb = stlpAcctNewWorkbook();
    XLSX.utils.book_append_sheet(wb, ws, "سود و زیان");
    stlpAcctDownload(wb, "صورت-سود-و-زیان");

}


