// ---------------- خروجی: کل مجموعه یک‌جا (همه‌ی ۹ بخش، یک فایل چندشیتی) ----------------

function stlpAcctExportAllExcel() {

    if (!stlpAcctCheckExcelLib()) return;

    // هر export تک‌شیتی جدا فایل می‌سازد؛ اینجا همان worksheetها را
    // در یک workbook واحد جمع می‌کنیم تا یک فایل چندشیتی کامل بگیری.

    const wb = stlpAcctNewWorkbook();


    // داشبورد
    (function() {
        const revAcc = stlpFindAccountByCode("4100");
        const rev = revAcc ? stlpAccountBalance(revAcc.id) : { debit: 0, credit: 0 };
        const totalRevenue = rev.credit - rev.debit;
        const otherRevAcc = stlpFindAccountByCode("4200");
        const otherRev = otherRevAcc ? stlpAccountBalance(otherRevAcc.id) : { debit: 0, credit: 0 };
        const totalOtherRevenue = otherRev.credit - otherRev.debit;
        const expAccounts = stlpAccounts.filter(function(a) { return a.type === "expense"; });
        const totalExpense = expAccounts.reduce(function(sum, a) { const b = stlpAccountBalance(a.id); return sum + (b.debit - b.credit); }, 0);
        const cashAccounts = stlpAccounts.filter(function(a) { return a.treasuryAccountId; });
        const totalCash = cashAccounts.reduce(function(sum, a) { const b = stlpAccountBalance(a.id); return sum + (b.debit - b.credit); }, 0);

        const rows = [
            ["درآمد فروش", totalRevenue],
            ["سایر درآمدها", totalOtherRevenue],
            ["جمع هزینه‌ها", totalExpense],
            ["سود (زیان) خالص", totalRevenue + totalOtherRevenue - totalExpense],
            ["موجودی نقد و بانک", totalCash]
        ];

        const ws = stlpAcctBuildSheet("داشبورد حسابداری", ["شاخص", "مبلغ (ریال)"], rows, [1], [34, 22]);
        XLSX.utils.book_append_sheet(wb, ws, "داشبورد");
    })();


    // سرفصل حساب‌ها
    (function() {
        const sorted = stlpAccounts.slice().sort(function(a, b) { return String(a.code).localeCompare(String(b.code)); });
        const rows = sorted.map(function(a) {
            const parent = stlpFindAccountById(a.parentId);
            const bal = stlpAccountBalance(a.id);
            const side = stlpAccountNormalSide(a.type);
            const balance = side === "debit" ? (bal.debit - bal.credit) : (bal.credit - bal.debit);
            return [a.code, a.name, stlpAccountTypeLabel(a.type), parent ? parent.name : "—", balance];
        });
        const ws = stlpAcctBuildSheet("سرفصل حساب‌ها", ["کد", "نام حساب", "نوع", "زیرمجموعه‌ی", "مانده (ریال)"], rows, [4], [10, 28, 16, 24, 18]);
        XLSX.utils.book_append_sheet(wb, ws, "سرفصل حساب‌ها");
    })();


    // اسناد حسابداری
    (function() {
        const sortedEntries = stlpJournalEntries.slice().sort(function(a, b) { return (b.dateTs || 0) - (a.dateTs || 0); });
        const rows = [];
        sortedEntries.forEach(function(e) {
            const src = e.sourceType === "treasury" ? "خودکار" : "دستی";
            e.lines.forEach(function(l, lineIdx) {
                const acc = stlpFindAccountById(l.accountId);
                rows.push([
                    lineIdx === 0 ? e.number : "", lineIdx === 0 ? e.date : "", lineIdx === 0 ? e.description : "",
                    acc ? (acc.code + " — " + acc.name) : "—", l.debit || 0, l.credit || 0, lineIdx === 0 ? src : ""
                ]);
            });
        });
        const ws = stlpAcctBuildSheet("اسناد حسابداری", ["شماره سند", "تاریخ", "شرح سند", "حساب", "بدهکار (ریال)", "بستانکار (ریال)", "منبع"], rows, [4, 5], [12, 14, 30, 28, 16, 16, 16]);
        XLSX.utils.book_append_sheet(wb, ws, "اسناد حسابداری");
    })();


    // تراز آزمایشی
    (function() {
        const rows = stlpAccounts
            .map(function(a) { const bal = stlpAccountBalance(a.id); return { account: a, debit: bal.debit, credit: bal.credit }; })
            .filter(function(r) { return r.debit || r.credit; })
            .sort(function(a, b) { return String(a.account.code).localeCompare(String(b.account.code)); });
        const totalDebit = rows.reduce(function(a, r) { return a + r.debit; }, 0);
        const totalCredit = rows.reduce(function(a, r) { return a + r.credit; }, 0);
        const dataRows = rows.map(function(r) { return [r.account.code, r.account.name, r.debit, r.credit]; });
        dataRows.push(["", "جمع کل", totalDebit, totalCredit]);
        const ws = stlpAcctBuildSheet("تراز آزمایشی", ["کد", "نام حساب", "بدهکار (ریال)", "بستانکار (ریال)"], dataRows, [2, 3], [10, 30, 18, 18]);
        XLSX.utils.book_append_sheet(wb, ws, "تراز آزمایشی");
    })();


    // ترازنامه
    (function() {
        const byType = { asset: [], liability: [], equity: [] };
        stlpAccounts.forEach(function(a) {
            if (!byType[a.type]) return;
            const b = stlpAccountBalance(a.id);
            const bal = stlpAccountNormalSide(a.type) === "debit" ? (b.debit - b.credit) : (b.credit - b.debit);
            if (bal) byType[a.type].push({ name: a.name, bal: bal });
        });
        const revAccounts = stlpAccounts.filter(function(a) { return a.type === "revenue"; });
        const expAccounts = stlpAccounts.filter(function(a) { return a.type === "expense"; });
        const totalRevenue = revAccounts.reduce(function(sum, a) { const b = stlpAccountBalance(a.id); return sum + (b.credit - b.debit); }, 0);
        const totalExpense = expAccounts.reduce(function(sum, a) { const b = stlpAccountBalance(a.id); return sum + (b.debit - b.credit); }, 0);
        const netIncome = totalRevenue - totalExpense;
        const sumType = function(t) { return byType[t].reduce(function(a, x) { return a + x.bal; }, 0); };
        const rows = [];
        rows.push(["دارایی‌ها", "", ""]);
        byType.asset.forEach(function(x) { rows.push(["", x.name, x.bal]); });
        rows.push(["", "جمع دارایی‌ها", sumType("asset")]);
        rows.push(["", "", ""]);
        rows.push(["بدهی‌ها", "", ""]);
        byType.liability.forEach(function(x) { rows.push(["", x.name, x.bal]); });
        rows.push(["", "جمع بدهی‌ها", sumType("liability")]);
        rows.push(["", "", ""]);
        rows.push(["حقوق صاحبان سهام", "", ""]);
        byType.equity.forEach(function(x) { rows.push(["", x.name, x.bal]); });
        rows.push(["", "سود (زیان) دوره", netIncome]);
        rows.push(["", "جمع حقوق صاحبان سهام", sumType("equity") + netIncome]);
        const ws = stlpAcctBuildSheet("ترازنامه", ["گروه", "شرح", "مبلغ (ریال)"], rows, [2], [24, 32, 20]);
        XLSX.utils.book_append_sheet(wb, ws, "ترازنامه");
    })();


    // سود و زیان
    (function() {
        const revAccounts = stlpAccounts.filter(function(a) { return a.type === "revenue"; });
        const expAccounts = stlpAccounts.filter(function(a) { return a.type === "expense"; });
        const revRows = revAccounts.map(function(a) { const b = stlpAccountBalance(a.id); return { name: a.name, amount: b.credit - b.debit }; }).filter(function(r) { return r.amount; });
        const expRows = expAccounts.map(function(a) { const b = stlpAccountBalance(a.id); return { name: a.name, amount: b.debit - b.credit }; }).filter(function(r) { return r.amount; });
        const totalRev = revRows.reduce(function(a, r) { return a + r.amount; }, 0);
        const totalExp = expRows.reduce(function(a, r) { return a + r.amount; }, 0);
        const cogs = stlpComputeCOGS();
        const rows = [];
        rows.push(["درآمدها", ""]);
        revRows.forEach(function(r) { rows.push([r.name, r.amount]); });
        rows.push(["جمع درآمد", totalRev]);
        rows.push(["", ""]);
        rows.push(["بهای تمام‌شده‌ی کالای فروش‌رفته (COGS، تقریبی)", cogs]);
        rows.push(["سود ناخالص", totalRev - cogs]);
        rows.push(["", ""]);
        rows.push(["هزینه‌ها (عملیاتی/نقدی)", ""]);
        expRows.forEach(function(r) { rows.push([r.name, r.amount]); });
        rows.push(["جمع هزینه", totalExp]);
        rows.push(["", ""]);
        rows.push(["سود (زیان) خالص نقدی دوره (بدون COGS)", totalRev - totalExp]);
        rows.push(["سود (زیان) خالص واقعی‌تر (سود ناخالص − هزینه‌های نقدی)", (totalRev - cogs) - totalExp]);
        const ws = stlpAcctBuildSheet("صورت سود و زیان", ["شرح", "مبلغ (ریال)"], rows, [1], [40, 22]);
        XLSX.utils.book_append_sheet(wb, ws, "سود و زیان");
    })();


    // مانده مشتریان (AR)
    (function() {
        const list = stlpComputeCustomerBalances();
        const totalAR = list.reduce(function(s, c) { return s + c.total; }, 0);
        const rows = list.map(function(c) { return [c.name, c.deliveries.length, c.deliveries.map(function(d) { return "#" + d.deliveryNo; }).join("، "), c.total]; });
        rows.push(["", "", "جمع کل", totalAR]);
        const ws = stlpAcctBuildSheet("مانده مشتریان", ["مشتری", "تعداد حواله‌ی معوق", "شماره حواله‌ها", "مبلغ (ریال)"], rows, [3], [26, 16, 30, 20]);
        XLSX.utils.book_append_sheet(wb, ws, "مانده مشتریان");
    })();


    // مانده تأمین‌کنندگان (AP)
    (function() {
        const list = stlpComputeSupplierBalances();
        const totalAP = list.reduce(function(s, c) { return s + c.total; }, 0);
        const rows = list.map(function(s) { return [s.name, s.deliveries.length, s.deliveries.map(function(d) { return "#" + d.deliveryNo; }).join("، "), s.total]; });
        rows.push(["", "", "جمع کل", totalAP]);
        const ws = stlpAcctBuildSheet("مانده تأمین‌کنندگان", ["تأمین‌کننده", "تعداد حواله‌ی معوق", "شماره حواله‌ها", "مبلغ (ریال)"], rows, [3], [26, 16, 30, 20]);
        XLSX.utils.book_append_sheet(wb, ws, "مانده تأمین‌کنندگان");
    })();


    stlpAcctDownload(wb, "گزارش-کامل-حسابداری");

}


// =====================================================
// ویرایش
// =====================================================

function editTreasuryTransaction(id) {

    // =====================================================
    // تراکنش (با شناسه، نه اندیسِ آرایه)
    // =====================================================

    const item =
        stlpTreasury.find(function(t) { return t.id === id; });


    if (!item) {

        alert(
            "تراکنش پیدا نشد."
        );

        return;

    }


    // =====================================================
    // ذخیره شناسه‌ی ویرایش
    // =====================================================

    stlpTreasuryEditingId =
        id;


    // =====================================================
    // نوع تراکنش
    // =====================================================

    const type =
        item.type ||
        "in";


    const isTransfer =
        type === "transfer";


    const isCheque =
        !isTransfer &&
        item.method === "cheque";


    // =====================================================
    // پر کردن نوع
    // =====================================================

    const treasuryType =
        document.getElementById(
            "treasuryType"
        );


    if (treasuryType) {

        treasuryType.value =
            type;

    }


    // =====================================================
    // حساب
    //
    // چک:
    // حساب همان حسابی است که برای آن چک انتخاب/ذخیره شده
    //
    // انتقال:
    // حساب از مبدأ گرفته می‌شود
    //
    // عادی:
    // حساب خود تراکنش
    // =====================================================

    const treasuryAccount =
        document.getElementById(
            "treasuryAccount"
        );


    if (treasuryAccount) {

        if (isTransfer) {

            treasuryAccount.value =
                item.transferFrom ||
                item.account ||
                "cash";

        }

        else {

            treasuryAccount.value =
                item.account ||
                "cash";

        }

    }


    // =====================================================
    // مبلغ
    // =====================================================

    const treasuryAmount =
        document.getElementById(
            "treasuryAmount"
        );


    if (treasuryAmount) {

        treasuryAmount.value =
            item.amount ||
            0;

    }


    // =====================================================
    // تاریخ
    // =====================================================

    const treasuryDate =
        document.getElementById(
            "treasuryDate"
        );


    if (treasuryDate) {

        treasuryDate.value =
            item.date ||
            "";

    }


    // =====================================================
    // طرف حساب
    // =====================================================

    const treasuryParty =
        document.getElementById(
            "treasuryParty"
        );


    if (treasuryParty) {

        treasuryParty.value =
            item.party ||
            "";

    }


    // =====================================================
    // روش پرداخت
    // =====================================================

    const treasuryMethod =
        document.getElementById(
            "treasuryMethod"
        );


    if (treasuryMethod) {

        treasuryMethod.value =
            isTransfer
                ? "cash"
                : (
                    item.method ||
                    "cash"
                );

    }


    // =====================================================
    // پیگیری
    // =====================================================

    const treasuryTracking =
        document.getElementById(
            "treasuryTracking"
        );


    if (treasuryTracking) {

        treasuryTracking.value =
            item.tracking ||
            "";

    }


    // =====================================================
    // شماره فاکتور
    // =====================================================

    const treasuryInvoiceNo =
        document.getElementById(
            "treasuryInvoiceNo"
        );


    if (treasuryInvoiceNo) {

        treasuryInvoiceNo.value =
            item.invoiceNo ||
            "";

    }


    // =====================================================
    // توضیحات
    // =====================================================

    const treasuryDescription =
        document.getElementById(
            "treasuryDescription"
        );


    if (treasuryDescription) {

        treasuryDescription.value =
            item.description ||
            "";

    }


    // =====================================================
    // اطلاعات چک
    // =====================================================

    const treasuryCheckNo =
        document.getElementById(
            "treasuryCheckNo"
        );


    if (treasuryCheckNo) {

        treasuryCheckNo.value =
            item.checkNo ||
            "";

    }


    const treasuryCheckBank =
        document.getElementById(
            "treasuryCheckBank"
        );


    if (treasuryCheckBank) {

        treasuryCheckBank.value =
            item.checkBank ||
            "";

    }


    const treasuryCheckDueDate =
        document.getElementById(
            "treasuryCheckDueDate"
        );


    if (treasuryCheckDueDate) {

        treasuryCheckDueDate.value =
            item.checkDueDate ||
            "";

    }


    // =====================================================
    // مبدأ و مقصد انتقال
    // =====================================================

    const transferFrom =
        document.getElementById(
            "treasuryTransferFrom"
        );


    const transferTo =
        document.getElementById(
            "treasuryTransferTo"
        );


    if (transferFrom) {

        transferFrom.value =
            item.transferFrom ||
            item.account ||
            "cash";

    }


    if (transferTo) {

        transferTo.value =
            item.transferTo ||
            "bank";

    }


    // =====================================================
    // نمایش فیلدهای مربوطه
    // =====================================================

    updateTreasuryCheckFields();

    updateTreasuryTransferFields();


    // =====================================================
    // عنوان فرم
    // =====================================================

    const title =
        document.getElementById(
            "treasuryFormTitle"
        );


    if (title) {

        title.innerText =
            "ویرایش تراکنش";

    }


    // =====================================================
    // رفتن به فرم
    // =====================================================

    const form =
        document.getElementById(
            "treasuryFormTitle"
        );


    if (form) {

        form.scrollIntoView({
            behavior: "smooth",
            block: "start"
        });

    }

}


