// =====================================================
// ساخت خودکار حواله فروش بعد از ثبت فاکتور
// =====================================================

function stlpCreateSalesDelivery(invoice) {

    try {

        if (!invoice) {
            console.error("❌ اطلاعات فاکتور برای ساخت حواله وجود ندارد.");
            return false;
        }

        const invoiceNo =
            String(invoice.invoiceNo || "").trim();

        if (!invoiceNo) {
            console.error("❌ شماره فاکتور برای ساخت حواله وجود ندارد.");
            return false;
        }

        let deliveries = [];

        try {
            deliveries = JSON.parse(
                localStorage.getItem("salesDeliveries") || "[]"
            );
        } catch (error) {
            deliveries = [];
        }

        if (!Array.isArray(deliveries)) {
            deliveries = [];
        }

        // جلوگیری از ساخت حواله تکراری
        const duplicate = deliveries.some(function(delivery) {

            return String(
                delivery.invoiceNo || ""
            ).trim() === invoiceNo;

        });

        if (duplicate) {

            console.warn(
                "⚠️ برای این فاکتور قبلاً حواله ساخته شده:",
                invoiceNo
            );

            return true;
        }

        // شماره حواله
        const deliveryNo =
            "HV-" +
            String(deliveries.length + 1)
                .padStart(5, "0");

        const delivery = {

            id:
                Date.now() +
                "_" +
                Math.random()
                    .toString(36)
                    .substring(2, 8),

            deliveryNo:
                deliveryNo,

            invoiceNo:
                invoiceNo,

            customer:
                invoice.customer || "",

            date:
                invoice.date ||
                new Date().toLocaleDateString("fa-IR"),

            total:
                invoice.total || "0 ریال",

            items:
                Array.isArray(invoice.items)
                    ? invoice.items
                    : [],

            status:
                "pending",

            createdAt:
                new Date().toISOString(),

            source:
                "invoice"

        };

        deliveries.push(delivery);

        localStorage.setItem(
            "salesDeliveries",
            JSON.stringify(deliveries)
        );

        console.log(
            "✅ حواله فروش ساخته شد:",
            delivery
        );

        return true;

    } catch (error) {

        console.error(
            "❌ خطا در ساخت حواله فروش:",
            error
        );

        return false;
    }
}
// =====================================================
// مدیریت کامل چک‌های خزانه
// =====================================================

function getTreasuryChecks() {

    return stlpTreasury.filter(function(item) {

        return (
            item.method === "cheque" &&
            item.checkNo
        );

    });

}


// =====================================================
// نام وضعیت چک
// =====================================================

function treasuryCheckStatusName(status) {

    switch (status) {

        case "pending":
            return "⏳ در انتظار";

        case "approved":
            return "✅ تأیید شده";

        case "paid":
            return "💰 وصول شده";

        case "returned":
            return "↩️ برگشتی";

        default:
            return "-";

    }

}


// =====================================================
// کلاس وضعیت چک
// =====================================================

function treasuryCheckStatusClass(status) {

    switch (status) {

        case "pending":
            return "check-status-pending";

        case "approved":
            return "check-status-approved";

        case "paid":
            return "check-status-paid";

        case "returned":
            return "check-status-returned";

        default:
            return "check-status-pending";

    }

}


// =====================================================
// بروزرسانی داشبورد چک‌ها
// =====================================================

function renderTreasuryCheckDashboard() {

    const checks =
        getTreasuryChecks();


    let receivedTotal = 0;
    let issuedTotal = 0;
    let pendingTotal = 0;
    let approvedTotal = 0;


    checks.forEach(function(item) {

        const amount =
            Number(item.amount || 0);


        if (
            item.checkDirection ===
            "received"
        ) {

            receivedTotal += amount;

        }


        if (
            item.checkDirection ===
            "issued"
        ) {

            issuedTotal += amount;

        }


        if (
            item.checkStatus ===
            "pending"
        ) {

            pendingTotal += amount;

        }


        if (
            item.checkStatus ===
            "approved" ||
            item.checkStatus ===
            "paid"
        ) {

            approvedTotal += amount;

        }

    });


    const values =
        document.querySelectorAll(
            ".check-stat-value"
        );


    if (values.length >= 4) {

        values[0].textContent =
            stlpTreasuryMoney(
                receivedTotal
            );

        values[1].textContent =
            stlpTreasuryMoney(
                issuedTotal
            );

        values[2].textContent =
            stlpTreasuryMoney(
                pendingTotal
            );

        values[3].textContent =
            stlpTreasuryMoney(
                approvedTotal
            );

    }


    renderTreasuryChecksTable();
    stlpRenderDueChequesTab();
    stlpRenderReturnedChequesTab();

}


// =====================================================
// تبِ سه‌گانه‌ی مدیریتِ چک — همه/سررسیدشده/برگشتی
// =====================================================

function stlpSwitchCheckTab(name) {

    const panels = {
        all: document.getElementById("checkTabPanelAll"),
        due: document.getElementById("checkTabPanelDue"),
        returned: document.getElementById("checkTabPanelReturned")
    };

    const buttons = {
        all: document.getElementById("checkTabBtnAll"),
        due: document.getElementById("checkTabBtnDue"),
        returned: document.getElementById("checkTabBtnReturned")
    };

    if (!panels.all || !panels.due || !panels.returned) return;

    Object.keys(panels).forEach(function(key) {
        panels[key].style.display = key === name ? "" : "none";
        if (buttons[key]) buttons[key].style.outline = key === name ? "2px solid #0fa37f" : "none";
    });

}


// چک‌هایی که هنوز تأیید/وصول یا برگشت نخورده‌اند (pending/approved) و
// تاریخِ سررسیدشان امروز رسیده یا گذشته — تا این‌جا اضافه نشده بود،
// تنها راهِ دیدنشان گشتن در کل جدولِ چک‌ها بود
function stlpRenderDueChequesTab() {

    const table = document.getElementById("dueChequesTable");
    if (!table) return;

    const todayLinear = stlpParseLooseJalaliDate(new Date().toLocaleDateString("fa-IR"));

    const due =
        getTreasuryChecks()
            .filter(function(item) {

                if (item.checkStatus !== "pending" && item.checkStatus !== "approved") return false;

                const dueLinear = stlpParseLooseJalaliDate(item.checkDueDate);

                return dueLinear !== null && dueLinear <= todayLinear;

            })
            .sort(function(a, b) {
                return stlpParseLooseJalaliDate(a.checkDueDate) - stlpParseLooseJalaliDate(b.checkDueDate);
            });

    if (due.length === 0) {
        table.innerHTML = '<tr><td colspan="8" style="text-align:center; color:#888; padding:20px;">فعلاً هیچ چکِ سررسیدشده‌ای وجود ندارد</td></tr>';
        return;
    }

    table.innerHTML =
        due.map(function(item) {

            const realIndex = stlpTreasury.indexOf(item);
            const dueLinear = stlpParseLooseJalaliDate(item.checkDueDate);
            const isOverdue = dueLinear < todayLinear;

            const typeHtml =
                item.checkDirection === "received"
                    ? '<span class="money-in">💚 دریافتی</span>'
                    : '<span class="money-out">🔴 پرداختی</span>';

            const actions =
                (item.checkStatus === "pending"
                    ? '<button type="button" class="check-action-btn check-approve-btn" onclick="approveTreasuryCheck(' + realIndex + ')">✅ تأیید</button>'
                    : '<button type="button" class="check-action-btn check-approve-btn" onclick="payTreasuryCheck(' + realIndex + ')">💰 وصول / پرداخت</button>') +
                '<button type="button" class="check-action-btn check-return-btn" onclick="returnTreasuryCheck(' + realIndex + ')">↩️ برگشت</button>';

            return (
                '<tr' + (isOverdue ? ' style="background:rgba(220,53,69,.12);"' : '') + '>' +
                    '<td>' + typeHtml + '</td>' +
                    '<td>' + escapeHtml(item.checkNo || "-") + '</td>' +
                    '<td>' + escapeHtml(item.checkBank || "-") + '</td>' +
                    '<td>' + escapeHtml(item.party || "-") + '</td>' +
                    '<td>' + stlpTreasuryMoney(item.amount) + '</td>' +
                    '<td>' + escapeHtml(item.checkDueDate || "-") + (isOverdue ? ' <span style="color:#dc3545; font-size:11px;">(گذشته)</span>' : ' <span style="color:#f0ad4e; font-size:11px;">(امروز)</span>') + '</td>' +
                    '<td><span class="check-status ' + treasuryCheckStatusClass(item.checkStatus) + '">' + treasuryCheckStatusName(item.checkStatus) + '</span></td>' +
                    '<td><div style="display:flex; flex-wrap:wrap; gap:6px; justify-content:center;">' + actions + '</div></td>' +
                '</tr>'
            );

        }).join("");

}


// چک‌های برگشتی — اگر به یک حواله‌ی تسویه‌شده وصل بودند، همون لحظه‌ی
// برگشت (stlpReopenDeliveryForBouncedCheck) آن حواله را خودکار دوباره
// در انتظارِ تسویه گذاشته، پس مسیرِ حل‌شدنش همون دکمه‌ی «تسویه شد»ی
// حواله‌هاست (نقد یا چکِ تازه) — این‌جا فقط لینکش نشون داده می‌شه. اگر
// وصل نبودند (چکِ مستقل)، مستقیماً از همین‌جا تعیین‌تکلیف می‌شن.
function stlpRenderReturnedChequesTab() {

    const table = document.getElementById("returnedChequesTable");
    if (!table) return;

    let deliveries;

    try {
        deliveries = JSON.parse(localStorage.getItem("salesDeliveries") || "[]");
    } catch (error) {
        deliveries = [];
    }

    if (!Array.isArray(deliveries)) deliveries = [];

    const returned = getTreasuryChecks().filter(function(item) { return item.checkStatus === "returned"; });

    if (returned.length === 0) {
        table.innerHTML = '<tr><td colspan="7" style="text-align:center; color:#888; padding:20px;">فعلاً هیچ چکِ برگشتیِ حل‌نشده‌ای وجود ندارد</td></tr>';
        return;
    }

    table.innerHTML =
        returned.map(function(item) {

            const realIndex = stlpTreasury.indexOf(item);

            const typeHtml =
                item.checkDirection === "received"
                    ? '<span class="money-in">💚 دریافتی</span>'
                    : '<span class="money-out">🔴 پرداختی</span>';

            const invoiceNo = String(item.invoiceNo || "").trim();

            const linkedDelivery =
                invoiceNo
                    ? deliveries.find(function(d) {
                        return String(d.invoiceNo || "").trim() === invoiceNo &&
                            ((item.source === "purchase-settlement" || item.source === "purchase") ? d.direction === "purchase" : d.direction !== "purchase") &&
                            d.treasuryRegistered === false;
                      })
                    : null;

            // همان حواله که بعد از برگشتِ چک دوباره تسویه شده (نقد یا چکِ تازه) —
            // بدونِ این، چکِ برگشتیِ قدیمی دوباره دکمه‌های «پرداختِ نقدی/جایگزین»
            // نشان می‌داد و کلیکش یک پرداختِ دوم برای همان فاکتور ثبت می‌کرد
            const reSettledDelivery =
                invoiceNo
                    ? deliveries.find(function(d) {
                        return String(d.invoiceNo || "").trim() === invoiceNo &&
                            ((item.source === "purchase-settlement" || item.source === "purchase") ? d.direction === "purchase" : d.direction !== "purchase") &&
                            d.treasuryRegistered === true;
                      })
                    : null;

            let resolutionHtml;

            if (item.chequeResolved) {

                resolutionHtml = '<span style="color:#0fa37f;">✅ ' + escapeHtml(item.chequeResolutionNote || "تعیین‌تکلیف شد") + '</span>';

            } else if (reSettledDelivery && !linkedDelivery) {

                resolutionHtml = '<span style="color:#0fa37f;">✅ حواله‌ی شماره‌ی ' + escapeHtml(reSettledDelivery.deliveryNo || "-") + ' بعد از برگشتِ این چک دوباره تسویه شد</span>';

            } else if (linkedDelivery) {

                resolutionHtml =
                    '<span style="color:#f0ad4e;">🔗 مربوطِ به حواله‌ی شماره‌ی ' + escapeHtml(linkedDelivery.deliveryNo || "-") + ' — دوباره در انتظارِ تسویه است</span><br>' +
                    '<a href="sales-delivery.html" style="color:#0d6efd; font-size:12px;">برو به حواله‌ها برای تسویه‌ی مجدد (نقد یا چکِ تازه)</a>';

            } else {

                resolutionHtml =
                    '<div style="display:flex; flex-wrap:wrap; gap:6px; justify-content:center;">' +
                        '<button type="button" class="check-action-btn check-approve-btn" onclick="stlpResolveChequeCash(' + realIndex + ')">💵 پرداخت/دریافتِ نقدی</button>' +
                        '<button type="button" class="check-action-btn check-approve-btn" onclick="stlpResolveChequeReplace(' + realIndex + ')">🔁 چکِ جایگزین</button>' +
                        '<button type="button" class="check-action-btn check-view-btn" onclick="stlpResolveChequeOther(' + realIndex + ')">✏️ حالتِ دیگر</button>' +
                    '</div>';

            }

            return (
                '<tr>' +
                    '<td>' + typeHtml + '</td>' +
                    '<td>' + escapeHtml(item.checkNo || "-") + '</td>' +
                    '<td>' + escapeHtml(item.checkBank || "-") + '</td>' +
                    '<td>' + escapeHtml(item.party || "-") + '</td>' +
                    '<td>' + stlpTreasuryMoney(item.amount) + '</td>' +
                    '<td>' + escapeHtml(item.checkDueDate || "-") + '</td>' +
                    '<td>' + resolutionHtml + '</td>' +
                '</tr>'
            );

        }).join("");

}


// تراکنشِ جایگزین باید «نوعِ منبع»ِ چکِ اصلی را حفظ کند (تسویه‌ی
// فروش/خرید) — وگرنه در سندِ حسابداری به‌جای درآمد/هزینه‌ی فروش و
// خرید، به «سایر درآمد/هزینه» می‌رفت و تطبیقِ چک با حواله از بین می‌رفت
function stlpChequeResolutionSource(item) {

    const keep = ["delivery-settlement", "purchase-settlement", "invoice", "purchase"];

    return keep.indexOf(item.source) !== -1 ? item.source : "cheque-resolution";

}

// تاریخِ شمسیِ قابل‌قبول برای سررسید: سالِ ۱۳xx/۱۴xx، ماه ۱–۱۲، روز ۱–۳۱
// (تاریخِ میلادی یا فرمتِ نامعلوم در تبِ «سررسیدشده‌ها» بی‌صدا نادیده
// گرفته می‌شد)
function stlpIsValidJalaliDateText(text) {

    const linear = stlpParseLooseJalaliDate(text);

    if (linear === null) return false;

    const year = Math.floor(linear / 10000);
    const month = Math.floor((linear % 10000) / 100);
    const day = linear % 100;

    return year >= 1300 && year <= 1500 && month >= 1 && month <= 12 && day >= 1 && day <= 31;

}

// اگر تراکنشِ تعیین‌تکلیف (نقدی/چکِ جایگزین) حذف شد، چکِ اصلی دوباره
// «تعیین‌تکلیف‌نشده» می‌شود — وگرنه برای همیشه «✅ تسویه شد» می‌ماند در
// حالی که هیچ پرداخت/چکی پشتش نیست
function stlpUnresolveChequesForDeletedTx(deletedId) {

    if (!deletedId) return;

    stlpTreasury.forEach(function(item) {

        if (item.chequeResolvedTxId === deletedId) {
            item.chequeResolved = false;
            delete item.chequeResolvedTxId;
            delete item.chequeResolutionNote;
        }

    });

}

// چکِ برگشتیِ مستقل (بدونِ حواله‌ی وصل) را با یک تراکنشِ نقدی به همون
// مبلغ تسویه می‌کند و چکِ اصلی را «تعیین‌تکلیف‌شده» علامت می‌زند
function stlpResolveChequeCash(index) {

    const item = stlpTreasury[index];
    if (!item) return;

    if (item.checkStatus !== "returned") {
        alert("این عملیات فقط برای چک‌های برگشتی مجاز است.");
        return;
    }

    if (item.chequeResolved) {
        alert("این چک قبلاً تعیین‌تکلیف شده است.");
        return;
    }

    // حساب باید یکی از حساب‌های واقعیِ خزانه باشد — قبلاً هر متنی (حتی اسمِ
    // حساب به‌جای شناسه) ذخیره می‌شد و یک «حسابِ شبح» بدونِ سندِ
    // حسابداری می‌ساخت
    const accountsList = Array.isArray(stlpTreasuryAccounts) ? stlpTreasuryAccounts : [];

    const accountInput = prompt(
        (item.checkDirection === "received" ? "این مبلغ نقداً به کدام حساب دریافت شود؟" : "این مبلغ نقداً از کدام حساب پرداخت شود؟") +
        "\n(یکی از این‌ها را وارد کنید: " +
        accountsList.map(function(a) { return a.id + " = " + a.name; }).join("، ") + ")",
        item.account || "cash"
    );

    if (accountInput === null) return;

    const typedAccount = accountInput.trim().toLowerCase();

    const accountObj = accountsList.find(function(a) {
        return String(a.id).toLowerCase() === typedAccount || String(a.name).trim().toLowerCase() === typedAccount;
    });

    if (!accountObj) {
        alert("❌ حسابی با این شناسه/نام پیدا نشد.");
        return;
    }

    const account = accountObj.id;

    // پرداختِ نقدی نباید حساب را منفی کند (همان چکِ فرمِ ثبتِ دستیِ تراکنش)
    if (item.checkDirection !== "received") {

        const currentBalance = Number(getTreasuryAccountBalances()[account] || 0);

        if (Number(item.amount || 0) > currentBalance) {
            alert("❌ موجودیِ حسابِ «" + accountObj.name + "» (" + stlpTreasuryMoney(currentBalance) + ") برای این پرداخت کافی نیست.");
            return;
        }

    }

    if (!confirm(
        "ثبتِ یک تراکنشِ نقدیِ " + stlpTreasuryMoney(item.amount) + " به‌جای چکِ برگشتیِ «" + (item.checkNo || "-") + "»، تأیید می‌کنید؟"
    )) return;

    const transaction = {

        id: Date.now() + "_" + Math.random().toString(36).substring(2, 8),
        type: item.checkDirection === "received" ? "in" : "out",
        account: account,
        transferFrom: "",
        transferTo: "",
        amount: Number(item.amount || 0),
        date: new Date().toLocaleDateString("fa-IR"),
        party: item.party || "",
        method: "cash",
        tracking: "",
        invoiceNo: item.invoiceNo || "",
        description: "پرداخت/دریافتِ نقدی به‌جای چکِ برگشتیِ شماره " + (item.checkNo || "-"),
        checkNo: "",
        checkBank: "",
        checkDueDate: "",
        checkStatus: "",
        checkDirection: "",
        balanceApplied: true,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        source: stlpChequeResolutionSource(item)

    };

    stlpTreasury.push(transaction);

    item.chequeResolved = true;
    item.chequeResolvedTxId = transaction.id;
    item.chequeResolutionNote = "با پرداخت/دریافتِ نقدی (" + new Date().toLocaleDateString("fa-IR") + ") تسویه شد";

    saveTreasury();

    if (typeof saveTreasuryAccountingEntry === "function") saveTreasuryAccountingEntry(transaction);

    if (typeof stlpLogActivity === "function") {
        stlpLogActivity("خزانه", "تعیین‌تکلیف چک برگشتی", "چک شماره " + (item.checkNo || "-") + " — پرداخت/دریافت نقدی جایگزین");
    }

    renderTreasuryCheckDashboard();
    if (typeof renderTreasury === "function") renderTreasury();

    alert("✅ ثبت شد.");

}


// چکِ برگشتیِ مستقل را با یک چکِ تازه (شماره/بانک/سررسیدِ جدید) جایگزین
// می‌کند — چکِ جدید با وضعیتِ «در انتظار» ثبت می‌شود و از همون تبِ
// «سررسیدشده‌ها» قابل‌پیگیری خواهد بود
function stlpResolveChequeReplace(index) {

    const item = stlpTreasury[index];
    if (!item) return;

    if (item.checkStatus !== "returned") {
        alert("این عملیات فقط برای چک‌های برگشتی مجاز است.");
        return;
    }

    if (item.chequeResolved) {
        alert("این چک قبلاً تعیین‌تکلیف شده است.");
        return;
    }

    const newCheckNo = prompt("شماره‌ی چکِ جایگزین:");
    if (newCheckNo === null || !newCheckNo.trim()) return;

    const duplicateCheckNo = stlpTreasury.some(function(t) {
        return t.method === "cheque" && String(t.checkNo || "").trim() === newCheckNo.trim() &&
            String(t.checkBank || "").trim() === String(item.checkBank || "").trim();
    });

    if (duplicateCheckNo && !confirm("⚠️ چکی با همین شماره قبلاً ثبت شده است. با این حال ادامه می‌دهید؟")) return;

    const newCheckBankInput = prompt("بانکِ چکِ جایگزین:", item.checkBank || "");
    if (newCheckBankInput === null) return;
    const newCheckBank = newCheckBankInput;

    const newDueDate = prompt("تاریخِ سررسیدِ چکِ جایگزین (مثلاً 1404/08/01):");
    if (newDueDate === null || !newDueDate.trim()) return;

    if (!stlpIsValidJalaliDateText(newDueDate)) {
        alert("❌ تاریخ سررسید را به‌صورتِ شمسی (مثلاً 1404/08/01) وارد کنید.");
        return;
    }

    if (!confirm(
        "ثبتِ چکِ جایگزین به‌جای چکِ برگشتیِ «" + (item.checkNo || "-") + "»، تأیید می‌کنید؟"
    )) return;

    const transaction = {

        id: Date.now() + "_" + Math.random().toString(36).substring(2, 8),
        type: item.type,
        account: item.account,
        transferFrom: "",
        transferTo: "",
        amount: Number(item.amount || 0),
        date: new Date().toLocaleDateString("fa-IR"),
        party: item.party || "",
        method: "cheque",
        tracking: "",
        invoiceNo: item.invoiceNo || "",
        description: "چکِ جایگزینِ چکِ برگشتیِ شماره " + (item.checkNo || "-"),
        checkNo: newCheckNo.trim(),
        checkBank: newCheckBank.trim(),
        checkDueDate: newDueDate.trim(),
        checkStatus: "pending",
        checkDirection: item.checkDirection,
        balanceApplied: false,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        source: stlpChequeResolutionSource(item)

    };

    stlpTreasury.push(transaction);

    item.chequeResolved = true;
    item.chequeResolvedTxId = transaction.id;
    item.chequeResolutionNote = "با چکِ جایگزینِ شماره‌ی «" + newCheckNo.trim() + "» تعویض شد";

    saveTreasury();

    if (typeof stlpLogActivity === "function") {
        stlpLogActivity("خزانه", "تعیین‌تکلیف چک برگشتی", "چک شماره " + (item.checkNo || "-") + " — جایگزین شد با چک شماره " + newCheckNo.trim());
    }

    renderTreasuryCheckDashboard();

    alert("✅ چکِ جایگزین ثبت شد (وضعیت: در انتظار).");

}


// برای هر حالتِ دیگری که پرداخت نقدی یا چکِ جایگزین نیست (مثلاً بعداً
// دوباره به بانک برده شد و پاس شد، یا بخشیده شد) — فقط یک یادداشتِ
// آزاد می‌گیرد و چک را «تعیین‌تکلیف‌شده» علامت می‌زند
function stlpResolveChequeOther(index) {

    const item = stlpTreasury[index];
    if (!item) return;

    if (item.checkStatus !== "returned") {
        alert("این عملیات فقط برای چک‌های برگشتی مجاز است.");
        return;
    }

    if (item.chequeResolved) {
        alert("این چک قبلاً تعیین‌تکلیف شده است.");
        return;
    }

    const note = prompt(
        "توضیح بده این چکِ برگشتی چطور تعیین‌تکلیف شد (مثلاً «دوباره به بانک برده شد و پاس شد»، «بخشیده شد»، ...):"
    );

    if (note === null || !note.trim()) return;

    item.chequeResolved = true;
    item.chequeResolutionNote = note.trim();

    saveTreasury();

    if (typeof stlpLogActivity === "function") {
        stlpLogActivity("خزانه", "تعیین‌تکلیف چک برگشتی", "چک شماره " + (item.checkNo || "-") + " — " + note.trim());
    }

    renderTreasuryCheckDashboard();

    alert("✅ ثبت شد.");

}


// =====================================================
// جدول چک‌ها
// =====================================================

function renderTreasuryChecksTable() {

    const table =
        document.getElementById(
            "treasuryCheckTable"
        );


    if (!table) return;


    const search =
        document.getElementById(
            "checkSearch"
        )?.value
        ?.trim()
        .toLowerCase() || "";


    const statusFilter =
        document.getElementById(
            "checkStatusFilter"
        )?.value || "";


    const typeFilter =
        document.getElementById(
            "checkTypeFilter"
        )?.value || "";


    const bankFilter =
        document.getElementById(
            "checkBankFilter"
        )?.value
        ?.trim()
        .toLowerCase() || "";


    let checks =
        getTreasuryChecks();


    checks =
        checks.filter(function(item) {

            const checkNo =
                String(
                    item.checkNo || ""
                ).toLowerCase();


            const party =
                String(
                    item.party || ""
                ).toLowerCase();


            const bank =
                String(
                    item.checkBank || ""
                ).toLowerCase();


            const matchesSearch =
                !search ||
                checkNo.includes(search) ||
                party.includes(search);


            const matchesStatus =
                !statusFilter ||
                item.checkStatus ===
                    statusFilter;


            const matchesType =
                !typeFilter ||
                item.checkDirection ===
                    typeFilter;


            const matchesBank =
                !bankFilter ||
                bank.includes(bankFilter);


            return (
                matchesSearch &&
                matchesStatus &&
                matchesType &&
                matchesBank
            );

        });


    if (checks.length === 0) {

        table.innerHTML = `

            <tr>

                <td colspan="9">

                    چکی مطابق فیلتر فعلی پیدا نشد.

                </td>

            </tr>

        `;

        return;

    }


    table.innerHTML = "";


    checks.forEach(function(item) {

        const realIndex =
            stlpTreasury.indexOf(
                item
            );


        const amount =
            Number(
                item.amount || 0
            );


        const typeHtml =

            item.checkDirection ===
            "received"

                ? `
                    <span class="money-in">
                        💚 دریافتی
                    </span>
                  `

                : `
                    <span class="money-out">
                        🔴 پرداختی
                    </span>
                  `;


        const status =
            item.checkStatus ||
            "pending";


        const statusHtml = `

            <span
                class="check-status
                ${treasuryCheckStatusClass(status)}"
            >

                ${treasuryCheckStatusName(status)}

            </span>

        `;


        let actions = `

            <button
                type="button"
                class="check-action-btn check-view-btn"
                onclick="
                    viewTreasuryCheck(${realIndex})
                "
            >
                👁 مشاهده
            </button>

        `;


        if (status === "pending") {

            actions += `

                <button
                    type="button"
                    class="check-action-btn check-approve-btn"
                    onclick="
                        approveTreasuryCheck(${realIndex})
                    "
                >
                    ✅ تأیید
                </button>

                <button
                    type="button"
                    class="check-action-btn check-return-btn"
                    onclick="
                        returnTreasuryCheck(${realIndex})
                    "
                >
                    ↩️ برگشت
                </button>

            `;

        }


        else if (
            status === "approved"
        ) {

            actions += `

                <button
                    type="button"
                    class="check-action-btn check-approve-btn"
                    onclick="
                        payTreasuryCheck(${realIndex})
                    "
                >
                    💰 وصول / پرداخت
                </button>

                <button
                    type="button"
                    class="check-action-btn check-return-btn"
                    onclick="
                        returnTreasuryCheck(${realIndex})
                    "
                >
                    ↩️ برگشت
                </button>

            `;

        }


        else if (
            status === "paid"
        ) {

            actions += `

                <button
                    type="button"
                    class="check-action-btn check-view-btn"
                    onclick="
                        reverseTreasuryCheck(${realIndex})
                    "
                >
                    ↩️ برگشت از وصول
                </button>

            `;

        }


        const row =
            document.createElement(
                "tr"
            );


        row.innerHTML = `

            <td>
                ${(
                    realIndex + 1
                ).toLocaleString("fa-IR")}
            </td>

            <td>
                ${typeHtml}
            </td>

            <td>
                ${escapeHtml(
                    item.checkNo || "-"
                )}
            </td>

            <td>
                ${escapeHtml(
                    item.checkBank || "-"
                )}
            </td>

            <td>
                ${escapeHtml(
                    item.party || "-"
                )}
            </td>

            <td>
                <strong>
                    ${stlpTreasuryMoney(
                        amount
                    )}
                </strong>
            </td>

            <td>
                ${escapeHtml(
                    item.checkDueDate || "-"
                )}
            </td>

            <td>
                ${statusHtml}
            </td>

            <td>
                ${actions}
            </td>

        `;


        table.appendChild(
            row
        );

    });

}


// =====================================================
// مشاهده چک
// =====================================================

function viewTreasuryCheck(index) {

    const item =
        stlpTreasury[index];


    if (!item) return;


    alert(

        "📋 اطلاعات چک\n\n" +

        "نوع: " +
        (
            item.checkDirection ===
            "received"
                ? "دریافتی"
                : "پرداختی"
        ) +

        "\n\n" +

        "شماره چک: " +
        (item.checkNo || "-") +

        "\n\n" +

        "بانک: " +
        (item.checkBank || "-") +

        "\n\n" +

        "طرف حساب: " +
        (item.party || "-") +

        "\n\n" +

        "مبلغ: " +
        stlpTreasuryMoney(
            item.amount
        ) +

        "\n\n" +

        "سررسید: " +
        (item.checkDueDate || "-") +

        "\n\n" +

        "وضعیت: " +
        treasuryCheckStatusName(
            item.checkStatus
        )

    );

}


// =====================================================
// تأیید چک
// =====================================================

function approveTreasuryCheck(index) {

    const item =
        stlpTreasury[index];


    if (!item) return;


    if (
        item.method !== "cheque"
    ) {

        return;

    }


    if (
        item.checkStatus !==
        "pending"
    ) {

        return;

    }


    item.checkStatus =
        "approved";


    item.balanceApplied =
        false;


    item.updatedAt =
        new Date().toISOString();


    saveTreasury();

    saveTreasuryAccountingEntry(item);

    stlpLogActivity("خزانه", "تأیید چک", "چک شماره " + (item.checkNo || "-") + " — " + stlpTreasuryMoney(item.amount) + (item.party ? " — " + item.party : ""));

    renderTreasury();

    renderTreasuryCheckDashboard();


    alert(
        "✅ چک با موفقیت تأیید شد."
    );

}


// =====================================================
// وصول / پرداخت چک
// =====================================================

function payTreasuryCheck(index) {

    const item =
        stlpTreasury[index];


    if (!item) return;


    if (
        item.method !== "cheque"
    ) {

        return;

    }


    if (
        item.checkStatus !==
        "approved"
    ) {

        alert(
            "ابتدا باید چک تأیید شود."
        );

        return;

    }


    const amount =
        Number(
            item.amount || 0
        );


    const account =
        item.account ||
        "cash";


    const balances =
        getTreasuryAccountBalances();


    const available =
        Number(
            balances[account] || 0
        );


    /*
     * چک دریافتی:
     * با وصول، موجودی حساب زیاد می‌شود.
     *
     * چک پرداختی:
     * با پرداخت، باید موجودی کافی باشد.
     */

    if (
        item.checkDirection ===
        "issued"
    ) {

        if (
            amount > available
        ) {

            alert(

                "❌ موجودی حساب برای پرداخت چک کافی نیست.\n\n" +

                "حساب: " +
                stlpTreasuryAccountName(
                    account
                ) +

                "\n\n" +

                "موجودی: " +
                stlpTreasuryMoney(
                    available
                ) +

                "\n\n" +

                "مبلغ چک: " +
                stlpTreasuryMoney(
                    amount
                )

            );

            return;

        }

    }


    const confirmed =
        confirm(

            "آیا از ثبت وصول / پرداخت این چک مطمئن هستید؟\n\n" +

            "مبلغ: " +
            stlpTreasuryMoney(
                amount
            )

        );


    if (!confirmed) return;


    item.checkStatus =
        "paid";


    item.balanceApplied =
        true;


    item.updatedAt =
        new Date().toISOString();


    saveTreasury();

    saveTreasuryAccountingEntry(item);

    stlpLogActivity("خزانه", "وصول/پرداخت چک", "چک شماره " + (item.checkNo || "-") + " — " + stlpTreasuryMoney(item.amount) + (item.party ? " — " + item.party : ""));

    renderTreasury();

    renderTreasuryCheckDashboard();


    alert(
        "✅ چک با موفقیت وصول / پرداخت شد."
    );

}


// =====================================================
// برگشت چک
// =====================================================

// وقتی تراکنشِ خزانه‌ای که بابت تسویه‌ی یک حواله‌ی نسیه ثبت شده بود
// از بین می‌رود (چکش برگشت می‌خورد/وصولش لغو می‌شود، یا خودِ تراکنش
// — نقدی یا چکی — مستقیماً حذف می‌شود)، آن حواله دیگر واقعاً
// تسویه‌نشده است — قبلاً delivery.treasuryRegistered برای همیشه true
// می‌ماند (فقط با رد/لغوِ خودِ حواله false می‌شد)، یعنی
// stlpComputeSupplierBalances/stlpComputeCustomerBalances دیگر
// هیچ‌وقت این بدهی را نشان نمی‌دادند، حتی وقتی پولی واقعاً دریافت/
// پرداخت نشده بود. علی‌رغمِ نامِ تابع (که از سناریوی اولیه‌ی برگشتِ
// چک مانده)، منطقش به روشِ پرداخت وابسته نیست — برای حذفِ هر نوع
// تراکنشِ تسویه (نقدی یا چکی) هم صدا زده می‌شود.
function stlpReopenDeliveryForBouncedCheck(item) {

    if (!item) return;

    const invoiceNo = String(item.invoiceNo || "").trim();
    if (!invoiceNo) return;

    const isPurchase = item.source === "purchase-settlement" || item.source === "purchase";

    let deliveries;

    try {
        deliveries = JSON.parse(localStorage.getItem("salesDeliveries") || "[]");
    } catch (error) {
        return;
    }

    if (!Array.isArray(deliveries)) return;

    const delivery = deliveries.find(function(d) {
        return (
            String(d.invoiceNo || "").trim() === invoiceNo &&
            (isPurchase ? d.direction === "purchase" : d.direction !== "purchase") &&
            d.treasuryRegistered === true
        );
    });

    if (!delivery) return;

    delivery.treasuryRegistered = false;
    delivery.settledAt = null;
    delivery.settlementMethod = null;
    delivery.settlementAccount = null;

    localStorage.setItem("salesDeliveries", JSON.stringify(deliveries));

    if (typeof renderSalesDeliveries === "function") renderSalesDeliveries();

}


function returnTreasuryCheck(index) {

    const item =
        stlpTreasury[index];


    if (!item) return;


    if (
        item.checkStatus ===
        "paid"
    ) {

        alert(
            "این چک قبلاً وصول / پرداخت شده است."
        );

        return;

    }


    const confirmed =
        confirm(
            "آیا از برگشت زدن این چک مطمئن هستید؟"
        );


    if (!confirmed) return;


    item.checkStatus =
        "returned";


    item.balanceApplied =
        false;


    item.updatedAt =
        new Date().toISOString();


    saveTreasury();

    saveTreasuryAccountingEntry(item);

    stlpReopenDeliveryForBouncedCheck(item);

    stlpLogActivity("خزانه", "برگشت چک", "چک شماره " + (item.checkNo || "-") + " — " + stlpTreasuryMoney(item.amount) + (item.party ? " — " + item.party : ""));

    renderTreasury();

    renderTreasuryCheckDashboard();


    alert(
        "↩️ چک به وضعیت برگشتی تغییر کرد."
    );

}


// =====================================================
// برگشت از وصول
// =====================================================

function reverseTreasuryCheck(index) {

    const item =
        stlpTreasury[index];


    if (!item) return;


    if (
        item.checkStatus !==
        "paid"
    ) {

        return;

    }


    const confirmed =
        confirm(
            "آیا می‌خواهید وصول / پرداخت این چک برگشت داده شود؟"
        );


    if (!confirmed) return;


    item.checkStatus =
        "returned";


    item.balanceApplied =
        false;


    item.updatedAt =
        new Date().toISOString();


    saveTreasury();

    saveTreasuryAccountingEntry(item);

    stlpReopenDeliveryForBouncedCheck(item);

    stlpLogActivity("خزانه", "برگشت از وصول چک", "چک شماره " + (item.checkNo || "-") + " — " + stlpTreasuryMoney(item.amount) + (item.party ? " — " + item.party : ""));

    renderTreasury();

    renderTreasuryCheckDashboard();


    alert(
        "↩️ اثر چک از موجودی حذف شد."
    );

}


// =====================================================
// فیلتر چک‌ها
// =====================================================

function filterTreasuryChecks() {

    renderTreasuryCheckDashboard();

}


// =====================================================
// پر کردن لیست بانک‌های چک
// =====================================================

function populateTreasuryCheckBanks() {

    const select =
        document.getElementById(
            "checkBankFilter"
        );


    if (!select) return;


    const current =
        select.value;


    const banks = [];


    getTreasuryChecks().forEach(
        function(item) {

            const bank =
                String(
                    item.checkBank || ""
                ).trim();


            if (
                bank &&
                !banks.includes(bank)
            ) {

                banks.push(bank);

            }

        }
    );


    select.innerHTML = `

        <option value="">
            همه بانک‌ها
        </option>

    `;


    banks.sort().forEach(
        function(bank) {

            const option =
                document.createElement(
                    "option"
                );


            option.value =
                bank;


            option.textContent =
                bank;


            select.appendChild(
                option
            );

        }
    );


    select.value =
        current;

}


// =====================================================
// دکمه ثبت چک
// =====================================================

function openTreasuryCheckForm() {

    const type =
        document.getElementById(
            "treasuryType"
        );


    const method =
        document.getElementById(
            "treasuryMethod"
        );


    if (type) {

        type.value =
            "in";

    }


    if (method) {

        method.value =
            "cheque";

    }


    updateTreasuryCheckFields();


    const form =
        document.getElementById(
            "treasuryFormTitle"
        );


    if (form) {

        form.scrollIntoView({
            behavior: "smooth",
            block: "start"
        });

    }

}


// =====================================================
// راه‌اندازی داشبورد چک‌ها
// =====================================================

function initTreasuryCheckDashboard() {

    const button =
        document.querySelector(
            ".check-dashboard-btn"
        );


    if (
        button &&
        !button.dataset.initialized
    ) {

        button.dataset.initialized =
            "true";


        button.addEventListener(
            "click",
            openTreasuryCheckForm
        );

    }


    const search =
        document.getElementById(
            "checkSearch"
        );


    const status =
        document.getElementById(
            "checkStatusFilter"
        );


    const type =
        document.getElementById(
            "checkTypeFilter"
        );


    const bank =
        document.getElementById(
            "checkBankFilter"
        );


    [search, status, type, bank]
        .forEach(function(el) {

            if (
                el &&
                !el.dataset.checkFilterInitialized
            ) {

                el.dataset.checkFilterInitialized =
                    "true";


                el.addEventListener(
                    "input",
                    filterTreasuryChecks
                );


                el.addEventListener(
                    "change",
                    filterTreasuryChecks
                );

            }

        });


    populateTreasuryCheckBanks();

    renderTreasuryCheckDashboard();

}


