function inventoryMovementReport() {

    if (!Array.isArray(inventoryMovements)) {

        alert("⚠️ هنوز هیچ سابقه‌ای در گردش کالا ثبت نشده است.");
        return;

    }

    let totalIn = 0;
    let totalOut = 0;
    let countIn = 0;
    let countOut = 0;

    const reasonTotals = {};

    inventoryMovements.forEach(function(m) {

        const qty = Number(m.quantity || 0);

        if (m.type === "in") {

            totalIn += qty;
            countIn++;

        } else if (m.type === "out") {

            totalOut += qty;
            countOut++;

        }

        const reason = m.reason || "سایر";

        reasonTotals[reason] =
            (reasonTotals[reason] || 0) + qty;

    });

    const reasonLines =
        Object.keys(reasonTotals)
            .map(function(r) {
                return "• " + r + ": " + formatInventoryNumber(reasonTotals[r]);
            })
            .join("\n");

    alert(

        "📊 گزارش گردش کالا\n\n" +

        "تعداد رویدادهای ورود: " + formatInventoryNumber(countIn) +
        " (جمع: " + formatInventoryNumber(totalIn) + ")\n" +

        "تعداد رویدادهای خروج: " + formatInventoryNumber(countOut) +
        " (جمع: " + formatInventoryNumber(totalOut) + ")\n\n" +

        "تفکیک بر اساس علت:\n" + (reasonLines || "—")

    );

}


function exportInventoryMovementsExcel() {

    if (
        !Array.isArray(inventoryMovements) ||
        inventoryMovements.length === 0
    ) {

        alert("⚠️ هنوز هیچ سابقه‌ای برای خروجی گرفتن وجود ندارد.");

        return;
    }


    function escapeHTML(value) {

        if (
            value === null ||
            value === undefined
        ) {

            return "";

        }

        return String(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");

    }


    function numberFormat(value) {

        const number =
            Number(value || 0);

        if (isNaN(number)) {

            return "0";

        }

        return number.toLocaleString("en-US");

    }


    let html = `
<!DOCTYPE html>

<html
    xmlns:o="urn:schemas-microsoft-com:office:office"
    xmlns:x="urn:schemas-microsoft-com:office:excel"
    xmlns="http://www.w3.org/TR/REC-html40"
>

<head>

<meta charset="UTF-8">

<meta http-equiv="Content-Type"
      content="text/html; charset=UTF-8">

<style>

body {

    font-family: Tahoma, Arial, sans-serif;

    direction: rtl;

}

table {

    border-collapse: collapse;

    width: 100%;

    direction: rtl;

}

th {

    background: #0fa37f;

    color: #fff;

    border: 1px solid #087f5b;

    padding: 10px;

    font-weight: bold;

    text-align: center;

}

td {

    border: 1px solid #ddd;

    padding: 8px;

    text-align: center;

}

.in {

    color: #198754;

    font-weight: bold;

}

.out {

    color: #dc3545;

    font-weight: bold;

}

.number {

    mso-number-format: "#,##0";

}

.text {

    mso-number-format: "\\@";

}

</style>

</head>

<body>

<table>

<thead>

<tr>

    <th>نوع گردش</th>

    <th>کد کالا</th>

    <th>شرح کالا</th>

    <th>تعداد</th>

    <th>تاریخ</th>

    <th>علت</th>

    <th>شماره سند</th>

    <th>موجودی قبل</th>

    <th>موجودی بعد</th>

    <th>توضیحات</th>

    <th>زمان ثبت</th>

</tr>

</thead>

<tbody>
`;


    [...inventoryMovements]
        .reverse()
        .forEach(function(movement) {

            const typeText =
                movement.type === "in"
                    ? "ورود"
                    : "خروج";


            html += `

<tr>

    <td class="${
        movement.type === "in"
            ? "in"
            : "out"
    }">

        ${typeText}

    </td>


    <td class="text">

        ${escapeHTML(
            movement.itemCode || ""
        )}

    </td>


    <td>

        ${escapeHTML(
            movement.itemName || ""
        )}

    </td>


    <td class="number">

        ${numberFormat(
            movement.quantity
        )}

    </td>


    <td class="text">

        ${escapeHTML(
            movement.date || ""
        )}

    </td>


    <td>

        ${escapeHTML(
            movement.reason || ""
        )}

    </td>


    <td class="text">

        ${escapeHTML(
            movement.document || ""
        )}

    </td>


    <td class="number">

        ${numberFormat(
            movement.stockBefore
        )}

    </td>


    <td class="number">

        ${numberFormat(
            movement.stockAfter
        )}

    </td>


    <td>

        ${escapeHTML(
            movement.notes || ""
        )}

    </td>


    <td class="text">

        ${escapeHTML(
            movement.createdAt || ""
        )}

    </td>

</tr>

`;

        });


    html += `

</tbody>

</table>

</body>

</html>
`;


    const blob =
        new Blob(
            [
                "\uFEFF",
                html
            ],
            {
                type:
                    "application/vnd.ms-excel;charset=utf-8"
            }
        );


    const url =
        URL.createObjectURL(blob);


    const link =
        document.createElement("a");


    link.href = url;


    link.download =
        "STLP-سوابق-گردش-انبار.xls";


    document.body.appendChild(link);

    link.click();

    document.body.removeChild(link);


    setTimeout(function() {

        URL.revokeObjectURL(url);

    }, 1000);


    alert(
        "✅ خروجی Excel سوابق گردش انبار ساخته شد."
    );

}
// =====================================================
// حذف سابقه گردش انبار
// =====================================================





async function deleteInventoryMovement(id) {

    if (!Array.isArray(inventoryMovements)) {
        inventoryMovements = [];
    }


    const index =
        inventoryMovements.findIndex(function(movement) {

            return String(movement.id) === String(id);

        });


    if (index === -1) {

        alert("❌ سابقه موردنظر پیدا نشد.");

        return;

    }


    const movement =
        inventoryMovements[index];


    // با کدِ کالا پیدا می‌شود، نه اندیسِ ذخیره‌شده روی خودِ سابقه —
    // آن اندیس با هر حذف/جابه‌جاییِ بعدیِ آرایه‌ی کالاها بی‌اعتبار
    // می‌شد و می‌توانست موجودیِ یک کالای کاملاً نامرتبط را عوض کند
    const item =
        inventoryItems.find(function(i) { return i.code === movement.itemCode; });


    if (!item) {

        alert("❌ کالای مربوط به این سابقه پیدا نشد.");

        return;

    }


    const confirmed =
        confirm(
            "⚠️ آیا از حذف این سابقه مطمئن هستید؟\n\n" +

            "کالا: " +
            (movement.itemName || "-") +

            "\nنوع: " +
            (
                movement.type === "in"
                    ? "ورود"
                    : "خروج"
            ) +

            "\nتعداد: " +
            formatInventoryNumber(
                movement.quantity || 0
            )
        );


    if (!confirmed) return;

    // حذفِ یک سابقه، موجودیِ کالا را هم دست می‌زند — فقط با رمزِ مدیر
    if (!(await stlpConfirmAdminPassword("حذفِ سابقه‌ی گردشِ انبار"))) return;


    const quantity =
        Number(movement.quantity || 0);


    const currentStock =
        Number(item.stock || 0);


    // =================================================
    // برگرداندن اثر گردش روی موجودی
    // =================================================

    if (movement.type === "in") {

        item.stock =
            currentStock - quantity;

    }

    else if (movement.type === "out") {

        item.stock =
            currentStock + quantity;

    }


    if (item.stock < 0) {

        item.stock = 0;

    }


    // حذف سابقه (اندیس بعد از پنجره‌ی رمز تازه پیدا می‌شود)

    const indexNow =
        inventoryMovements.findIndex(function(m) { return String(m.id) === String(id); });

    if (indexNow >= 0) inventoryMovements.splice(indexNow, 1);


    // ذخیره

    saveInventory();

    saveInventoryMovements();

    stlpLogActivity("انبار", "حذف گردش انبار", (movement.itemName || movement.itemCode || "-") + " — " + (movement.type === "in" ? "ورود" : "خروج") + " " + formatInventoryNumber(movement.quantity));


    // بروزرسانی

    renderInventory();

    updateInventoryStats();

    updateInventoryTodayStats();

    renderInventoryMovements();


    alert(
        "✅ سابقه حذف شد و موجودی اصلاح شد."
    );

}


// =====================================================
// ویرایش سابقه گردش انبار
// =====================================================


async function editInventoryMovement(id) {

    if (!Array.isArray(inventoryMovements)) {

        inventoryMovements = [];

    }


    const index =
        inventoryMovements.findIndex(
            function(movement) {

                return String(movement.id)
                    ===
                    String(id);

            }
        );


    if (index === -1) {

        alert(
            "❌ سابقه موردنظر پیدا نشد."
        );

        return;

    }


    const movement =
        inventoryMovements[index];


    const item =
        inventoryItems.find(function(i) { return i.code === movement.itemCode; });


    if (!item) {

        alert(
            "❌ کالای مربوط به این سابقه پیدا نشد."
        );

        return;

    }


    // =================================================
    // اطلاعات جدید
    // =================================================

    const newQuantity =
        prompt(
            "تعداد جدید:",
            movement.quantity
        );


    if (newQuantity === null) return;


    const quantity =
        Number(newQuantity);


    if (
        !Number.isFinite(quantity) ||
        quantity <= 0
    ) {

        alert(
            "❌ تعداد وارد شده نامعتبر است."
        );

        return;

    }


    const newDate =
        prompt(
            "تاریخ جدید:",
            movement.date || ""
        );


    if (newDate === null) return;


    const newReason =
        prompt(
            "علت جدید:",
            movement.reason || ""
        );


    if (newReason === null) return;


    const newDocument =
        prompt(
            "شماره سند / فاکتور:",
            movement.document || ""
        );


    if (newDocument === null) return;


    const newNotes =
        prompt(
            "توضیحات:",
            movement.notes || ""
        );


    if (newNotes === null) return;

    // ویرایشِ یک سابقه موجودیِ کالا را هم عوض می‌کند — فقط با رمزِ مدیر
    if (!(await stlpConfirmAdminPassword("ویرایشِ سابقه‌ی گردشِ انبار"))) return;


    // =================================================
    // بازگرداندن اثر قبلی
    // =================================================

    const oldQuantity =
        Number(
            movement.quantity || 0
        );


    const currentStock =
        Number(item.stock || 0);


    if (
        movement.type === "in"
    ) {

        // اگر بخشی از این ورود قبلاً فروخته/خارج شده، برگرداندنش
        // موجودی را منفی می‌کرد و دیگر خروجی هم رد نمی‌شد
        if (currentStock - oldQuantity < 0) {
            alert("❌ بخشی از این ورود قبلاً مصرف/فروخته شده؛ ویرایشش موجودی را منفی می‌کند.");
            return;
        }

        item.stock =
            currentStock - oldQuantity;

    }

    else if (
        movement.type === "out"
    ) {

        item.stock =
            currentStock + oldQuantity;

    }


    // =================================================
    // اعمال اثر جدید
    // =================================================

    const stockBefore =
        Number(item.stock || 0);


    if (
        movement.type === "out"
    ) {

        if (
            quantity > stockBefore
        ) {

            alert(

                "❌ موجودی کافی نیست.\n\n" +

                "موجودی پس از اصلاح: " +

                formatInventoryNumber(
                    stockBefore
                ) +

                "\nمقدار خروج جدید: " +

                formatInventoryNumber(
                    quantity
                )

            );


            // موجودی را دقیقاً به مقدارِ پیش از شروعِ ویرایش برمی‌گردانیم.
            // قبلاً این‌جا stockBefore+quantity گذاشته می‌شد (یک عددِ
            // بی‌ربط که موجودی را بدونِ هیچ دلیلی بالا می‌برد و با اولین
            // saveInventory ماندگار می‌شد)
            item.stock = currentStock;

            return;

        }


        item.stock =
            stockBefore - quantity;

    }

    else {

        item.stock =
            stockBefore + quantity;

    }


    // =================================================
    // بروزرسانی رکورد
    // =================================================

    movement.quantity =
        quantity;


    movement.date =
        newDate;


    movement.reason =
        newReason;


    movement.document =
        newDocument.trim();


    movement.notes =
        newNotes.trim();


    movement.stockBefore =
        stockBefore;


    movement.stockAfter =
        Number(item.stock || 0);


    movement.editedAt =
        new Date().toISOString();


    // =================================================
    // ذخیره
    // =================================================

    saveInventory();

    saveInventoryMovements();

    stlpLogActivity("انبار", "ویرایش گردش انبار", (movement.itemName || movement.itemCode || "-") + " — " + (movement.type === "in" ? "ورود" : "خروج") + " " + formatInventoryNumber(movement.quantity));


    // =================================================
    // بروزرسانی صفحه
    // =================================================

    renderInventory();

    updateInventoryStats();

    updateInventoryTodayStats();

    renderInventoryMovements();


    alert(
        "✅ سابقه با موفقیت ویرایش شد و موجودی اصلاح شد."
    );

}



